    /**
     * Extrahiert den Programmtag aus der URI (Query-Parameter ?typ=...)
     */
    private String extractProgrammTyp(String uri) {
        if (uri.contains("?")) {
            String query = uri.substring(uri.indexOf("?") + 1);
            String[] params = query.split("&");
            for (String param : params) {
                if (param.startsWith("typ=")) {
                    String typ = param.substring(4);
                    // Validiere den Typ
                    if (typ.equals("normal") || typ.equals("festtag_variabel") || 
                        typ.equals("festtag_fest") || typ.equals("benutzer")) {
                        return typ;
                    }
                }
            }
        }
        return null; // Kein Typ angegeben, verwende Standard
    }
    
