    /**
     * Liest Soforttasten-Namen aus der DB (beschriftung_tasten, c1 = "Sofort Start"), sortiert nach zeile_index.
     * Index 0, 1, 2, … entspricht sofort_melodie_0, sofort_melodie_1, …
     */
    private java.util.List<String> getSofortStartTastenNames() {
        java.util.List<String> names = new java.util.ArrayList<>();
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.BeschriftungTastenRow> rows = dbHelper.getBeschriftungTasten();
            for (PlatinenDatabaseHelper.BeschriftungTastenRow r : rows) {
                String funktion = r.c1 != null ? r.c1.trim() : "";
                if (!"Sofort Start".equalsIgnoreCase(funktion)) continue;
                String name = r.c2 != null ? r.c2.trim() : "";
                names.add(name.isEmpty() ? ("Soforttaste " + (names.size() + 1)) : name);
            }
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Lesen der Soforttasten aus DB", e);
        }
        return names;
    }

    /**
     * Liefert nur Soforttasten, deren Taste in der Beschriftung die Funktion "Sofort Start" hat.
     * Index 0 = erste Sofort-Start-Taste, 1 = zweite, … (sofort_melodie_0, sofort_melodie_1, …).
     */
    private SimpleHttpServer.HttpResponse handleGetSoforttasten() {
        try {
            java.util.List<String> sofortStartNames = getSofortStartTastenNames();
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            java.util.List<Map<String, Object>> list = new java.util.ArrayList<>();
            for (int i = 0; i < sofortStartNames.size(); i++) {
                Map<String, Object> item = new HashMap<>();
                item.put("index", i);
                item.put("tasteName", sofortStartNames.get(i));
                String melodieName = dbHelper.getConfigValue("sofort_melodie_" + i);
                item.put("melodieName", melodieName != null ? melodieName.trim() : "");
                String startzeit = dbHelper.getConfigValue("sofort_startzeit_" + i);
                item.put("startzeit", startzeit != null ? startzeit.trim() : "");
                list.add(item);
            }
            String json = gson.toJson(list);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Lesen der Soforttasten", e);
            String errorJson = "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    private SimpleHttpServer.HttpResponse handlePutSoforttaste(int index, SimpleHttpServer.HttpRequest request) {
        if (index < 0 || index >= SOFORTTASTEN_MAX) {
            String errorJson = "{\"error\":\"Index außerhalb 0.." + (SOFORTTASTEN_MAX - 1) + "\"}";
            return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
        }
        try {
            Map<?, ?> body = null;
            if (request != null && request.body != null && !request.body.trim().isEmpty()) {
                try {
                    body = gson.fromJson(request.body, Map.class);
                } catch (Exception ignored) { }
            }
            if (body == null) body = new HashMap<>();
            String melodieName = body.containsKey("melodieName") ? String.valueOf(body.get("melodieName")) : "";
            if (melodieName == null || "null".equals(melodieName)) melodieName = "";
            melodieName = melodieName.trim().replaceAll("\\s+", " ").trim();
            String configKey = "sofort_melodie_" + index;
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.setConfigValue(configKey, melodieName);
            String readBack = dbHelper.getConfigValue(configKey);
            Log.d(TAG, "Soforttaste " + index + " gespeichert: key=" + configKey + " melodieName=\"" + melodieName + "\" readBack=\"" + (readBack != null ? readBack : "null") + "\"");
            if (readBack != null && !readBack.equals(melodieName)) {
                Log.w(TAG, "Soforttaste " + index + " Readback abweichend: erwartet \"" + melodieName + "\" gelesen \"" + readBack + "\"");
            }
            Map<String, Object> resp = new HashMap<>();
            resp.put("success", true);
            resp.put("index", index);
            resp.put("melodieName", melodieName);
            String json = gson.toJson(resp);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Speichern der Soforttaste " + index, e);
            String errorJson = "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

    /** PUT /api/soforttasten/:index/startzeit – Startzeit setzen oder leeren (Body: { "startzeit": "HH:mm" oder "" }). */
    private SimpleHttpServer.HttpResponse handlePutSoforttasteStartzeit(int index, SimpleHttpServer.HttpRequest request) {
        if (index < 0 || index >= SOFORTTASTEN_MAX) {
            return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Index außerhalb 0.." + (SOFORTTASTEN_MAX - 1) + "\"}");
        }
        try {
            String startzeit = "";
            if (request != null && request.body != null && !request.body.trim().isEmpty()) {
                try {
                    Map<?, ?> body = gson.fromJson(request.body, Map.class);
                    if (body != null && body.containsKey("startzeit")) {
                        String v = String.valueOf(body.get("startzeit"));
                        if (v != null && !"null".equals(v)) startzeit = v.trim();
                    }
                } catch (Exception ignored) { }
            }
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.setConfigValue("sofort_startzeit_" + index, startzeit);
            Map<String, Object> resp = new HashMap<>();
            resp.put("success", true);
            resp.put("index", index);
            resp.put("startzeit", startzeit);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(resp));
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Setzen der Startzeit Soforttaste " + index, e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "'") : "") + "\"}");
        }
    }

    /** c1 (Tastentyp): null/leer → "Leer", literal "NULL" bleibt "NULL", sonst getrimmter Wert. (Einheitlich "Leer" damit App-Seiten Leer-Zellen zuverlässig ausblenden.) */
    private static String normNullToLeer(String v) {
        if (v == null) return "Leer";
        String s = v.trim();
        if (s.isEmpty()) return "Leer";
        if ("null".equalsIgnoreCase(s)) return "NULL"; // NULL-Vorlage erhalten, nicht in Leer überschreiben
        return s;
    }

    /** c2/c3: "NULL"/"null" oder leer → "", sonst getrimmter Wert. */
    private static String normNullToEmpty(String v) {
        if (v == null) return "";
        String s = v.trim();
        if (s.isEmpty() || "null".equalsIgnoreCase(s)) return "";
        return s;
    }

    /** Liefert die Liste der Sound-Dateien im Ordner Turmtechnik/Sound/ (für Dropdown in Tasten-Config). */
    private SimpleHttpServer.HttpResponse handleGetSoundFiles() {
        try {
            String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
            File soundDir = new File(sdCardPath + "/Turmtechnik/Sound");
            java.util.List<String> files = new java.util.ArrayList<>();
            if (soundDir.exists() && soundDir.isDirectory()) {
                File[] list = soundDir.listFiles();
                if (list != null) {
                    for (File f : list) {
                        if (f.isFile()) {
                            String name = f.getName();
                            String lower = name.toLowerCase();
                            if (lower.endsWith(".mp3") || lower.endsWith(".wav") || lower.endsWith(".ogg")) {
                                files.add(name);
                            }
                        }
                    }
                    java.util.Collections.sort(files);
                }
            }
            Map<String, Object> out = new HashMap<>();
            out.put("files", files);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(out));
        } catch (Exception e) {
            Log.e(TAG, "Sound-Dateien auflisten fehlgeschlagen", e);
            Map<String, Object> out = new HashMap<>();
            out.put("files", new java.util.ArrayList<String>());
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(out));
        }
    }

    private SimpleHttpServer.HttpResponse handleGetBeschriftungTasten() {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.BeschriftungTastenRow> rows = dbHelper.getBeschriftungTasten();
            java.util.List<Map<String, Object>> list = new java.util.ArrayList<>();
            int sofortIndex = 0;
            for (PlatinenDatabaseHelper.BeschriftungTastenRow r : rows) {
                Map<String, Object> item = new HashMap<>();
                item.put("id", r.id);
                item.put("zeile_index", r.zeileIndex);
                boolean isNullRow = r.c1 != null && r.c1.trim().equalsIgnoreCase("null");
                if (isNullRow) {
                    item.put("c1", "NULL");
                    item.put("c2", "NULL");
                    item.put("c3", "NULL");
                    item.put("c4", "NULL");
                    item.put("c5", "NULL");
                    item.put("c13", "NULL");
                } else {
                    item.put("c1", normNullToLeer(r.c1));
                    item.put("c2", normNullToEmpty(r.c2));
                    item.put("c3", normNullToEmpty(r.c3));
                    item.put("c4", r.c4 != null ? r.c4 : "");
                    item.put("c5", r.c5 != null ? r.c5 : "");
                    item.put("c13", r.c13 != null ? r.c13 : "");
                }
                item.put("c6", r.c6);
                item.put("c7", r.c7);
                item.put("c8", r.c8);
                item.put("c9", r.c9);
                item.put("c10", r.c10);
                item.put("sonder_id", r.sonderId);
                item.put("sound", r.sound != null ? r.sound : "");
                if ("Sofort Start".equalsIgnoreCase(r.c1 != null ? r.c1.trim() : "")) {
                    String melodieName = dbHelper.getConfigValue("sofort_melodie_" + sofortIndex);
                    item.put("sofort_melodie", melodieName != null ? melodieName.trim() : "");
                    String startzeit = dbHelper.getConfigValue("sofort_startzeit_" + sofortIndex);
                    item.put("sofort_startzeit", startzeit != null ? startzeit.trim() : "");
                    sofortIndex++;
                }
                list.add(item);
            }
            // Auf mindestens 48 Slots auff\u00fcllen, damit App-Seite 2 (Indizes 24\u201347) immer Zellen und Klick-Handler bekommt
            final int APP_GRID_SLOTS = 48;
            while (list.size() < APP_GRID_SLOTS) {
                Map<String, Object> empty = new HashMap<>();
                empty.put("c1", "Leer");
                empty.put("c2", "");
                empty.put("c3", "");
                empty.put("c4", "");
                empty.put("c5", "");
                empty.put("c13", "");
                empty.put("sonder_id", (Object) null);
                empty.put("sound", "");
                list.add(empty);
            }
            String json = gson.toJson(list);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Lesen der Beschriftung-Tasten", e);
            String errorJson = "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

    /**
     * Importiert Beschriftung-Tasten aus der Excel-Datei im Config-Ordner des Geräts (wie Tagtypen/Programme).
     * Pfad: /Turmtechnik/Config/Beschriftung-Tasten.xls
     */
    private SimpleHttpServer.HttpResponse handlePostBeschriftungTastenImportFromDevice() {
        try {
            String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
            java.io.File excelFile = new java.io.File(sdCardPath + "/Turmtechnik/Config/Beschriftung-Tasten.xls");
            if (!excelFile.exists() || !excelFile.canRead()) {
                String errorJson = "{\"error\":\"Datei nicht gefunden oder nicht lesbar: Turmtechnik/Config/Beschriftung-Tasten.xls auf dem Gerät. Bitte die Datei in diesen Ordner legen.\"}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", errorJson);
            }
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            int count = dbHelper.importBeschriftungTastenFromExcel(excelFile.getAbsolutePath());
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", count > 0);
            result.put("count", count);
            String msg = count > 0 ? (count + " Tasten aus Excel importiert.") : "Import fehlgeschlagen. Bitte eine gültige .xls-Datei (altes Excel-Format) verwenden.";
            result.put("message", msg);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(result));
        } catch (Exception e) {
            Log.e(TAG, "Beschriftung-Tasten Import vom Gerät fehlgeschlagen", e);
            String errorJson = "{\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "'") : "Import fehlgeschlagen") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

