    /** Datenbank-Datei als Download (Sicherung) ausliefern. Dateiname enthält Baustellennamen. */
    private SimpleHttpServer.HttpResponse handleGetBackup() {
        try {
            File dbFile = context.getDatabasePath("turmtechnik_config.db");
            if (dbFile == null || !dbFile.exists()) {
                return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Datenbankdatei nicht gefunden\"}");
            }
            FileInputStream fis = new FileInputStream(dbFile);
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int n;
            while ((n = fis.read(buf)) != -1) {
                baos.write(buf, 0, n);
            }
            fis.close();
            byte[] bytes = baos.toByteArray();
            String backupFilename = buildBackupFilename();
            SimpleHttpServer.HttpResponse resp = new SimpleHttpServer.HttpResponse(200, "application/octet-stream", "");
            resp.bodyBytes = bytes;
            resp.headers.put("Content-Disposition", "attachment; filename=\"" + backupFilename + "\"");
            return resp;
        } catch (Exception e) {
            Log.e(TAG, "Backup fehlgeschlagen", e);
            String errorJson = "{\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "'") : "Backup fehlgeschlagen") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

    /** Erzeugt Backup-Dateinamen mit Baustellennamen und Datum (z. B. turmtechnik_config_Kirche_Musterstadt_2025-01-27.db). */
    private String buildBackupFilename() {
        PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
        String baustelle = dbHelper.getConfigValue("anlage_baustelle_name");
        String installDatum = dbHelper.getConfigValue("anlage_installationsdatum");
        String datePart = (installDatum != null && !installDatum.trim().isEmpty()) ? installDatum.trim() : new java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.GERMANY).format(new java.util.Date());
        if (datePart.length() > 10) datePart = datePart.substring(0, 10);
        datePart = datePart.replaceAll("[^0-9\\-]", "-");
        String namePart = "turmtechnik_config";
        if (baustelle != null && !baustelle.trim().isEmpty()) {
            String safe = baustelle.trim().replaceAll("[^a-zA-Z0-9\u00C4\u00E4\u00D6\u00F6\u00DC\u00FC\u00DF\\- ]", "").replaceAll("\\s+", "_").replaceAll("_+", "_");
            if (safe.length() > 50) safe = safe.substring(0, 50);
            if (!safe.isEmpty()) namePart = namePart + "_" + safe;
        }
        return namePart + "_" + datePart + ".db";
    }

    /** Query-Parameter aus URI lesen (z. B. path=Config%2Ffile.xls → Config/file.xls). */
    private static String getQueryParam(String uri, String key) {
        if (uri == null || !uri.contains("?")) return null;
        String query = uri.substring(uri.indexOf("?") + 1);
        for (String param : query.split("&")) {
            int eq = param.indexOf("=");
            if (eq > 0 && key.equals(param.substring(0, eq).trim())) {
                String value = param.substring(eq + 1).trim();
                try {
                    return java.net.URLDecoder.decode(value, StandardCharsets.UTF_8.name());
                } catch (Exception e) {
                    return value;
                }
            }
        }
        return null;
    }

    /** Basis-Pfad des Turmtechnik-Ordners auf dem Gerät (z. B. /storage/emulated/0/Turmtechnik). */
    private static File getTurmtechnikBaseDir() {
        String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
        return new File(sdCardPath + "/Turmtechnik");
    }

    /** Wurzel für Datei-Transfer-Navigation: gesamter externer Speicher (alle Ordner durchsuchbar). */
    private static File getFileTransferRoot() {
        return android.os.Environment.getExternalStorageDirectory();
    }

    /** Maximale Anzahl Dateien in der Liste (Schutz vor zu großer Antwort). */
    private static final int TURMTECHNIK_FILES_LIST_LIMIT = 2000;
    /** Maximale ZIP-Größe in Bytes (ca. 200 MB). */
    private static final long TURMTECHNIK_ZIP_MAX_BYTES = 200L * 1024 * 1024;

    /** GET /api/turmtechnik-files – Liste aller Dateien/Ordner im Turmtechnik-Ordner (relativer Pfad, Größe, dir). */
    private SimpleHttpServer.HttpResponse handleGetTurmtechnikFilesList() {
        try {
            File base = getTurmtechnikBaseDir();
            if (!base.exists() || !base.isDirectory()) {
                return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"basePath\":\"" + escapeJsonString(base.getAbsolutePath()) + "\",\"files\":[],\"message\":\"Ordner nicht vorhanden\"}");
            }
            List<Map<String, Object>> files = new ArrayList<>();
            collectTurmtechnikFiles(base, "", files, TURMTECHNIK_FILES_LIST_LIMIT);
            Map<String, Object> out = new HashMap<>();
            out.put("basePath", base.getAbsolutePath());
            out.put("files", files);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(out));
        } catch (Exception e) {
            Log.e(TAG, "turmtechnik-files list fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    private void collectTurmtechnikFiles(File dir, String relativePrefix, List<Map<String, Object>> out, int limit) {
        if (out.size() >= limit) return;
        File[] children = dir.listFiles();
        if (children == null) return;
        for (File f : children) {
            if (out.size() >= limit) break;
            String rel = relativePrefix.isEmpty() ? f.getName() : (relativePrefix + "/" + f.getName());
            Map<String, Object> entry = new HashMap<>();
            entry.put("path", rel);
            entry.put("dir", f.isDirectory());
            if (!f.isDirectory()) entry.put("size", f.length());
            out.add(entry);
            if (f.isDirectory()) collectTurmtechnikFiles(f, rel, out, limit);
        }
    }

    /** Max. Dateigröße für Datei-Transfer Download/Upload (100 MB, wie Restore). */
    private static final long FILE_TRANSFER_MAX_SIZE_BYTES = 100L * 1024 * 1024;

    /**
     * Validiert einen relativen Pfad unter dem Speicher-Stamm (externer Speicher, alle Ordner durchsuchbar, kein Path-Traversal).
     * @param relativePath relativer Pfad (z. B. "" = Wurzel, "Turmtechnik", "Download", "Turmtechnik/Config")
     * @param mustExist wenn true, liefert nur dann ein File, wenn es existiert
     * @return File unter Speicher-Stamm, oder null bei ungültigem Pfad
     */
    private File resolveAndValidateFileTransferPath(String relativePath, boolean mustExist) {
        if (relativePath == null) relativePath = "";
        relativePath = relativePath.trim().replace('\\', '/');
        if (relativePath.contains("..")) return null;
        while (relativePath.startsWith("/")) relativePath = relativePath.substring(1);
        File base = getFileTransferRoot();
        File resolved = relativePath.isEmpty() ? base : new File(base, relativePath);
        try {
            String canonicalResolved = resolved.getCanonicalPath();
            String canonicalBase = base.getCanonicalPath();
            if (!canonicalResolved.equals(canonicalBase) && !canonicalResolved.startsWith(canonicalBase + File.separator)) {
                return null;
            }
            if (mustExist && !resolved.exists()) return null;
            return resolved;
        } catch (IOException e) {
            return null;
        }
    }

    /** GET /api/file-transfer/list?path=... – Eine Verzeichnisebene (Ordner + Dateien). */
    private SimpleHttpServer.HttpResponse handleGetFileTransferList(String relativePath) {
        File dir = resolveAndValidateFileTransferPath(relativePath, true);
        if (dir == null || !dir.isDirectory()) {
            return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Ordner nicht gefunden oder ungültiger Pfad\"}");
        }
        try {
            File[] children = dir.listFiles();
            List<Map<String, Object>> entries = new ArrayList<>();
            if (children != null) {
                for (File f : children) {
                    Map<String, Object> entry = new HashMap<>();
                    entry.put("name", f.getName());
                    entry.put("dir", f.isDirectory());
                    if (!f.isDirectory()) entry.put("size", f.length());
                    entries.add(entry);
                }
            }
            Map<String, Object> out = new HashMap<>();
            out.put("path", relativePath);
            out.put("entries", entries);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(out));
        } catch (Exception e) {
            Log.e(TAG, "file-transfer list fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /** GET /api/file-transfer/download?path=... – Datei herunterladen (max 100 MB). */
    private SimpleHttpServer.HttpResponse handleGetFileTransferDownload(String relativePath) {
        if (relativePath == null || relativePath.trim().isEmpty()) {
            return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Parameter path fehlt\"}");
        }
        File file = resolveAndValidateFileTransferPath(relativePath.trim(), true);
        if (file == null || !file.isFile()) {
            return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Datei nicht gefunden\"}");
        }
        try {
            long len = file.length();
            if (len > FILE_TRANSFER_MAX_SIZE_BYTES) {
                return new SimpleHttpServer.HttpResponse(413, "application/json", "{\"error\":\"Datei zu groß (max. 100 MB)\"}");
            }
            FileInputStream fis = new FileInputStream(file);
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int n;
            while ((n = fis.read(buf)) != -1) baos.write(buf, 0, n);
            fis.close();
            byte[] bytes = baos.toByteArray();
            String filename = file.getName();
            String contentType = "application/octet-stream";
            String nameLower = filename.toLowerCase();
            if (nameLower.endsWith(".txt")) contentType = "text/plain; charset=UTF-8";
            else if (nameLower.endsWith(".html")) contentType = "text/html; charset=UTF-8";
            else if (nameLower.endsWith(".json")) contentType = "application/json";
            else if (nameLower.endsWith(".xls")) contentType = "application/vnd.ms-excel";
            SimpleHttpServer.HttpResponse resp = new SimpleHttpServer.HttpResponse(200, contentType, "");
            resp.bodyBytes = bytes;
            resp.headers.put("Content-Disposition", "attachment; filename=\"" + filename.replace("\"", "\\\"") + "\"");
            return resp;
        } catch (Exception e) {
            Log.e(TAG, "file-transfer download fehlgeschlagen: " + relativePath, e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /** POST /api/file-transfer/upload – Multipart: path (relativer Ordner), file (Datei). */
    private SimpleHttpServer.HttpResponse handlePostFileTransferUpload(SimpleHttpServer.HttpRequest request) {
        try {
            String contentType = null;
            for (Map.Entry<String, String> entry : request.headers.entrySet()) {
                if (entry.getKey().equalsIgnoreCase("content-type")) {
                    contentType = entry.getValue();
                    break;
                }
            }
            if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Content-Type muss multipart/form-data sein\"}");
            }
            byte[] bodyBytes = request.bodyBytes;
            if (bodyBytes == null || bodyBytes.length == 0) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Keine Datei-Daten empfangen\"}");
            }
            if (bodyBytes.length > FILE_TRANSFER_MAX_SIZE_BYTES) {
                return new SimpleHttpServer.HttpResponse(413, "application/json", "{\"error\":\"Datei zu groß (max. 100 MB)\"}");
            }
            String boundary = null;
            if (contentType.contains("boundary=")) {
                int boundaryStart = contentType.indexOf("boundary=") + 9;
                String boundaryValue = contentType.substring(boundaryStart).trim();
                if (boundaryValue.contains("\r")) boundaryValue = boundaryValue.substring(0, boundaryValue.indexOf("\r"));
                if (boundaryValue.contains("\n")) boundaryValue = boundaryValue.substring(0, boundaryValue.indexOf("\n"));
                if (boundaryValue.startsWith("\"") && boundaryValue.endsWith("\"")) {
                    boundaryValue = boundaryValue.substring(1, boundaryValue.length() - 1);
                }
                boundary = "--" + boundaryValue;
            }
            if (boundary == null) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Boundary nicht gefunden\"}");
            }
            byte[] boundaryBytes = boundary.getBytes("ISO-8859-1");
            String uploadPath = "";
            String fileName = null;
            byte[] fileData = null;
            int i = 0;
            while (i < bodyBytes.length) {
                int boundaryIdx = indexOf(bodyBytes, boundaryBytes, i);
                if (boundaryIdx < 0) break;
                int partStart = boundaryIdx + boundaryBytes.length;
                if (partStart >= bodyBytes.length) break;
                if (bodyBytes[partStart] == '\r') partStart += 2;
                else if (bodyBytes[partStart] == '\n') partStart += 1;
                int nextBoundary = indexOf(bodyBytes, boundaryBytes, partStart);
                int partEnd = nextBoundary >= 0 ? nextBoundary : bodyBytes.length;
                String partHeader = new String(bodyBytes, partStart, Math.min(partEnd - partStart, 1024), "ISO-8859-1");
                int headerEnd = partHeader.indexOf("\r\n\r\n");
                if (headerEnd < 0) headerEnd = partHeader.indexOf("\n\n");
                if (headerEnd >= 0) {
                    int dataStart = partStart + headerEnd + (partHeader.contains("\r\n\r\n") ? 4 : 2);
                    int dataEnd = partEnd;
                    while (dataEnd > dataStart && (bodyBytes[dataEnd - 1] == '\n' || bodyBytes[dataEnd - 1] == '\r')) dataEnd--;
                    if (partHeader.contains("name=\"path\"")) {
                        uploadPath = new String(bodyBytes, dataStart, dataEnd - dataStart, "UTF-8").trim().replace('\\', '/');
                        while (uploadPath.startsWith("/")) uploadPath = uploadPath.substring(1);
                    } else if (partHeader.contains("name=\"file\"") || partHeader.contains("filename=")) {
                        if (partHeader.contains("filename=\"")) {
                            int fnStart = partHeader.indexOf("filename=\"") + 10;
                            int fnEnd = partHeader.indexOf("\"", fnStart);
                            if (fnEnd > fnStart) fileName = partHeader.substring(fnStart, fnEnd).trim();
                        }
                        if (fileName == null || fileName.isEmpty()) fileName = "upload";
                        fileData = new byte[dataEnd - dataStart];
                        System.arraycopy(bodyBytes, dataStart, fileData, 0, fileData.length);
                    }
                }
                i = partEnd;
            }
            if (fileName == null || fileData == null) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Keine Datei im Feld 'file' gefunden\"}");
            }
            File dir = resolveAndValidateFileTransferPath(uploadPath, true);
            if (dir == null || !dir.isDirectory()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Zielordner ungültig oder nicht vorhanden\"}");
            }
            File destFile = new File(dir, fileName);
            try {
                FileOutputStream fos = new FileOutputStream(destFile);
                fos.write(fileData);
                fos.close();
            } catch (IOException e) {
                Log.e(TAG, "file-transfer upload schreiben fehlgeschlagen", e);
                return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
            }
            String savedPath = uploadPath.isEmpty() ? fileName : (uploadPath + "/" + fileName);
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"path\":\"" + escapeJsonString(savedPath) + "\"}");
        } catch (Exception e) {
            Log.e(TAG, "file-transfer upload fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /** POST /api/file-transfer/copy – JSON body: { "fromPath": "relativer Pfad zur Datei", "toDir": "relativer Pfad zum Zielordner" }. Kopiert die Datei auf dem Gerät. */
    private SimpleHttpServer.HttpResponse handlePostFileTransferCopy(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Body fehlt (fromPath, toDir)\"}");
            }
            com.google.gson.JsonObject obj;
            try {
                obj = gson.fromJson(body, com.google.gson.JsonObject.class);
            } catch (Exception e) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Ungültiges JSON\"}");
            }
            if (obj == null || !obj.has("fromPath") || !obj.has("toDir")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"fromPath und toDir erforderlich\"}");
            }
            String fromPath = obj.has("fromPath") ? obj.get("fromPath").getAsString() : "";
            String toDir = obj.has("toDir") ? obj.get("toDir").getAsString() : "";
            File sourceFile = resolveAndValidateFileTransferPath(fromPath, true);
            if (sourceFile == null || !sourceFile.isFile()) {
                return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Quelldatei nicht gefunden oder ungültig\"}");
            }
            File destDir = resolveAndValidateFileTransferPath(toDir, true);
            if (destDir == null || !destDir.isDirectory()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Zielordner nicht gefunden oder ungültig\"}");
            }
            File destFile = new File(destDir, sourceFile.getName());
            FileInputStream fis = new FileInputStream(sourceFile);
            FileOutputStream fos = new FileOutputStream(destFile);
            byte[] buf = new byte[8192];
            int n;
            while ((n = fis.read(buf)) != -1) fos.write(buf, 0, n);
            fis.close();
            fos.close();
            String resultPath = toDir.isEmpty() ? sourceFile.getName() : (toDir + "/" + sourceFile.getName());
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"path\":\"" + escapeJsonString(resultPath) + "\"}");
        } catch (IOException e) {
            Log.e(TAG, "file-transfer copy fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        } catch (Exception e) {
            Log.e(TAG, "file-transfer copy fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /** DELETE /api/file-transfer/node?path=... – Datei oder leeren Ordner löschen. */
    private SimpleHttpServer.HttpResponse handleDeleteFileTransferNode(String relativePath) {
        if (relativePath == null || relativePath.trim().isEmpty()) {
            return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Parameter path fehlt\"}");
        }
        File node = resolveAndValidateFileTransferPath(relativePath.trim(), true);
        if (node == null) {
            return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Nicht gefunden oder ungültiger Pfad\"}");
        }
        try {
            if (node.isDirectory()) {
                File[] children = node.listFiles();
                if (children != null && children.length > 0) {
                    return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Ordner ist nicht leer. Bitte zuerst Inhalt löschen.\"}");
                }
            }
            if (!node.delete()) {
                return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"Löschen fehlgeschlagen\"}");
            }
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true}");
        } catch (Exception e) {
            Log.e(TAG, "file-transfer delete fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /** PUT /api/file-transfer/rename – JSON: { "path": "relativer Pfad", "newName": "neuer Name" }. */
    private SimpleHttpServer.HttpResponse handlePutFileTransferRename(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Body fehlt (path, newName)\"}");
            }
            com.google.gson.JsonObject obj = gson.fromJson(body, com.google.gson.JsonObject.class);
            if (obj == null || !obj.has("path") || !obj.has("newName")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"path und newName erforderlich\"}");
            }
            String path = obj.get("path").getAsString();
            String newName = obj.get("newName").getAsString().trim().replace('\\', '/');
            if (newName.isEmpty() || newName.contains("..") || newName.contains("/")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Ungültiger neuer Name\"}");
            }
            File node = resolveAndValidateFileTransferPath(path, true);
            if (node == null || !node.exists()) {
                return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Nicht gefunden\"}");
            }
            File parent = node.getParentFile();
            File dest = new File(parent != null ? parent : getFileTransferRoot(), newName);
            if (dest.exists()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Name existiert bereits\"}");
            }
            if (!node.renameTo(dest)) {
                return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"Umbenennen fehlgeschlagen\"}");
            }
            String parentRel = path.contains("/") ? path.substring(0, path.lastIndexOf('/')) : "";
            String resultPath = parentRel.isEmpty() ? newName : (parentRel + "/" + newName);
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"path\":\"" + escapeJsonString(resultPath) + "\"}");
        } catch (Exception e) {
            Log.e(TAG, "file-transfer rename fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /** POST /api/file-transfer/mkdir – JSON: { "parentPath": "relativer Pfad zum Elternordner", "name": "Ordnername" }. */
    private SimpleHttpServer.HttpResponse handlePostFileTransferMkdir(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Body fehlt (parentPath, name)\"}");
            }
            com.google.gson.JsonObject obj = gson.fromJson(body, com.google.gson.JsonObject.class);
            if (obj == null || !obj.has("parentPath") || !obj.has("name")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"parentPath und name erforderlich\"}");
            }
            String parentPath = obj.get("parentPath").getAsString();
            String name = obj.get("name").getAsString().trim().replace('\\', '/');
            if (name.isEmpty() || name.contains("..") || name.contains("/")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Ungültiger Ordnername\"}");
            }
            File parentDir = resolveAndValidateFileTransferPath(parentPath, true);
            if (parentDir == null || !parentDir.isDirectory()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Elternordner nicht gefunden\"}");
            }
            File newDir = new File(parentDir, name);
            if (newDir.exists()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Ordner existiert bereits\"}");
            }
            if (!newDir.mkdir()) {
                return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"Ordner anlegen fehlgeschlagen\"}");
            }
            String resultPath = parentPath.isEmpty() ? name : (parentPath + "/" + name);
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"path\":\"" + escapeJsonString(resultPath) + "\"}");
        } catch (Exception e) {
            Log.e(TAG, "file-transfer mkdir fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    private static int indexOf(byte[] source, byte[] target, int fromIndex) {
        if (target.length == 0) return fromIndex;
        for (int i = fromIndex; i <= source.length - target.length; i++) {
            boolean match = true;
            for (int j = 0; j < target.length; j++) {
                if (source[i + j] != target[j]) { match = false; break; }
            }
            if (match) return i;
        }
        return -1;
    }

    /** GET /api/turmtechnik-files/download?path=... – Einzeldatei aus Turmtechnik-Ordner herunterladen. */
    private SimpleHttpServer.HttpResponse handleGetTurmtechnikFileDownload(String relativePath) {
        if (relativePath == null || relativePath.trim().isEmpty()) {
            return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Parameter path fehlt\"}");
        }
        relativePath = relativePath.trim().replace('\\', '/');
        if (relativePath.contains("..")) {
            return new SimpleHttpServer.HttpResponse(403, "application/json", "{\"error\":\"Ungültiger Pfad\"}");
        }
        if (relativePath.startsWith("/")) relativePath = relativePath.substring(1);
        File base = getTurmtechnikBaseDir();
        File file = new File(base, relativePath);
        try {
            if (!file.exists() || !file.isFile()) {
                return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Datei nicht gefunden\"}");
            }
            if (!file.getCanonicalPath().startsWith(base.getCanonicalPath())) {
                return new SimpleHttpServer.HttpResponse(403, "application/json", "{\"error\":\"Ungültiger Pfad\"}");
            }
            FileInputStream fis = new FileInputStream(file);
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int n;
            while ((n = fis.read(buf)) != -1) baos.write(buf, 0, n);
            fis.close();
            byte[] bytes = baos.toByteArray();
            String filename = file.getName();
            SimpleHttpServer.HttpResponse resp = new SimpleHttpServer.HttpResponse(200, "application/octet-stream", "");
            resp.bodyBytes = bytes;
            resp.headers.put("Content-Disposition", "attachment; filename=\"" + filename + "\"");
            return resp;
        } catch (Exception e) {
            Log.e(TAG, "turmtechnik-files download fehlgeschlagen: " + relativePath, e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /** GET /api/turmtechnik-folder-zip – Gesamten Turmtechnik-Ordner als ZIP herunterladen. */
    private SimpleHttpServer.HttpResponse handleGetTurmtechnikFolderZip() {
        try {
            File base = getTurmtechnikBaseDir();
            if (!base.exists() || !base.isDirectory()) {
                return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Turmtechnik-Ordner nicht gefunden\"}");
            }
            ByteArrayOutputStream zipBaos = new ByteArrayOutputStream();
            java.util.zip.ZipOutputStream zos = new java.util.zip.ZipOutputStream(zipBaos);
            final long[] totalBytes = {0L};
            final boolean[] overflow = {false};
            collectFilesIntoZip(base, "", zos, totalBytes, overflow);
            zos.finish();
            zos.close();
            if (overflow[0]) {
                return new SimpleHttpServer.HttpResponse(413, "application/json", "{\"error\":\"ZIP zu groß (max. 200 MB)\"}");
            }
            byte[] zipBytes = zipBaos.toByteArray();
            String zipName = "Turmtechnik_Ordner_" + new java.text.SimpleDateFormat("yyyy-MM-dd_HH-mm", java.util.Locale.GERMANY).format(new java.util.Date()) + ".zip";
            SimpleHttpServer.HttpResponse resp = new SimpleHttpServer.HttpResponse(200, "application/zip", "");
            resp.bodyBytes = zipBytes;
            resp.headers.put("Content-Disposition", "attachment; filename=\"" + zipName + "\"");
            return resp;
        } catch (Exception e) {
            Log.e(TAG, "turmtechnik-folder-zip fehlgeschlagen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    private void collectFilesIntoZip(File dir, String zipPathPrefix, java.util.zip.ZipOutputStream zos, long[] totalBytes, boolean[] overflow) throws IOException {
        File[] children = dir.listFiles();
        if (children == null) return;
        for (File f : children) {
            if (overflow[0]) return;
            String entryName = zipPathPrefix.isEmpty() ? f.getName() : (zipPathPrefix + "/" + f.getName());
            if (f.isDirectory()) {
                entryName = entryName.endsWith("/") ? entryName : (entryName + "/");
                zos.putNextEntry(new java.util.zip.ZipEntry(entryName));
                zos.closeEntry();
                collectFilesIntoZip(f, entryName, zos, totalBytes, overflow);
            } else {
                if (totalBytes[0] + f.length() > TURMTECHNIK_ZIP_MAX_BYTES) {
                    overflow[0] = true;
                    return;
                }
                zos.putNextEntry(new java.util.zip.ZipEntry(entryName));
                FileInputStream fis = new FileInputStream(f);
                byte[] buf = new byte[8192];
                int n;
                while ((n = fis.read(buf)) != -1) {
                    zos.write(buf, 0, n);
                    totalBytes[0] += n;
                }
                fis.close();
                zos.closeEntry();
            }
        }
    }

    /** Maximale Größe der hochgeladenen .db-Datei beim Wiederherstellen (100 MB), um Speicherüberlauf zu vermeiden. */
    private static final int RESTORE_MAX_FILE_SIZE_BYTES = 100 * 1024 * 1024;

    /** Hochgeladene .db-Datei als Datenbank wiederherstellen (Import). */
    private SimpleHttpServer.HttpResponse handlePostRestore(SimpleHttpServer.HttpRequest request) {
        try {
            byte[] bodyBytes = request.bodyBytes;
            if (bodyBytes != null && bodyBytes.length > RESTORE_MAX_FILE_SIZE_BYTES) {
                return new SimpleHttpServer.HttpResponse(400, "application/json",
                    "{\"error\":\"Datei zu groß (max. 100 MB). Bitte kleinere Sicherung wählen oder Daten per Programm-Editor/Melodien-Editor einzeln importieren.\"}");
            }
            String contentType = null;
            for (java.util.Map.Entry<String, String> entry : request.headers.entrySet()) {
                if (entry.getKey().equalsIgnoreCase("content-type")) {
                    contentType = entry.getValue();
                    break;
                }
            }
            if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Content-Type muss multipart/form-data sein\"}");
            }
            if (bodyBytes == null || bodyBytes.length == 0) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Keine Datei-Daten empfangen\"}");
            }
            String boundary = null;
            if (contentType.contains("boundary=")) {
                String boundaryValue = contentType.substring(contentType.indexOf("boundary=") + 9).trim();
                if (boundaryValue.startsWith("\"") && boundaryValue.endsWith("\"")) {
                    boundaryValue = boundaryValue.substring(1, boundaryValue.length() - 1);
                }
                boundary = "--" + boundaryValue;
            }
            if (boundary == null) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Boundary nicht gefunden\"}");
            }
            byte[] boundaryBytes = boundary.getBytes("ISO-8859-1");
            String fileName = null;
            byte[] fileData = null;
            int boundaryIndex = 0;
            while (boundaryIndex < bodyBytes.length) {
                int nextBoundary = findBytes(bodyBytes, boundaryBytes, boundaryIndex + boundaryBytes.length);
                if (nextBoundary < 0) nextBoundary = bodyBytes.length;
                int partStart = boundaryIndex + boundaryBytes.length;
                int partEnd = nextBoundary;
                if (partStart < partEnd) {
                    byte[] partBytes = new byte[partEnd - partStart];
                    System.arraycopy(bodyBytes, partStart, partBytes, 0, partBytes.length);
                    String partString = new String(partBytes, "ISO-8859-1");
                    if (partString.contains("Content-Disposition") || partString.contains("content-disposition")) {
                        int filenameStart = partString.indexOf("filename=\"");
                        if (filenameStart >= 0) {
                            filenameStart += 10;
                            int filenameEnd = partString.indexOf("\"", filenameStart);
                            if (filenameEnd > filenameStart) {
                                fileName = partString.substring(filenameStart, filenameEnd);
                            }
                        }
                        int dataStartInString = partString.indexOf("\r\n\r\n");
                        if (dataStartInString < 0) dataStartInString = partString.indexOf("\n\n");
                        if (dataStartInString >= 0) {
                            int headerBytes = partString.substring(0, dataStartInString).getBytes("ISO-8859-1").length;
                            int skipBytes = (partString.indexOf("\r\n\r\n") == dataStartInString) ? 4 : 2;
                            int dataStartIndex = partStart + headerBytes + skipBytes;
                            int dataEndIndex = partEnd;
                            while (dataEndIndex > dataStartIndex && (bodyBytes[dataEndIndex - 1] == '\r' || bodyBytes[dataEndIndex - 1] == '\n' || bodyBytes[dataEndIndex - 1] == ' ' || bodyBytes[dataEndIndex - 1] == '\t')) {
                                dataEndIndex--;
                            }
                            if (dataEndIndex > dataStartIndex) {
                                fileData = new byte[dataEndIndex - dataStartIndex];
                                System.arraycopy(bodyBytes, dataStartIndex, fileData, 0, fileData.length);
                            }
                        }
                    }
                }
                if (fileData != null && fileData.length > 0) break;
                boundaryIndex = nextBoundary;
            }
            if (fileName == null || fileData == null || fileData.length == 0) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Dateiname oder Dateiinhalt nicht gefunden\"}");
            }
            if (!fileName.toLowerCase().endsWith(".db")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Nur .db-Dateien sind erlaubt\"}");
            }
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.close();
            File dbFile = context.getDatabasePath("turmtechnik_config.db");
            FileOutputStream fos = new FileOutputStream(dbFile);
            fos.write(fileData);
            fos.close();
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("message", "Datenbank wiederhergestellt. App ggf. neu starten.");
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(result));
        } catch (Exception e) {
            Log.e(TAG, "Restore fehlgeschlagen", e);
            String errorJson = "{\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "'") : "Wiederherstellung fehlgeschlagen") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

