    /**
     * Importiert Beschriftung-Tasten aus einer hochgeladenen Excel-Datei (.xls, multipart).
     * Ersetzt alle Einträge in der DB durch die aus Excel gelesenen 48 Zeilen.
     */
    private SimpleHttpServer.HttpResponse handlePostBeschriftungTastenImportFromExcel(SimpleHttpServer.HttpRequest request) {
        try {
            String contentType = null;
            for (java.util.Map.Entry<String, String> entry : request.headers.entrySet()) {
                if (entry.getKey().equalsIgnoreCase("content-type")) {
                    contentType = entry.getValue();
                    break;
                }
            }
            if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Content-Type muss multipart/form-data sein\"}");
            }
            byte[] bodyBytes = request.bodyBytes;
            if (bodyBytes == null || bodyBytes.length == 0) {
                Log.w(TAG, "Beschriftung-Tasten Import: bodyBytes ist null oder leer (Content-Length/ multipart?)");
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Keine Datei-Daten empfangen. Bitte eine .xls-Datei auswählen und erneut versuchen.\"}");
            }
            String boundary = null;
            if (contentType.contains("boundary=")) {
                int boundaryStart = contentType.indexOf("boundary=") + 9;
                String boundaryValue = contentType.substring(boundaryStart).trim();
                if (boundaryValue.startsWith("\"") && boundaryValue.endsWith("\"")) {
                    boundaryValue = boundaryValue.substring(1, boundaryValue.length() - 1);
                }
                boundary = "--" + boundaryValue;
            }
            if (boundary == null) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Boundary nicht gefunden\"}");
            }
            byte[] boundaryBytes = boundary.getBytes("ISO-8859-1");
            String fileName = null;
            byte[] fileData = null;
            int boundaryIndex = 0;
            while (boundaryIndex < bodyBytes.length) {
                // Nächste Boundary nach der aktuellen suchen (erste Part = Datei zwischen erstem und zweitem Boundary)
                int nextBoundary = findBytes(bodyBytes, boundaryBytes, boundaryIndex + boundaryBytes.length);
                if (nextBoundary < 0) nextBoundary = bodyBytes.length;
                int partStart = boundaryIndex + boundaryBytes.length;
                int partEnd = nextBoundary;
                if (partStart < partEnd) {
                    byte[] partBytes = new byte[partEnd - partStart];
                    System.arraycopy(bodyBytes, partStart, partBytes, 0, partBytes.length);
                    String partString = new String(partBytes, "ISO-8859-1");
                    if (partString.contains("Content-Disposition") || partString.contains("content-disposition")) {
                        int filenameStart = partString.indexOf("filename=\"");
                        if (filenameStart >= 0) {
                            filenameStart += 10;
                            int filenameEnd = partString.indexOf("\"", filenameStart);
                            if (filenameEnd > filenameStart) {
                                fileName = partString.substring(filenameStart, filenameEnd);
                            }
                        }
                        int dataStartInString = partString.indexOf("\r\n\r\n");
                        if (dataStartInString < 0) dataStartInString = partString.indexOf("\n\n");
                        if (dataStartInString >= 0) {
                            int headerBytes = partString.substring(0, dataStartInString).getBytes("ISO-8859-1").length;
                            int skipBytes = (partString.indexOf("\r\n\r\n") == dataStartInString) ? 4 : 2;
                            int dataStartIndex = partStart + headerBytes + skipBytes;
                            int dataEndIndex = partEnd;
                            while (dataEndIndex > dataStartIndex && (bodyBytes[dataEndIndex - 1] == '\r' || bodyBytes[dataEndIndex - 1] == '\n' || bodyBytes[dataEndIndex - 1] == ' ' || bodyBytes[dataEndIndex - 1] == '\t')) {
                                dataEndIndex--;
                            }
                            if (dataEndIndex > dataStartIndex) {
                                fileData = new byte[dataEndIndex - dataStartIndex];
                                System.arraycopy(bodyBytes, dataStartIndex, fileData, 0, fileData.length);
                            }
                        }
                    }
                }
                if (fileData != null && fileData.length > 0) break;
                boundaryIndex = nextBoundary;
            }
            if (fileName == null || fileData == null || fileData.length == 0) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Dateiname oder Dateiinhalt nicht gefunden\"}");
            }
            if (!fileName.toLowerCase().endsWith(".xls")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Nur .xls Dateien sind erlaubt\"}");
            }
            String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
            java.io.File tempDir = new java.io.File(sdCardPath + "/Turmtechnik/temp");
            if (!tempDir.exists()) tempDir.mkdirs();
            java.io.File tempFile = new java.io.File(tempDir, fileName);
            java.io.FileOutputStream fos = new java.io.FileOutputStream(tempFile);
            fos.write(fileData);
            fos.close();
            Log.d(TAG, "Beschriftung-Tasten Import: Temp-Datei geschrieben " + tempFile.getAbsolutePath() + " (" + fileData.length + " Bytes)");
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            int count = dbHelper.importBeschriftungTastenFromExcel(tempFile.getAbsolutePath());
            if (!tempFile.delete()) tempFile.deleteOnExit();
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", count > 0);
            result.put("count", count);
            String msg = count > 0 ? (count + " Tasten aus Excel importiert.") : "Import fehlgeschlagen. Bitte eine gültige .xls-Datei (altes Excel-Format) mit Beschriftungstasten verwenden.";
            result.put("message", msg);
            if (count == 0) Log.w(TAG, "Beschriftung-Tasten Import: 0 Zeilen importiert von " + fileName);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(result));
        } catch (Exception e) {
            Log.e(TAG, "Beschriftung-Tasten Excel-Import fehlgeschlagen", e);
            String errorJson = "{\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "'") : "Import fehlgeschlagen") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

    @SuppressWarnings("unchecked")
    private SimpleHttpServer.HttpResponse handlePutBeschriftungTasten(SimpleHttpServer.HttpRequest request) {
        try {
            if (request == null || request.body == null || request.body.trim().isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Body fehlt\"}");
            }
            List<?> rawList = gson.fromJson(request.body, List.class);
            if (rawList == null) rawList = new java.util.ArrayList<>();
            java.util.List<PlatinenDatabaseHelper.BeschriftungTastenRow> rows = new java.util.ArrayList<>();
            java.util.List<String> sofortMelodien = new java.util.ArrayList<>();
            for (int i = 0; i < rawList.size(); i++) {
                Object o = rawList.get(i);
                if (!(o instanceof Map)) continue;
                Map<?, ?> m = (Map<?, ?>) o;
                PlatinenDatabaseHelper.BeschriftungTastenRow r = new PlatinenDatabaseHelper.BeschriftungTastenRow();
                r.id = o instanceof Map && ((Map<?, ?>) o).containsKey("id") ? ((Number) ((Map<?, ?>) o).get("id")).intValue() : 0;
                r.zeileIndex = i;
                r.c1 = getStringFromMap(m, "c1");
                r.c2 = getStringFromMap(m, "c2");
                r.c3 = getStringFromMap(m, "c3");
                r.c4 = getStringFromMap(m, "c4");
                r.c5 = getStringFromMap(m, "c5");
                r.c6 = getStringFromMap(m, "c6");
                r.c7 = getStringFromMap(m, "c7");
                r.c8 = getStringFromMap(m, "c8");
                r.c9 = getStringFromMap(m, "c9");
                r.c10 = getStringFromMap(m, "c10");
                r.c13 = getStringFromMap(m, "c13");
                r.sound = getStringFromMap(m, "sound");
                Object so = m.get("sonder_id");
                if (so != null && !(so instanceof com.google.gson.JsonNull)) {
                    if (so instanceof Number) r.sonderId = ((Number) so).intValue();
                    else if (so instanceof String && !((String) so).trim().isEmpty()) {
                        try { r.sonderId = Integer.parseInt((String) so); } catch (NumberFormatException ignored) { }
                    }
                }
                sofortMelodien.add(getStringFromMap(m, "sofort_melodie"));
                rows.add(r);
            }
            // Automatische Relais-IDs: Verknüpft = 2001+, Sofort Start = 3001+
            final int VERKNUEPFT_BASE = 2001;
            final int SOFORT_BASE = 3001;
            int verknuepftCount = 0;
            int sofortCount = 0;
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            for (int i = 0; i < rows.size(); i++) {
                PlatinenDatabaseHelper.BeschriftungTastenRow r = rows.get(i);
                String c1 = r.c1 != null ? r.c1.trim() : "";
                if ("verknuepft".equalsIgnoreCase(c1) || "Verknüpft".equals(c1)) {
                    r.c3 = String.valueOf(VERKNUEPFT_BASE + verknuepftCount++);
                } else if ("Sofort Start".equalsIgnoreCase(c1)) {
                    r.c3 = String.valueOf(SOFORT_BASE + sofortCount);
                    String melodie = (i < sofortMelodien.size() && sofortMelodien.get(i) != null) ? sofortMelodien.get(i).trim() : "";
                    dbHelper.setConfigValue("sofort_melodie_" + sofortCount, melodie);
                    sofortCount++;
                } else if (r.sonderId != null) {
                    // Systemtasten (Stop, Automatik, Zweite Seite, …): c3 = sonder_id, damit die App die richtige „Relaisnummer“ aus c3 liest (auch bei mehrfach vorkommenden Systemtasten).
                    r.c3 = String.valueOf(r.sonderId);
                }
            }
            dbHelper.replaceBeschriftungTasten(rows);
            Map<String, Object> resp = new HashMap<>();
            resp.put("success", true);
            resp.put("count", rows.size());
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(resp));
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Speichern der Beschriftung-Tasten", e);
            String errorJson = "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

    private static String getStringFromMap(Map<?, ?> m, String key) {
        Object v = m.get(key);
        if (v == null) return null;
        String s = (v instanceof String) ? (String) v : String.valueOf(v);
        return "null".equals(s) ? null : s;
    }
    
    private SimpleHttpServer.HttpResponse handleGetBenutzerprogramme() {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.cleanupAlteBenutzerprogramme();
            java.util.List<Map<String, Object>> list = new java.util.ArrayList<>();
            for (int i = 0; i < BENUTZERPROGRAMME_MAX; i++) {
                Map<String, Object> item = new HashMap<>();
                item.put("index", i);
                String on = dbHelper.getConfigValue("benutzer_" + i + "_on");
                item.put("on", "1".equals(on) || "true".equalsIgnoreCase(on != null ? on : ""));
                String v = dbHelper.getConfigValue("benutzer_" + i + "_stunde");
                item.put("stunde", v != null && !v.isEmpty() ? Integer.parseInt(v) : 12);
                v = dbHelper.getConfigValue("benutzer_" + i + "_minute");
                item.put("minute", v != null && !v.isEmpty() ? Integer.parseInt(v) : 0);
                v = dbHelper.getConfigValue("benutzer_" + i + "_tag");
                item.put("tag", v != null && !v.isEmpty() ? Integer.parseInt(v) : 1);
                v = dbHelper.getConfigValue("benutzer_" + i + "_monat");
                int monatVal = (v != null && !v.isEmpty()) ? Integer.parseInt(v) : 1;
                // DB speichert 1-12. Nur Alt-Werte 0 (0-basiert) auf 1 bringen.
                if (monatVal == 0) monatVal = 1;
                else if (monatVal < 1 || monatVal > 12) monatVal = 1;
                item.put("monat", monatVal);
                v = dbHelper.getConfigValue("benutzer_" + i + "_jahr");
                item.put("jahr", v != null && !v.isEmpty() ? Integer.parseInt(v) : java.util.Calendar.getInstance().get(java.util.Calendar.YEAR));
                v = dbHelper.getConfigValue("benutzer_" + i + "_melodie");
                item.put("melodieName", v != null ? v.trim() : "");
                v = dbHelper.getConfigValue("benutzer_" + i + "_tagtyp");
                item.put("tagtypName", v != null ? v.trim() : "");
                list.add(item);
            }
            String json = gson.toJson(list);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Lesen der Benutzerprogramme", e);
            String errorJson = "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    private SimpleHttpServer.HttpResponse handlePutBenutzerprogramm(int index, SimpleHttpServer.HttpRequest request) {
        if (index < 0 || index >= BENUTZERPROGRAMME_MAX) {
            String errorJson = "{\"error\":\"Index außerhalb 0.." + (BENUTZERPROGRAMME_MAX - 1) + "\"}";
            return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
        }
        try {
            Map<?, ?> body = gson.fromJson(request.body, Map.class);
            if (body == null) body = new HashMap<>();
            String melodie = body.containsKey("melodieName") ? String.valueOf(body.get("melodieName")).trim() : "";
            String tagtyp = body.containsKey("tagtypName") ? String.valueOf(body.get("tagtypName")).trim() : "";
            boolean on = Boolean.TRUE.equals(body.get("on")) || "1".equals(String.valueOf(body.get("on")));
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            String key = "benutzer_" + index + "_";
            String currentOn = dbHelper.getConfigValue(key + "on");
            boolean slotWasOff = !"1".equals(currentOn);
            if (on && melodie.isEmpty() && tagtyp.isEmpty() && !slotWasOff) {
                String errorJson = "{\"error\":\"Bitte wählen Sie eine Melodie oder einen Programmtag aus.\",\"index\":" + index + "}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            dbHelper.setConfigValue(key + "on", on ? "1" : "0");
            dbHelper.setConfigValue(key + "stunde", String.valueOf(body.containsKey("stunde") ? ((Number) body.get("stunde")).intValue() : 12));
            dbHelper.setConfigValue(key + "minute", String.valueOf(body.containsKey("minute") ? ((Number) body.get("minute")).intValue() : 0));
            dbHelper.setConfigValue(key + "tag", String.valueOf(body.containsKey("tag") ? ((Number) body.get("tag")).intValue() : 1));
            int monatPut = body.containsKey("monat") ? ((Number) body.get("monat")).intValue() : 1;
            if (monatPut == 0) monatPut = 1;
            else if (monatPut < 1 || monatPut > 12) monatPut = 1;
            dbHelper.setConfigValue(key + "monat", String.valueOf(monatPut));
            dbHelper.setConfigValue(key + "jahr", String.valueOf(body.containsKey("jahr") ? ((Number) body.get("jahr")).intValue() : java.util.Calendar.getInstance().get(java.util.Calendar.YEAR)));
            dbHelper.setConfigValue(key + "melodie", melodie);
            dbHelper.setConfigValue(key + "tagtyp", tagtyp);
            String json = "{\"success\":true,\"index\":" + index + "}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Speichern des Benutzerprogramms " + index, e);
            String errorJson = "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /** Relais-Basis für Verknüpfte Tasten (c3 = 2001, 2002, …). Index = c3 - VERKNUEPFT_BASE. */
    private static final int VERKNUEPFT_BASE = 2001;

    /**
     * Gibt alle Verknüpften Tasten mit Zustand zurück: [{ index, tasteName, on }, ...].
     * index = aus c3 abgeleitet (c3 2001 → 0, 2002 → 1, …), damit Web-UI und App dieselbe Taste meinen.
     */
    private SimpleHttpServer.HttpResponse handleGetVerknuepfteTasten() {
        try {
            java.util.List<java.util.Map<String, Object>> list = new java.util.ArrayList<>();
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.BeschriftungTastenRow> rows = dbHelper.getBeschriftungTasten();
            int sequentialFallback = 0;
            for (PlatinenDatabaseHelper.BeschriftungTastenRow r : rows) {
                String funktion = r.c1 != null ? r.c1.trim() : "";
                if ("verknuepft".equalsIgnoreCase(funktion) || "Verknüpft".equals(funktion)) {
                    String tasteName = r.c2 != null ? r.c2.trim() : "";
                    int index = sequentialFallback;
                    String c3 = r.c3 != null ? r.c3.trim() : "";
                    if (!c3.isEmpty() && !"null".equalsIgnoreCase(c3)) {
                        try {
                            int relaisNr = Integer.parseInt(c3);
                            if (relaisNr >= VERKNUEPFT_BASE && relaisNr < VERKNUEPFT_BASE + TurmtechnikActivity.RELAIS_COUNT) {
                                index = relaisNr - VERKNUEPFT_BASE;
                            }
                        } catch (NumberFormatException ignored) { }
                    }
                    sequentialFallback++;
                    boolean on = false;
                    if (index >= 0 && index < TurmtechnikActivity.verknuepfteTastenOn.length) {
                        synchronized (TurmtechnikActivity.VERKNUEPFTE_TASTEN_LOCK) {
                            on = Boolean.TRUE.equals(TurmtechnikActivity.verknuepfteTastenOn[index]);
                        }
                    }
                    java.util.Map<String, Object> entry = new HashMap<>();
                    entry.put("index", index);
                    entry.put("tasteName", tasteName.isEmpty() ? ("Verknüpft " + (index + 1)) : tasteName);
                    entry.put("on", on);
                    list.add(entry);
                }
            }
            String json = gson.toJson(list);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen der Verknüpften Tasten", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

    /** PUT /api/verknuepfte-tasten/:index – Body: { "on": true/false }. Setzt Zustand in App, DB und SharedPreferences. */
    private SimpleHttpServer.HttpResponse handlePutVerknuepfteTaste(int index, SimpleHttpServer.HttpRequest request) {
        if (index < 0 || index >= TurmtechnikActivity.RELAIS_COUNT) {
            return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Index außerhalb des gültigen Bereichs\"}");
        }
        try {
            String body = request.body != null ? request.body : "";
            Boolean on = parseJsonBoolean(body, "on");
            if (on == null) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Body muss { \\\"on\\\": true oder false } enthalten\"}");
            }
            android.content.Context ctx = context != null ? context : TurmtechnikActivity.turmtechnikContext;
            if (ctx == null) {
                return new SimpleHttpServer.HttpResponse(503, "application/json", "{\"error\":\"Kontext nicht verfügbar\"}");
            }
            TurmtechnikActivity.setVerknuepfteTasteFromWeb(ctx, index, on);
            String json = "{\"success\":true,\"index\":" + index + ",\"on\":" + on + "}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler bei PUT /api/verknuepfte-tasten/" + index, e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"success\":false,\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /** Liest aus JSON-String den Wert des Keys key als Boolean (true/false). */
    private static Boolean parseJsonBoolean(String json, String key) {
        if (json == null || key == null) return null;
        String s = json.trim();
        if (!s.startsWith("{")) return null;
        // Einfaches Parsing: "on":true oder "on": false
        java.util.regex.Pattern p = java.util.regex.Pattern.compile("\"" + java.util.regex.Pattern.quote(key) + "\"\\s*:\\s*(true|false)", java.util.regex.Pattern.CASE_INSENSITIVE);
        java.util.regex.Matcher m = p.matcher(s);
        if (m.find()) return "true".equalsIgnoreCase(m.group(1));
        return null;
    }
    
