    /**
     * Hilfsmethode: Gibt alle Tasten mit einer bestimmten Funktion aus der DB zurück (name, relais, platine, relaisBerechnet).
     */
    private SimpleHttpServer.HttpResponse handleGetTastenByFunktion(String funktionFilter) {
        try {
            java.util.List<Map<String, Object>> tasten = new java.util.ArrayList<>();
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.BeschriftungTastenRow> rows = dbHelper.getBeschriftungTasten();
            for (PlatinenDatabaseHelper.BeschriftungTastenRow r : rows) {
                String funktion = r.c1 != null ? r.c1.trim() : "";
                if (!funktion.equalsIgnoreCase(funktionFilter)) continue;
                String tasteName = r.c2 != null ? r.c2.trim() : "";
                if (tasteName.isEmpty() || "leer".equalsIgnoreCase(tasteName)) continue;
                int relais = 0;
                try {
                    if (r.c3 != null && !r.c3.trim().isEmpty() && !"null".equalsIgnoreCase(r.c3.trim())) {
                        relais = Integer.parseInt(r.c3.trim());
                    }
                } catch (NumberFormatException e) { continue; }
                int platine = 1;
                try {
                    if (r.c5 != null && !r.c5.trim().isEmpty()) platine = Integer.parseInt(r.c5.trim());
                } catch (NumberFormatException e) { /* Default 1 */ }
                int relaisBerechnet = relais + ((platine - 1) * 32);
                Map<String, Object> taste = new HashMap<>();
                taste.put("name", tasteName);
                taste.put("relais", relais);
                taste.put("platine", platine);
                taste.put("relaisBerechnet", relaisBerechnet);
                tasten.add(taste);
            }
            String json = gson.toJson(tasten);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen der " + funktionFilter + " Tasten", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /** Zusätzliche Minute bei Sofort-Startzeit: früheste Start = Jetzt + Vorlauf + Vorschwingen + diese Minute (nicht zu knapp an RTC). */
    private static final int SOFORT_MIN_ZUSATZ_MINUTEN = 1;

    /**
     * GET /api/play/sofort/:index/min-startzeit – früheste erlaubte Startzeit (Jetzt + Vorlauf + längstes Vorschwingen + 1 Min).
     * Formel: minStart = Jetzt + Vorlauf (Min) + ceil(Vorschwingen Sek/60) + SOFORT_MIN_ZUSATZ_MINUTEN.
     * Für Vorbelegung des Zeitwählers und min-Attribut.
     */
    private SimpleHttpServer.HttpResponse handleGetSofortMinStartzeit(int index) {
        try {
            android.content.Context ctx = context != null ? context : TurmtechnikActivity.turmtechnikContext;
            if (ctx == null) {
                return new SimpleHttpServer.HttpResponse(503, "application/json", "{\"success\":false,\"error\":\"Kontext nicht verfügbar\"}");
            }
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(ctx);
            String melodieName = dbHelper.getConfigValue("sofort_melodie_" + index);
            java.util.Calendar now = java.util.Calendar.getInstance();
            int nowH = now.get(java.util.Calendar.HOUR_OF_DAY);
            int nowM = now.get(java.util.Calendar.MINUTE);
            String jetztStr = (nowH < 10 ? "0" : "") + nowH + ":" + (nowM < 10 ? "0" : "") + nowM;
            if (melodieName == null || melodieName.trim().isEmpty()) {
                String erkNull = "Keine Melodie konfiguriert → Mindest = Jetzt " + jetztStr;
                return new SimpleHttpServer.HttpResponse(200, "application/json",
                    "{\"success\":true,\"minStartzeit\":\"" + jetztStr + "\",\"berechnung\":{\"jetzt\":\"" + jetztStr + "\",\"vorlaufMinuten\":0,\"vorschwingenSekunden\":0,\"erklaerung\":\"" + escapeJsonString(erkNull) + "\",\"melodieName\":\"\"}}");
            }
            melodieName = melodieName.trim();
            int vorlaufMinuten = 0;
            PlatinenDatabaseHelper.Melodie melodie = dbHelper.getMelodieByNormalizedName(melodieName);
            if (melodie != null) vorlaufMinuten = melodie.vorlaufMinuten;
            int maxVorschwingenSekunden = 0;
            for (PlatinenDatabaseHelper.VorschwingenConfig v : dbHelper.getAllVorschwingen()) {
                if (v.aktiv && v.zeitSekunden > maxVorschwingenSekunden) maxVorschwingenSekunden = v.zeitSekunden;
            }
            // Früheste Startzeit: Jetzt + Vorlauf + Vorschwingen (aufgerundet in Min) + 1 Min Puffer (nicht zu knapp an RTC)
            int vorschwingMinuten = (maxVorschwingenSekunden + 59) / 60;
            int minZusatzMinuten = vorlaufMinuten + vorschwingMinuten + SOFORT_MIN_ZUSATZ_MINUTEN;
            int nowMinuten = nowH * 60 + nowM;
            int minErlaubt;
            if (nowMinuten + minZusatzMinuten <= 1439) {
                minErlaubt = nowMinuten + minZusatzMinuten;
            } else {
                minErlaubt = nowMinuten + minZusatzMinuten - 1440;
            }
            int minStunde = minErlaubt / 60;
            int minMinute = minErlaubt % 60;
            if (minStunde >= 24) minStunde -= 24;
            String minStartzeit = (minStunde < 10 ? "0" : "") + minStunde + ":" + (minMinute < 10 ? "0" : "") + minMinute;
            String erklaerung = "Jetzt " + jetztStr + " + Vorlauf " + vorlaufMinuten + " Min + Vorschwingen " + maxVorschwingenSekunden + " s (" + vorschwingMinuten + " Min) + " + SOFORT_MIN_ZUSATZ_MINUTEN + " Min Puffer → früheste Startzeit " + minStartzeit;
            String berechnungJson = "\"jetzt\":\"" + jetztStr + "\",\"vorlaufMinuten\":" + vorlaufMinuten + ",\"vorschwingenSekunden\":" + maxVorschwingenSekunden + ",\"vorschwingMinuten\":" + vorschwingMinuten + ",\"pufferMinuten\":" + SOFORT_MIN_ZUSATZ_MINUTEN + ",\"erklaerung\":\"" + escapeJsonString(erklaerung) + "\",\"melodieName\":\"" + escapeJsonString(melodieName) + "\"";
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"minStartzeit\":\"" + minStartzeit + "\",\"berechnung\":{" + berechnungJson + "}}");
        } catch (Exception e) {
            Log.e(TAG, "Fehler bei GET /api/play/sofort/" + index + "/min-startzeit", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"success\":false,\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

    /**
     * POST /api/play/sofort/:index – Soforttaste per API auslösen (Melodie sofort starten).
     * Optionaler Body: { "startzeit": "HH:mm" } – ohne Body wird aktuelle Uhrzeit verwendet.
     */
    private SimpleHttpServer.HttpResponse handlePostPlaySofort(SimpleHttpServer.HttpRequest request, int index) {
        try {
            android.content.Context ctx = context != null ? context : TurmtechnikActivity.turmtechnikContext;
            if (ctx == null) {
                String err = "{\"success\":false,\"error\":\"Kontext nicht verfügbar\"}";
                return new SimpleHttpServer.HttpResponse(503, "application/json", err);
            }
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(ctx);
            String melodieName = dbHelper.getConfigValue("sofort_melodie_" + index);
            if (melodieName == null || melodieName.trim().isEmpty()) {
                String err = "{\"success\":false,\"error\":\"Soforttaste nicht konfiguriert\",\"index\":" + index + "}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", err);
            }
            melodieName = melodieName.trim();
            int stunde;
            int minute;
            if (request.body != null && !request.body.trim().isEmpty()) {
                try {
                    com.google.gson.JsonObject obj = gson.fromJson(request.body, com.google.gson.JsonObject.class);
                    if (obj != null && obj.has("startzeit")) {
                        String startzeit = obj.get("startzeit").getAsString();
                        if (startzeit != null && startzeit.matches("\\d{1,2}:\\d{1,2}")) {
                            String[] parts = startzeit.split(":");
                            stunde = Integer.parseInt(parts[0].trim());
                            minute = Integer.parseInt(parts[1].trim());
                            if (stunde < 0 || stunde > 23 || minute < 0 || minute > 59) {
                                stunde = java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY);
                                minute = java.util.Calendar.getInstance().get(java.util.Calendar.MINUTE);
                            }
                        } else {
                            java.util.Calendar cal = java.util.Calendar.getInstance();
                            stunde = cal.get(java.util.Calendar.HOUR_OF_DAY);
                            minute = cal.get(java.util.Calendar.MINUTE);
                        }
                    } else {
                        java.util.Calendar cal = java.util.Calendar.getInstance();
                        stunde = cal.get(java.util.Calendar.HOUR_OF_DAY);
                        minute = cal.get(java.util.Calendar.MINUTE);
                    }
                } catch (Exception e) {
                    java.util.Calendar cal = java.util.Calendar.getInstance();
                    stunde = cal.get(java.util.Calendar.HOUR_OF_DAY);
                    minute = cal.get(java.util.Calendar.MINUTE);
                }
            } else {
                java.util.Calendar cal = java.util.Calendar.getInstance();
                stunde = cal.get(java.util.Calendar.HOUR_OF_DAY);
                minute = cal.get(java.util.Calendar.MINUTE);
            }
            int vorlaufMinuten = 0;
            PlatinenDatabaseHelper.Melodie melodie = dbHelper.getMelodieByNormalizedName(melodieName);
            if (melodie != null) vorlaufMinuten = melodie.vorlaufMinuten;
            int maxVorschwingenSekunden = 0;
            for (PlatinenDatabaseHelper.VorschwingenConfig v : dbHelper.getAllVorschwingen()) {
                if (v.aktiv && v.zeitSekunden > maxVorschwingenSekunden) maxVorschwingenSekunden = v.zeitSekunden;
            }
            int vorschwingMinuten = (maxVorschwingenSekunden + 59) / 60;
            int minZusatzMinuten = vorlaufMinuten + vorschwingMinuten + SOFORT_MIN_ZUSATZ_MINUTEN;
            java.util.Calendar now = java.util.Calendar.getInstance();
            int nowMinuten = now.get(java.util.Calendar.HOUR_OF_DAY) * 60 + now.get(java.util.Calendar.MINUTE);
            int gewuenschteMinuten = stunde * 60 + minute;
            int minErlaubt;
            if (nowMinuten + minZusatzMinuten <= 1439) {
                minErlaubt = nowMinuten + minZusatzMinuten;
            } else {
                minErlaubt = nowMinuten + minZusatzMinuten - 1440;
            }
            if (gewuenschteMinuten < minErlaubt) {
                int minStunde = minErlaubt / 60;
                int minMinute = minErlaubt % 60;
                if (minStunde >= 24) minStunde -= 24;
                String msg = "Startzeit muss mindestens Jetzt + Vorlauf + Vorschwingen + " + SOFORT_MIN_ZUSATZ_MINUTEN + " Min Puffer sein (früheste: "
                    + (minStunde < 10 ? "0" : "") + minStunde + ":" + (minMinute < 10 ? "0" : "") + minMinute + ").";
                String err = "{\"success\":false,\"error\":\"" + escapeJsonString(msg) + "\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", err);
            }
            StaticVariable.startStundeManuell = stunde;
            StaticVariable.startMinuteManuell = minute;
            StaticVariable.sofortStartPopupFilename = melodieName;
            StaticVariable.sofortStartPopupFlag = true;
            StaticVariable.sofortStartPopupGefunden = false;
            String padH = stunde < 10 ? "0" + stunde : String.valueOf(stunde);
            String padM = minute < 10 ? "0" + minute : String.valueOf(minute);
            String startzeitStr = padH + ":" + padM;
            // Infozeile: berechneten Beginn (Start − Vorlauf) anzeigen wie bei anderen Programmen, nicht die Startzeit
            long vorlaufMs = vorlaufMinuten * 60L * 1000L;
            long vorschwingMs = maxVorschwingenSekunden * 1000L;
            long abzugMs = Math.max(vorlaufMs, vorschwingMs);
            java.util.Calendar startCal = java.util.Calendar.getInstance();
            startCal.set(java.util.Calendar.HOUR_OF_DAY, stunde);
            startCal.set(java.util.Calendar.MINUTE, minute);
            startCal.set(java.util.Calendar.SECOND, 0);
            startCal.set(java.util.Calendar.MILLISECOND, 0);
            long beginnMs = startCal.getTimeInMillis() - abzugMs;
            java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("HH:mm:ss", java.util.Locale.GERMANY);
            String beginnStr = sdf.format(new java.util.Date(beginnMs));
            String infoText = (melodieName != null ? melodieName : "") + "  " + beginnStr;
            StaticVariable.stringInfoTextField[0] = infoText;
            UhrThread.newSearchAutomaticStart = true;
            dbHelper.setConfigValue("sofort_startzeit_" + index, "");
            String json = "{\"success\":true,\"melodieName\":\"" + escapeJsonString(melodieName) + "\",\"startzeit\":\"" + escapeJsonString(startzeitStr) + "\",\"infoText\":\"" + escapeJsonString(infoText) + "\"}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler bei POST /api/play/sofort/" + index, e);
            String err = "{\"success\":false,\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", err);
        }
    }
    
    private static String escapeJsonString(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }

    /**
     * Berechnet Sonnenaufgang- und Sonnenuntergangszeit für das angegebene Datum (Anlagenstandort, Anpassung, Runden).
     * @return String[2] mit [0]=sonnenaufgangZeit, [1]=sonnenuntergangZeit (Format HH:mm), oder null wenn keine Koordinaten.
     */
    private static String[] computeSaSuForDate(PlatinenDatabaseHelper dbHelper, int tag, int monat, int jahr) {
        if (dbHelper == null) return null;
        PlatinenDatabaseHelper.AnlagenstandortConfig config = dbHelper.getAnlagenstandortConfig();
        String breitengrad = config.breitengrad != null ? config.breitengrad.replace(",", ".").trim() : "";
        String laengengrad = config.laengengrad != null ? config.laengengrad.replace(",", ".").trim() : "";
        if (breitengrad.isEmpty() || laengengrad.isEmpty()) return null;
        String anpassungSA = config.anpassungSonnenaufgangMinuten != null ? config.anpassungSonnenaufgangMinuten.trim() : "0";
        String anpassungSU = config.anpassungSonnenuntergangMinuten != null ? config.anpassungSonnenuntergangMinuten.trim() : "0";
        String rundenStr = config.rundenMinuten != null ? config.rundenMinuten.trim() : "5";
        long rundenMs = 0;
        try {
            rundenMs = Long.parseLong(rundenStr) * 60 * 1000;
        } catch (NumberFormatException e) {
            rundenMs = 5 * 60 * 1000;
        }
        long anpassungMsSA = 0, anpassungMsSU = 0;
        try {
            anpassungMsSA = Long.parseLong(anpassungSA) * 60 * 1000;
            anpassungMsSU = Long.parseLong(anpassungSU) * 60 * 1000;
        } catch (NumberFormatException ignored) { }
        try {
            Location location = new Location(breitengrad, laengengrad);
            SunriseSunsetCalculator calc = new SunriseSunsetCalculator(location, TimeZone.getDefault());
            Calendar cal = Calendar.getInstance();
            cal.set(jahr, monat, tag);
            Calendar officialSunrise = calc.getOfficialSunriseCalendarForDate(cal);
            Calendar officialSunset = calc.getOfficialSunsetCalendarForDate(cal);
            long msSA = officialSunrise.getTimeInMillis() + anpassungMsSA;
            long msSU = officialSunset.getTimeInMillis() + anpassungMsSU;
            msSA = roundMinutes(msSA, rundenMs);
            msSU = roundMinutes(msSU, rundenMs);
            SimpleDateFormat sdf = new SimpleDateFormat("HH:mm");
            return new String[]{ sdf.format(msSA), sdf.format(msSU) };
        } catch (Exception e) {
            Log.e(TAG, "SA/SU-Berechnung fehlgeschlagen", e);
            return null;
        }
    }

    private static long roundMinutes(long number, long round) {
        if (round <= 0) return number;
        long half = round / 2;
        return (number + half) / round * round;
    }
    
