    /** POST /api/app/install – APK per Multipart hochladen, auf Gerät speichern und Install-Dialog öffnen. */
    private SimpleHttpServer.HttpResponse handlePostAppInstall(SimpleHttpServer.HttpRequest request) {
        try {
            byte[] bodyBytes = request.bodyBytes;
            if (bodyBytes != null && bodyBytes.length > APK_INSTALL_MAX_FILE_SIZE_BYTES) {
                return new SimpleHttpServer.HttpResponse(400, "application/json",
                    "{\"success\":false,\"error\":\"APK zu groß (max. 100 MB)\"}");
            }
            String contentType = null;
            for (java.util.Map.Entry<String, String> entry : request.headers.entrySet()) {
                if (entry.getKey().equalsIgnoreCase("content-type")) {
                    contentType = entry.getValue();
                    break;
                }
            }
            if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Content-Type muss multipart/form-data sein\"}");
            }
            if (bodyBytes == null || bodyBytes.length == 0) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Keine Datei-Daten empfangen\"}");
            }
            String boundary = null;
            if (contentType.contains("boundary=")) {
                String boundaryValue = contentType.substring(contentType.indexOf("boundary=") + 9).trim();
                if (boundaryValue.startsWith("\"") && boundaryValue.endsWith("\"")) {
                    boundaryValue = boundaryValue.substring(1, boundaryValue.length() - 1);
                }
                boundary = "--" + boundaryValue;
            }
            if (boundary == null) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Boundary nicht gefunden\"}");
            }
            byte[] boundaryBytes = boundary.getBytes("ISO-8859-1");
            String fileName = null;
            byte[] fileData = null;
            int boundaryIndex = 0;
            while (boundaryIndex < bodyBytes.length) {
                int nextBoundary = findBytes(bodyBytes, boundaryBytes, boundaryIndex + boundaryBytes.length);
                if (nextBoundary < 0) nextBoundary = bodyBytes.length;
                int partStart = boundaryIndex + boundaryBytes.length;
                int partEnd = nextBoundary;
                if (partStart < partEnd) {
                    byte[] partBytes = new byte[partEnd - partStart];
                    System.arraycopy(bodyBytes, partStart, partBytes, 0, partBytes.length);
                    String partString = new String(partBytes, "ISO-8859-1");
                    if (partString.contains("Content-Disposition") || partString.contains("content-disposition")) {
                        int filenameStart = partString.indexOf("filename=\"");
                        if (filenameStart >= 0) {
                            filenameStart += 10;
                            int filenameEnd = partString.indexOf("\"", filenameStart);
                            if (filenameEnd > filenameStart) {
                                fileName = partString.substring(filenameStart, filenameEnd);
                            }
                        }
                        int dataStartInString = partString.indexOf("\r\n\r\n");
                        if (dataStartInString < 0) dataStartInString = partString.indexOf("\n\n");
                        if (dataStartInString >= 0) {
                            int headerBytes = partString.substring(0, dataStartInString).getBytes("ISO-8859-1").length;
                            int skipBytes = (partString.indexOf("\r\n\r\n") == dataStartInString) ? 4 : 2;
                            int dataStartIndex = partStart + headerBytes + skipBytes;
                            int dataEndIndex = partEnd;
                            while (dataEndIndex > dataStartIndex && (bodyBytes[dataEndIndex - 1] == '\r' || bodyBytes[dataEndIndex - 1] == '\n' || bodyBytes[dataEndIndex - 1] == ' ' || bodyBytes[dataEndIndex - 1] == '\t')) {
                                dataEndIndex--;
                            }
                            if (dataEndIndex > dataStartIndex) {
                                fileData = new byte[dataEndIndex - dataStartIndex];
                                System.arraycopy(bodyBytes, dataStartIndex, fileData, 0, fileData.length);
                            }
                        }
                    }
                }
                if (fileData != null && fileData.length > 0) break;
                boundaryIndex = nextBoundary;
            }
            if (fileName == null || fileData == null || fileData.length == 0) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Keine APK-Datei im Upload gefunden\"}");
            }
            if (!fileName.toLowerCase().endsWith(".apk")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Nur .apk-Dateien sind erlaubt\"}");
            }
            File cacheDir = context.getCacheDir();
            if (cacheDir == null) {
                return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"success\":false,\"error\":\"Cache-Verzeichnis nicht verfügbar\"}");
            }
            File apkFile = new File(cacheDir, "uploaded.apk");
            FileOutputStream fos = new FileOutputStream(apkFile);
            fos.write(fileData);
            fos.close();
            TurmtechnikActivity.requestOpenInstallDialog(apkFile);
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("message", "APK gespeichert. Auf dem Gerät bitte 'Installieren' tippen.");
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(result));
        } catch (Exception e) {
            Log.e(TAG, "APK-Install-Upload fehlgeschlagen", e);
            String errorJson = "{\"success\":false,\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "'") : "Upload fehlgeschlagen") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

    /** POST /api/app/exit-for-settings – App beenden; für die nächsten Minuten startet sie nicht automatisch (für Einstellungen am Tablet). Body optional: { "minutes": 120 }. */
    private SimpleHttpServer.HttpResponse handlePostAppExitForSettings(SimpleHttpServer.HttpRequest request) {
        try {
            int minutes = 120;
            if (request.body != null && !request.body.trim().isEmpty()) {
                try {
                    com.google.gson.JsonObject jo = gson.fromJson(request.body, com.google.gson.JsonObject.class);
                    if (jo != null && jo.has("minutes")) {
                        minutes = Math.max(1, Math.min(1440, jo.get("minutes").getAsInt())); // 1–1440 (24 h)
                    }
                } catch (Exception e) {
                    // Fallback 120
                }
            }
            TurmtechnikActivity.requestAppExitForSettings(minutes);
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("message", "App wird beendet. Für " + minutes + " Minuten startet sie nicht automatisch. Beim erneuten Öffnen (z. B. HOME) erscheint die Launcher-Auswahl – Sie können dann den Launcher und alle Apps nutzen.");
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(result));
        } catch (Exception e) {
            Log.e(TAG, "Fehler bei POST /api/app/exit-for-settings", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"success\":false,\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

