    /** Sortierschlüssel für Programmabfrage: nach Startzeit (Minute des Tages), bei gleicher Zeit Benutzerprogramm zuerst. */
    private static int programmeSortKey(String startzeit, boolean benutzerprogramm) {
        if (startzeit == null || startzeit.trim().isEmpty()) return 24 * 60 * 2;
        startzeit = startzeit.trim();
        if ("SA".equalsIgnoreCase(startzeit)) return 0 * 2 + (benutzerprogramm ? 0 : 1);
        if ("SU".equalsIgnoreCase(startzeit)) return (24 * 60 - 1) * 2 + (benutzerprogramm ? 0 : 1);
        // HH:mm oder H:mm
        String[] parts = startzeit.split(":");
        if (parts.length >= 2) {
            try {
                int h = Integer.parseInt(parts[0].trim());
                int m = Integer.parseInt(parts[1].trim());
                int minuteOfDay = Math.max(0, Math.min(23 * 60 + 59, h * 60 + m));
                return minuteOfDay * 2 + (benutzerprogramm ? 0 : 1);
            } catch (NumberFormatException e) { }
        }
        return 12 * 60 * 2;
    }

    /** Berechnet die Gesamtdauer einer Melodie aus den Melodiezeilen (Sekunden) und formatiert als mm:ss oder hh:mm:ss. */
    private String getMelodieDauerFormatted(PlatinenDatabaseHelper dbHelper, String melodieName) {
        if (melodieName == null || melodieName.trim().isEmpty()) return "";
        PlatinenDatabaseHelper.Melodie melodie = dbHelper.getMelodieByNormalizedName(melodieName.trim());
        if (melodie == null) return "";
        java.util.List<PlatinenDatabaseHelper.MelodieZeile> zeilen = dbHelper.getMelodieZeilen(melodie.id);
        if (zeilen == null) return "";
        double totalSek = 0;
        for (PlatinenDatabaseHelper.MelodieZeile z : zeilen) {
            if (z.dauerSekunden != null) totalSek += z.dauerSekunden;
        }
        if (totalSek <= 0) return "";
        int sek = (int) Math.round(totalSek);
        int h = sek / 3600, m = (sek % 3600) / 60, s = sek % 60;
        if (h > 0) return String.format("%d:%02d:%02d", h, m, s);
        return String.format("%d:%02d", m, s);
    }

    /** GET /api/programm-abfrage?datum=YYYY-MM-DD – Tagtyp und Programme für ein Datum (wie Programmabfrage in der App). */
    private SimpleHttpServer.HttpResponse handleGetProgrammAbfrage(String uri) {
        try {
            int tag = 1, monat = 0, jahr = 2020;
            if (uri != null && uri.contains("?")) {
                String query = uri.substring(uri.indexOf("?") + 1);
                for (String param : query.split("&")) {
                    if (param.startsWith("datum=")) {
                        String datum = param.substring(6).trim();
                        if (datum.matches("\\d{4}-\\d{2}-\\d{2}")) {
                            String[] parts = datum.split("-");
                            jahr = Integer.parseInt(parts[0]);
                            monat = Integer.parseInt(parts[1]) - 1;
                            tag = Integer.parseInt(parts[2]);
                        }
                        break;
                    }
                    if (param.startsWith("tag=")) { try { tag = Integer.parseInt(param.substring(4).trim()); } catch (NumberFormatException e) { } }
                    if (param.startsWith("monat=")) { try { monat = Integer.parseInt(param.substring(6).trim()); if (monat >= 1 && monat <= 12) monat--; } catch (NumberFormatException e) { } }
                    if (param.startsWith("jahr=")) { try { jahr = Integer.parseInt(param.substring(5).trim()); } catch (NumberFormatException e) { } }
                }
            } else {
                java.util.Calendar cal = java.util.Calendar.getInstance();
                tag = cal.get(java.util.Calendar.DAY_OF_MONTH);
                monat = cal.get(java.util.Calendar.MONTH);
                jahr = cal.get(java.util.Calendar.YEAR);
            }
            android.content.Context ctx = context != null ? context : TurmtechnikActivity.turmtechnikContext;
            if (ctx == null) {
                return new SimpleHttpServer.HttpResponse(503, "application/json", "{\"success\":false,\"error\":\"Kontext nicht verfügbar\"}");
            }
            TurmtechnikActivity.loadBenutzerprogrammeFromDb(ctx);
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(ctx);
            Log.d(TAG, "[ProgrammAbfrage] datum=" + tag + "." + (monat + 1) + "." + jahr);
            String tagtypName = TurmtechnikActivity.getBenutzerprogrammTagtypForDate(tag, monat, jahr);
            Log.d(TAG, "[ProgrammAbfrage] nach getBenutzerprogrammTagtypForDate: tagtypName=" + (tagtypName != null ? tagtypName : "null"));
            if (tagtypName == null || tagtypName.trim().isEmpty()) {
                tagtypName = TagesSuche.getPathAndFilenameToday(tag, monat, jahr);
                Log.d(TAG, "[ProgrammAbfrage] nach getPathAndFilenameToday: tagtypName=" + (tagtypName != null ? tagtypName : "null"));
            }
            // Vortag eines Osterfeiertags (z. B. 17.02 vor Aschermittwoch): immer Normalprogramm, nie den Feiertags-Programmtag
            boolean vortag = dbHelper.istVortagOsterfeiertag(tag, monat, jahr);
            Log.d(TAG, "[ProgrammAbfrage] istVortagOsterfeiertag=" + vortag);
            if (vortag) {
                tagtypName = null;
            }
            if (tagtypName != null && tagtypName.toLowerCase().endsWith(".xls")) {
                tagtypName = tagtypName.substring(0, tagtypName.length() - 4);
            }
            if (tagtypName == null || tagtypName.trim().isEmpty()) {
                tagtypName = "Normalprogramm";
            }
            Log.d(TAG, "[ProgrammAbfrage] final tagtypName=" + tagtypName);
            dbHelper.cleanupAlteBenutzerprogramme();
            TagesSuche tagesSuche = new TagesSuche();
            java.util.List<Map<String, Object>> programmeList = new java.util.ArrayList<>();

            // 1) Benutzerprogramm-Einträge für dieses Datum (wie in der App: einzelne Termine mit Datum+Uhrzeit+Melodie)
            int monat1based = monat + 1;
            for (int i = 0; i < BENUTZERPROGRAMME_MAX; i++) {
                String on = dbHelper.getConfigValue("benutzer_" + i + "_on");
                if (!"1".equals(on) && !"true".equalsIgnoreCase(on != null ? on : "")) continue;
                String tagS = dbHelper.getConfigValue("benutzer_" + i + "_tag");
                String monatS = dbHelper.getConfigValue("benutzer_" + i + "_monat");
                String jahrS = dbHelper.getConfigValue("benutzer_" + i + "_jahr");
                if (tagS == null || monatS == null || jahrS == null) continue;
                int slotTag, slotMonat, slotJahr;
                try {
                    slotTag = Integer.parseInt(tagS.trim());
                    slotMonat = Integer.parseInt(monatS.trim());
                    if (slotMonat == 0) slotMonat = 1;
                    slotJahr = Integer.parseInt(jahrS.trim());
                } catch (NumberFormatException e) { continue; }
                if (slotTag != tag || slotMonat != monat1based || slotJahr != jahr) continue;
                String stundeS = dbHelper.getConfigValue("benutzer_" + i + "_stunde");
                String minuteS = dbHelper.getConfigValue("benutzer_" + i + "_minute");
                int slotStunde = 12, slotMinute = 0;
                try {
                    if (stundeS != null && !stundeS.trim().isEmpty()) slotStunde = Integer.parseInt(stundeS.trim());
                    if (minuteS != null && !minuteS.trim().isEmpty()) slotMinute = Integer.parseInt(minuteS.trim());
                } catch (NumberFormatException e) { }
                if (slotStunde < 0 || slotMinute < 0) continue; // nur Programmtag (ganzer Tag), keine Melodie-Zeit
                String melodie = dbHelper.getConfigValue("benutzer_" + i + "_melodie");
                if (melodie == null || melodie.trim().isEmpty()) continue;
                melodie = melodie.trim();
                Map<String, Object> item = new java.util.HashMap<>();
                item.put("id", -1);
                item.put("startzeit", (slotStunde < 10 ? "0" : "") + slotStunde + ":" + (slotMinute < 10 ? "0" : "") + slotMinute);
                item.put("funktion", "Benutzerprogramm");
                item.put("melodieName", melodie);
                item.put("dauerHeizung", "");
                item.put("melodieDauer", getMelodieDauerFormatted(dbHelper, melodie));
                item.put("benutzerprogramm", true);
                item.put("einmalig", true);
                String slotDatumStr = (slotTag < 10 ? "0" : "") + slotTag + "." + (slotMonat < 10 ? "0" : "") + slotMonat + "." + slotJahr;
                item.put("startDatum", slotDatumStr);
                item.put("endeDatum", "");
                programmeList.add(item);
            }

            // 2) Programme aus Tagtyp (Normalprogramm/Feiertag etc.), gefiltert mit programmOkFromDatabase
            java.util.List<Programm> allProgramme = dbHelper.getProgrammeByTagtyp(tagtypName.trim());
            if (allProgramme != null) {
                for (Programm p : allProgramme) {
                    if (tagesSuche.programmOkFromDatabase(p, jahr, monat, tag)) {
                        Map<String, Object> item = new java.util.HashMap<>();
                        item.put("id", p.getId());
                        item.put("startzeit", p.getStartzeit() != null ? p.getStartzeit() : "");
                        item.put("funktion", p.getFunktion() != null ? p.getFunktion() : "");
                        item.put("melodieName", p.getMelodieName() != null ? p.getMelodieName() : "");
                        item.put("dauerHeizung", p.getDauerHeizung() != null ? p.getDauerHeizung() : "");
                        item.put("melodieDauer", getMelodieDauerFormatted(dbHelper, p.getMelodieName()));
                        item.put("benutzerprogramm", false);
                        boolean hatVerknuepfteTaste = p.getVerknuepfteTaste() != null && !p.getVerknuepfteTaste().trim().isEmpty();
                        item.put("einmalig", !p.isImmer() && hatVerknuepfteTaste);
                        item.put("startDatum", p.getStartDatum() != null ? p.getStartDatum() : "");
                        item.put("endeDatum", p.getEndeDatum() != null ? p.getEndeDatum() : "");
                        programmeList.add(item);
                    }
                }
            }

            // 3) Nach Startzeit sortieren (wie in der App: chronologisch, bei gleicher Zeit Benutzerprogramm zuerst)
            programmeList.sort((a, b) -> {
                int keyA = programmeSortKey((String) a.get("startzeit"), Boolean.TRUE.equals(a.get("benutzerprogramm")));
                int keyB = programmeSortKey((String) b.get("startzeit"), Boolean.TRUE.equals(b.get("benutzerprogramm")));
                return Integer.compare(keyA, keyB);
            });

            PlatinenDatabaseHelper.FeiertagsInfo feiertag = dbHelper.getFeiertagsInfo(tag, monat, jahr);
            String datumStr = (tag < 10 ? "0" : "") + tag + "." + (monat + 1 < 10 ? "0" : "") + (monat + 1) + "." + jahr;
            String[] saSu = computeSaSuForDate(dbHelper, tag, monat, jahr);
            com.google.gson.JsonObject root = new com.google.gson.JsonObject();
            root.addProperty("success", true);
            root.addProperty("tagtypName", tagtypName);
            root.addProperty("datum", datumStr);
            if (saSu != null) {
                root.addProperty("sonnenaufgangZeit", saSu[0]);
                root.addProperty("sonnenuntergangZeit", saSu[1]);
            }
            root.add("programme", gson.toJsonTree(programmeList));
            if (feiertag != null && feiertag.name != null && !feiertag.name.trim().isEmpty()) {
                com.google.gson.JsonObject fi = new com.google.gson.JsonObject();
                fi.addProperty("name", feiertag.name);
                fi.addProperty("datum", feiertag.datum != null ? feiertag.datum : datumStr);
                root.add("feiertag", fi);
            }
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(root));
        } catch (Exception e) {
            Log.e(TAG, "Fehler bei GET /api/programm-abfrage", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"success\":false,\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }

