    /** Liest aus JSON-String den Wert des Keys key als Integer. */
    private static Integer parseJsonInt(String json, String key) {
        if (json == null || key == null) return null;
        String s = json.trim();
        if (!s.startsWith("{")) return null;
        java.util.regex.Pattern p = java.util.regex.Pattern.compile("\"" + java.util.regex.Pattern.quote(key) + "\"\\s*:\\s*(-?\\d+)");
        java.util.regex.Matcher m = p.matcher(s);
        if (m.find()) {
            try {
                return Integer.parseInt(m.group(1));
            } catch (NumberFormatException e) {
                return null;
            }
        }
        return null;
    }
    
