    private SimpleHttpServer.HttpResponse handleGetProgramme(String uri) {
        try {
            // Tagtyp aus Query-Parameter extrahieren
            String tagtypName = extractTagtypName(uri);
            
            if (tagtypName == null || tagtypName.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Tagtyp-Parameter erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Lese Programme aus Datenbank
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<Programm> programme = dbHelper.getProgrammeByTagtyp(tagtypName.trim());
            
            String json = gson.toJson(programme);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen der Programme", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Extrahiert den Tagtyp-Namen aus der URI (Query-Parameter ?tagtyp=...)
     */
    private String extractTagtypName(String uri) {
        if (uri.contains("?")) {
            String query = uri.substring(uri.indexOf("?") + 1);
            String[] params = query.split("&");
            for (String param : params) {
                if (param.startsWith("tagtyp=")) {
                    try {
                        return java.net.URLDecoder.decode(param.substring(7), "UTF-8");
                    } catch (Exception e) {
                        Log.e(TAG, "Fehler beim Dekodieren des Tagtyp-Namens", e);
                        return param.substring(7);
                    }
                }
            }
        }
        return null;
    }

    private String resolveProgrammTypForTagtyp(String tagtypName) {
        if (tagtypName == null || tagtypName.trim().isEmpty()) {
            return null;
        }
        PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
        PlatinenDatabaseHelper.Tagtyp tagtyp = dbHelper.getTagtypByName(tagtypName.trim());
        if (tagtyp == null) {
            return null;
        }
        if (tagtyp.programmTyp == null || tagtyp.programmTyp.trim().isEmpty()) {
            return "normal";
        }
        return tagtyp.programmTyp.trim();
    }
    
    /**
     * Gibt alle verfügbaren Tagtypen zurück.
     * Zeigt nur Excel-Dateien, wenn keine Tagtypen in der Datenbank vorhanden sind.
     * Wenn Tagtypen in DB vorhanden sind, werden Excel-Dateien ignoriert (auch wenn sie noch im Dateisystem existieren).
     */
    private SimpleHttpServer.HttpResponse handleGetAllTagtypen() {
        try {
            // Lade Tagtypen aus Datenbank
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.Tagtyp> tagtypen = dbHelper.getAllTagtypen();
            
            Log.d(TAG, "handleGetAllTagtypen: Gefundene Tagtypen in DB: " + (tagtypen != null ? tagtypen.size() : 0));
            
            java.util.List<java.util.Map<String, String>> tagtypenList = new java.util.ArrayList<>();
            
            if (tagtypen != null && !tagtypen.isEmpty()) {
                // Tagtypen in DB vorhanden: Zeige nur diese an (ignoriere Excel-Dateien komplett)
                Log.d(TAG, "Tagtypen in DB vorhanden (" + tagtypen.size() + "), zeige nur DB-Tagtypen an");
                for (PlatinenDatabaseHelper.Tagtyp tagtyp : tagtypen) {
                    java.util.Map<String, String> tagtypMap = new java.util.HashMap<>();
                    // Entferne .xls Endung für Anzeige (falls noch vorhanden)
                    String displayName = tagtyp.name;
                    if (displayName.toLowerCase().endsWith(".xls")) {
                        displayName = displayName.substring(0, displayName.length() - 4);
                    }
                    tagtypMap.put("name", displayName);
                    tagtypMap.put("path", "DB:" + displayName); // Kennzeichnung dass es aus DB kommt
                    tagtypMap.put("typ", tagtyp.programmTyp != null ? tagtyp.programmTyp : "normal");
                    String dropdownVal = dbHelper.getConfigValue("tagtyp_dropdown_" + displayName);
                    tagtypMap.put("inDropdown", "0".equals(dropdownVal) ? "false" : "true");
                    tagtypenList.add(tagtypMap);
                }
                
                Log.d(TAG, "Tagtypen geladen: " + tagtypenList.size() + " aus Datenbank (Excel-Dateien werden ignoriert)");
                // Debug: Zeige alle Tagtyp-Namen
                for (java.util.Map<String, String> tt : tagtypenList) {
                    Log.d(TAG, "  - Tagtyp: " + tt.get("name"));
                }
            } else {
                // Keine Tagtypen in DB: Zeige Excel-Dateien als Fallback
                Log.d(TAG, "Keine Tagtypen in DB gefunden, lade Excel-Dateien als Fallback");
                String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
                String programmtagePath = sdCardPath + "/Turmtechnik/Programmtage/";
                java.io.File programmtageDir = new java.io.File(programmtagePath);
                
                if (programmtageDir.exists() && programmtageDir.isDirectory()) {
                    java.io.File[] files = programmtageDir.listFiles();
                    if (files != null) {
                        for (java.io.File file : files) {
                            if (file.isFile() && file.getName().toLowerCase().endsWith(".xls")) {
                                String fileName = file.getName();
                                String filePath = file.getAbsolutePath();
                                
                                // Prüfe zusätzlich, ob dieser Tagtyp bereits in DB existiert (sollte nicht passieren, aber zur Sicherheit)
                                PlatinenDatabaseHelper.Tagtyp existingTagtyp = dbHelper.getTagtypByName(fileName);
                                if (existingTagtyp == null) {
                                    java.util.Map<String, String> tagtypMap = new java.util.HashMap<>();
                                    tagtypMap.put("name", fileName);
                                    tagtypMap.put("path", filePath);
                                    tagtypMap.put("typ", "tagtyp"); // Einheitlicher Typ
                                    String dropdownVal = dbHelper.getConfigValue("tagtyp_dropdown_" + fileName);
                                    tagtypMap.put("inDropdown", "0".equals(dropdownVal) ? "false" : "true");
                                    tagtypenList.add(tagtypMap);
                                } else {
                                    Log.d(TAG, "Excel-Datei " + fileName + " wird ignoriert, da bereits in DB vorhanden");
                                }
                            }
                        }
                    }
                } else {
                    Log.w(TAG, "Programmtage-Ordner nicht gefunden: " + programmtagePath);
                }
                
                Log.d(TAG, "Tagtypen geladen: " + tagtypenList.size() + " Excel-Dateien (Fallback)");
            }
            
            // Sortiere nach Name
            java.util.Collections.sort(tagtypenList, new java.util.Comparator<java.util.Map<String, String>>() {
                @Override
                public int compare(java.util.Map<String, String> a, java.util.Map<String, String> b) {
                    return a.get("name").compareToIgnoreCase(b.get("name"));
                }
            });
            
            String json = gson.toJson(tagtypenList);
            Log.d(TAG, "handleGetAllTagtypen: Rückgabe: " + tagtypenList.size() + " Tagtypen");
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen der Tagtypen", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /** Setzt das Flag „In Benutzerprogramm-Dropdown anzeigen“ für einen Tagtyp (io_config). */
    private SimpleHttpServer.HttpResponse handlePutTagtypDropdown(SimpleHttpServer.HttpRequest request) {
        try {
            Map<?, ?> body = gson.fromJson(request.body, Map.class);
            if (body == null) body = new java.util.HashMap<>();
            String tagtypName = body.get("tagtypName") != null ? String.valueOf(body.get("tagtypName")).trim() : "";
            if (tagtypName.isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"tagtypName erforderlich\"}");
            }
            Object inObj = body.get("inDropdown");
            boolean inDropdown = Boolean.TRUE.equals(inObj) || "true".equalsIgnoreCase(String.valueOf(inObj)) || "1".equals(String.valueOf(inObj));
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.setConfigValue("tagtyp_dropdown_" + tagtypName, inDropdown ? "1" : "0");
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"inDropdown\":" + inDropdown + "}");
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Setzen Tagtyp-Dropdown", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}");
        }
    }
    
    private SimpleHttpServer.HttpResponse handleGetProgrammById(int id, String uri) {
        try {
            // Tagtyp aus Query-Parameter extrahieren
            String tagtypName = extractTagtypName(uri);
            
            if (tagtypName == null || tagtypName.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Tagtyp-Parameter erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Lese Programm aus Datenbank
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<Programm> programme = dbHelper.getProgrammeByTagtyp(tagtypName.trim());
            
            Programm programm = null;
            for (Programm p : programme) {
                if (p.getId() == id) {
                    programm = p;
                    break;
                }
            }
            
            if (programm == null) {
                String errorJson = "{\"error\":\"Programm mit ID " + id + " nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", errorJson);
            }
            
            String json = gson.toJson(programm);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen des Programms " + id, e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    private SimpleHttpServer.HttpResponse handlePostProgramm(SimpleHttpServer.HttpRequest request, String uri) {
        String postData = request.body;
        
        if (postData == null || postData.isEmpty()) {
            String errorJson = "{\"error\":\"Keine Daten empfangen\"}";
            return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
        }
        
        // Tagtyp aus Query-Parameter extrahieren
        String tagtypName = extractTagtypName(uri);
        
        if (tagtypName == null || tagtypName.trim().isEmpty()) {
            String errorJson = "{\"error\":\"Tagtyp-Parameter erforderlich\"}";
            return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
        }
        
        try {
            Programm programm = gson.fromJson(postData, Programm.class);
            normalizeProgrammMelodieName(programm);
            // Bestimme neue ID (nächste freie Zeile)
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<Programm> existingProgramme = dbHelper.getProgrammeByTagtyp(tagtypName.trim());
            int maxZeile = 2; // Beginne bei 3 (Index 2)
            for (Programm p : existingProgramme) {
                if (p.getId() > maxZeile) {
                    maxZeile = p.getId();
                }
            }
            int newId = maxZeile + 1;
            programm.setId(newId);
            
            // Speichere in Datenbank
            boolean success = dbHelper.saveProgramm(tagtypName.trim(), programm);
            if (success) {
                String json = gson.toJson(programm);
                return new SimpleHttpServer.HttpResponse(201, "application/json", json);
            } else {
                String errorJson = "{\"error\":\"Fehler beim Speichern in Datenbank\"}";
                return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
            }
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Erstellen des Programms", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
        }
    }
    
    private SimpleHttpServer.HttpResponse handlePutProgramm(SimpleHttpServer.HttpRequest request, int id, String uri) {
        String putData = request.body;
        
        if (putData == null || putData.isEmpty()) {
            String errorJson = "{\"error\":\"Keine Daten empfangen\"}";
            return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
        }
        
        // Tagtyp aus Query-Parameter extrahieren
        String tagtypName = extractTagtypName(uri);
        
        if (tagtypName == null || tagtypName.trim().isEmpty()) {
            String errorJson = "{\"error\":\"Tagtyp-Parameter erforderlich\"}";
            return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
        }
        
        try {
            Programm programm = gson.fromJson(putData, Programm.class);
            normalizeProgrammMelodieName(programm);
            programm.setId(id); // Stelle sicher, dass ID korrekt ist
            // Speichere in Datenbank (wie bei POST)
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            boolean success = dbHelper.saveProgramm(tagtypName.trim(), programm);
            
            if (success) {
                String json = gson.toJson(programm);
                return new SimpleHttpServer.HttpResponse(200, "application/json", json);
            } else {
                String errorJson = "{\"error\":\"Fehler beim Speichern in Datenbank\"}";
                return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
            }
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Aktualisieren des Programms", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
        }
    }
    
    /** Entfernt .xls am Ende von melodie_name, damit keine Doppelstarts (z. B. "Messe Sonntag" vs "Messe Sonntag.xls") entstehen. */
    private void normalizeProgrammMelodieName(Programm programm) {
        if (programm == null) return;
        String name = programm.getMelodieName();
        if (name != null && name.length() > 4 && name.toLowerCase().endsWith(".xls")) {
            programm.setMelodieName(name.substring(0, name.length() - 4).trim());
        }
    }

    private SimpleHttpServer.HttpResponse handleDeleteProgramm(int id, String uri) {
        try {
            // Tagtyp aus Query-Parameter extrahieren
            String tagtypName = extractTagtypName(uri);
            
            if (tagtypName == null || tagtypName.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Tagtyp-Parameter erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Lösche aus Datenbank
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.deleteProgramm(tagtypName.trim(), id);
            
            String json = "{\"success\":true,\"message\":\"Programm " + id + " gelöscht\"}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Löschen des Programms " + id, e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
