    /** Minimale Test-UI: nur Anfrage an Platine senden, auf Antwort warten, Zeit anzeigen (kein Lauflicht, kein weiterer Verkehr). */
    private SimpleHttpServer.HttpResponse serveTestPlatinePage() {
        String html = "<!DOCTYPE html>\n" +
                "<html lang=\"de\">\n" +
                "<head>\n" +
                "    <meta charset=\"UTF-8\">\n" +
                "    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n" +
                "    <title>Platine Ping-Test - Turmtechnik</title>\n" +
                "    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n" +
                "    <style>\n" +
                "        .result-box { font-family: monospace; white-space: pre-wrap; background: #f5f5f5; padding: 1rem; border-radius: 0.25rem; }\n" +
                "        .time-ok { color: #198754; font-weight: bold; }\n" +
                "        .time-fail { color: #dc3545; font-weight: bold; }\n" +
                "    </style>\n" +
                "</head>\n" +
                "<body>\n" +
                "    <nav class=\"navbar navbar-dark bg-dark\">\n" +
                "        <div class=\"container-fluid\">\n" +
                "            <a class=\"navbar-brand\" href=\"/\">Turmtechnik</a>\n" +
                "            <a class=\"nav-link text-light\" href=\"/platinen-config.html\">Platinen-Konfiguration</a>\n" +
                "        </div>\n" +
                "    </nav>\n" +
                "    <div class=\"container mt-4\">\n" +
                "        <h1>Platine Ping-Test</h1>\n" +
                "        <p class=\"text-muted\">Nur eine Anfrage senden, auf Antwort warten und Zeit messen. Kein Lauflicht, kein weiterer Verkehr.</p>\n" +
                "        <div class=\"card\">\n" +
                "            <div class=\"card-body\">\n" +
                "                <div class=\"row g-3 align-items-end\">\n" +
                "                    <div class=\"col-md-4\">\n" +
                "                        <label for=\"pingIp\" class=\"form-label\">IP-Adresse</label>\n" +
                "                        <input type=\"text\" class=\"form-control\" id=\"pingIp\" placeholder=\"192.168.1.181\" value=\"\">\n" +
                "                    </div>\n" +
                "                    <div class=\"col-md-2\">\n" +
                "                        <label for=\"pingPort\" class=\"form-label\">Port</label>\n" +
                "                        <input type=\"number\" class=\"form-control\" id=\"pingPort\" value=\"23\" min=\"1\" max=\"65535\">\n" +
                "                    </div>\n" +
                "                    <div class=\"col-md-4\">\n" +
                "                        <button type=\"button\" class=\"btn btn-primary\" id=\"pingBtn\" onclick=\"sendPing()\">Anfrage senden</button>\n" +
                "                    </div>\n" +
                "                </div>\n" +
                "                <div id=\"pingStatus\" class=\"mt-3\" style=\"display: none;\"></div>\n" +
                "                <div id=\"pingResult\" class=\"mt-3\" style=\"display: none;\">\n" +
                "                    <div><strong>Zeit:</strong> <span id=\"pingTime\"></span></div>\n" +
                "                    <div class=\"mt-2\"><strong>Antwort:</strong></div>\n" +
                "                    <div id=\"pingResponse\" class=\"result-box mt-1\"></div>\n" +
                "                </div>\n" +
                "            </div>\n" +
                "        </div>\n" +
                "    </div>\n" +
                "    <script>\n" +
                "        async function sendPing() {\n" +
                "            var ip = document.getElementById('pingIp').value.trim();\n" +
                "            var port = parseInt(document.getElementById('pingPort').value, 10) || 23;\n" +
                "            if (!ip) { alert('Bitte IP-Adresse eingeben.'); return; }\n" +
                "            var btn = document.getElementById('pingBtn');\n" +
                "            var status = document.getElementById('pingStatus');\n" +
                "            var result = document.getElementById('pingResult');\n" +
                "            btn.disabled = true;\n" +
                "            status.style.display = 'block';\n" +
                "            status.className = 'alert alert-info';\n" +
                "            status.textContent = 'Sende Anfrage und warte auf Antwort …';\n" +
                "            result.style.display = 'none';\n" +
                "            try {\n" +
                "                var res = await fetch('/api/platinen/ping', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ip: ip, port: port }) });\n" +
                "                var data = await res.json();\n" +
                "                status.style.display = 'block';\n" +
                "                if (data.ok) {\n" +
                "                    status.className = 'alert alert-success';\n" +
                "                    status.textContent = 'Antwort erhalten (impulsok).';\n" +
                "                } else {\n" +
                "                    status.className = 'alert alert-danger';\n" +
                "                    status.textContent = data.error || 'Keine gültige Antwort (Timeout oder Fehler).';\n" +
                "                }\n" +
                "                result.style.display = 'block';\n" +
                "                var timeEl = document.getElementById('pingTime');\n" +
                "                var ms = data.timeMs != null ? data.timeMs : -1;\n" +
                "                timeEl.textContent = (ms >= 0 ? ms + ' ms' : '–');\n" +
                "                timeEl.className = data.ok ? 'time-ok' : 'time-fail';\n" +
                "                document.getElementById('pingResponse').textContent = data.responsePreview || '(leer)';\n" +
                "            } catch (e) {\n" +
                "                status.className = 'alert alert-danger';\n" +
                "                status.textContent = 'Fehler: ' + (e.message || e);\n" +
                "                result.style.display = 'none';\n" +
                "            }\n" +
                "            btn.disabled = false;\n" +
                "        }\n" +
                "    </script>\n" +
                "</body>\n" +
                "</html>";
        return new SimpleHttpServer.HttpResponse(200, "text/html; charset=UTF-8", html);
    }
    
