    /**
     * Löscht alle Programme eines Programmtags.
     */
    private SimpleHttpServer.HttpResponse handleDeleteAllProgramme(String uri) {
        try {
            // Programmtag und Tagtyp aus Query-Parameter extrahieren
            String programmTyp = extractProgrammTyp(uri);
            String tagtypName = extractTagtypName(uri);
            
            if (programmTyp == null) {
                String errorJson = "{\"error\":\"Parameter 'typ' erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            if (tagtypName == null || tagtypName.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Parameter 'tagtyp' erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Alle Programme des Tagtyps lesen und löschen
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<Programm> programme = dbHelper.getProgrammeByTagtyp(tagtypName.trim());
            
            int deleted = 0;
            for (Programm programm : programme) {
                if (dbHelper.deleteProgramm(tagtypName.trim(), programm.getId())) {
                    deleted++;
                }
            }
            
            String json = "{\"success\":true,\"deleted\":" + deleted + ",\"typ\":\"" + programmTyp + "\",\"tagtyp\":\"" + tagtypName + "\"}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
            
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Löschen aller Programme", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Validiert einen Programmtag.
     */
    private boolean isValidProgrammTyp(String typ) {
        return typ != null && (typ.equals("normal") || typ.equals("festtag_variabel") || 
                              typ.equals("festtag_fest") || typ.equals("benutzer"));
    }
    
    /**
     * Erstellt einen neuen Tagtyp in der Datenbank (KEINE Excel-Datei mehr!).
     */
    private SimpleHttpServer.HttpResponse handleCreateTagtyp(String uri) {
        try {
            // Query-Parameter extrahieren: ?tagtypName=Weihnachten.xls&typ=festtag_variabel
            String tagtypName = null;
            String programmTyp = null;
            
            if (uri.contains("?")) {
                String query = uri.substring(uri.indexOf("?") + 1);
                String[] params = query.split("&");
                for (String param : params) {
                    if (param.startsWith("tagtypName=")) {
                        try {
                            tagtypName = java.net.URLDecoder.decode(param.substring(11), "UTF-8");
                        } catch (Exception e) {
                            tagtypName = param.substring(11);
                        }
                    } else if (param.startsWith("typ=")) {
                        try {
                            programmTyp = java.net.URLDecoder.decode(param.substring(4), "UTF-8");
                        } catch (Exception e) {
                            programmTyp = param.substring(4);
                        }
                    }
                }
            }
            
            if (tagtypName == null || tagtypName.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Parameter 'tagtypName' erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Default: normal, wenn nicht angegeben
            if (programmTyp == null || programmTyp.trim().isEmpty()) {
                programmTyp = "normal";
            }
            
            // Speichere in Datenbank (KEINE Excel-Datei mehr erstellen!)
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            PlatinenDatabaseHelper.Tagtyp tagtyp = dbHelper.saveTagtyp(tagtypName.trim(), programmTyp);
            
            String json = "{\"success\":true,\"message\":\"Tagtyp in Datenbank erstellt: " + tagtypName + "\",\"tagtypName\":\"" + tagtypName.trim() + "\"}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
            
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Erstellen des Tagtyps", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Lädt Modus und alle Platinen aus der Datenbank.
     * Bei Bluetooth-Modus werden MAC-Adresse und Online-Status automatisch von der Bluetooth-Verbindung geladen.
     */
    private SimpleHttpServer.HttpResponse handleGetPlatinenConfig() {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            String modus = dbHelper.getModus();
            // Anzeige = tatsächlich laufender Modus (aus Excel beim Start), damit BL/WIFI in der UI stimmt
            if (StaticVariable.bluetoothMode && !"bluetooth".equals(modus)) {
                modus = "bluetooth";
            } else if (!StaticVariable.bluetoothMode && !"wifi".equals(modus)) {
                modus = "wifi";
            }
            List<Platine> platinen = dbHelper.getAllPlatinen();
            
            // Bei Bluetooth: Nur Platine 1 zurückgeben und Bluetooth-Daten laden
            if ("bluetooth".equals(modus)) {
                List<Platine> bluetoothPlatinen = new java.util.ArrayList<>();
                Platine platine1 = null;
                
                // Suche nach Platine 1
                for (Platine p : platinen) {
                    if (p.platineNummer == 1) {
                        platine1 = p;
                        break;
                    }
                }
                
                // Erstelle Platine 1 falls nicht vorhanden
                if (platine1 == null) {
                    platine1 = new Platine();
                    platine1.platineNummer = 1;
                    platine1.ipAdresse = null;
                    platine1.port = 50210;
                    platine1.aktiv = false;
                    platine1.relaisAnzahl = 32;
                }
                
                // Lade Bluetooth-Daten automatisch
                try {
                    // MAC-Adresse von gepaarten Bluetooth-Geräten
                    if (StaticVariable.myBluetoothAdapter != null && StaticVariable.myBluetoothAdapter.isEnabled()) {
                        java.util.Set<android.bluetooth.BluetoothDevice> pairedDevices = StaticVariable.myBluetoothAdapter.getBondedDevices();
                        if (pairedDevices != null && pairedDevices.size() > 0) {
                            // Nimm das erste gepaarte Gerät
                            android.bluetooth.BluetoothDevice device = pairedDevices.iterator().next();
                            platine1.macAdresse = device.getAddress();
                        }
                    }
                    
                    // Online-Status von StaticVariable.bt_io_ok
                    platine1.online = StaticVariable.bt_io_ok;
                } catch (Exception e) {
                    Log.w(TAG, "Fehler beim Laden der Bluetooth-Daten", e);
                    // Behalte vorhandene Werte aus der Datenbank
                }
                
                bluetoothPlatinen.add(platine1);
                platinen = bluetoothPlatinen;
            }
            
            // Lade Scan-Relais-Wert und berechne Antwortzeit
            int scanRelaisMS = StaticVariable.scanRelaisMS;
            // Antwortzeit: minimalCheckTime = scanRelaisMS / 20 (aus Serial_IoThread)
            int antwortZeitMS = scanRelaisMS / 20; // Minimal-Check-Zeit
            
            // Lade Power off Akku Prozent aus Datenbank
            int powerOffAkkuProzent = dbHelper.getPowerOffAkkuProzent();
            
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("modus", modus);
            result.put("platinen", platinen);
            result.put("scanRelaisMS", scanRelaisMS);
            result.put("antwortZeitMS", antwortZeitMS);
            result.put("powerOffAkkuProzent", powerOffAkkuProzent);
            
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen der Platinen-Konfiguration", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
