    /**
     * Setzt den Power off Akku Prozent Wert.
     */
    private SimpleHttpServer.HttpResponse handlePutPowerOffAkku(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Request-Body erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            java.util.Map<String, Object> data = gson.fromJson(body, java.util.Map.class);
            Object prozentObj = data.get("powerOffAkkuProzent");
            
            if (prozentObj == null) {
                String errorJson = "{\"error\":\"powerOffAkkuProzent erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            int prozent;
            if (prozentObj instanceof Number) {
                prozent = ((Number) prozentObj).intValue();
            } else {
                try {
                    prozent = Integer.parseInt(prozentObj.toString());
                } catch (NumberFormatException e) {
                    String errorJson = "{\"error\":\"Ungültiger Power off Akku Prozent Wert\"}";
                    return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
                }
            }
            
            // Validierung: 0-100%
            if (prozent < 0 || prozent > 100) {
                String errorJson = "{\"error\":\"Power off Akku Prozent muss zwischen 0 und 100 liegen\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Setze Wert in StaticVariable
            StaticVariable.batt_shut_down_level2 = prozent;
            
            // Speichere in Datenbank
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.setPowerOffAkkuProzent(prozent);
            
            // HINWEIS: Excel-Schreib-Operation entfernt, da ExcelReadWrite nur ein Sheet erstellt
            // und dadurch alle anderen Sheets verloren gehen würden.
            // Der Wert wird in StaticVariable und Datenbank gespeichert, was ausreicht.
            // Falls Excel-Synchronisation benötigt wird, muss eine Methode verwendet werden,
            // die alle Sheets behält (z.B. Workbook.createWorkbook(file, originalWorkbook)).
            
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("powerOffAkkuProzent", prozent);
            
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Setzen des Power off Akku Prozent", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
