    private static final Pattern MAC_PATTERN = Pattern.compile("([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}");

    /**
     * Extrahiert MAC-Adresse aus der Scan-Antwort (z. B. "OK 8relais AA:BB:CC:DD:EE:FF").
     */
    private static String extractMacFromResponse(String response) {
        if (response == null || response.isEmpty()) return null;
        Matcher m = MAC_PATTERN.matcher(response);
        return m.find() ? m.group() : null;
    }

    /**
     * Ermittelt die lokale WLAN-IP für den Netzwerk-Scan (Subnetz-Basis).
     */
    private String getLocalIpForScan() {
        if (context == null) return null;
        try {
            Object service = context.getApplicationContext().getSystemService(android.content.Context.WIFI_SERVICE);
            if (service == null) return null;
            android.net.wifi.WifiManager wifiManager = (android.net.wifi.WifiManager) service;
            android.net.wifi.WifiInfo wifiInfo = wifiManager.getConnectionInfo();
            if (wifiInfo == null) return null;
            int ip = wifiInfo.getIpAddress();
            if (ip == 0) return null;
            return (ip & 0xff) + "." + ((ip >> 8) & 0xff) + "." + ((ip >> 16) & 0xff) + "." + ((ip >> 24) & 0xff);
        } catch (Exception e) {
            Log.w(TAG, "WLAN-IP für Scan nicht ermittelt", e);
            return null;
        }
    }
    
    /**
     * POST /api/platinen/ping-sweep – schnelles TCP-Ping auf Port 23 über alle IPs im Subnetz (2–254).
     * Parallel mit kurzem Timeout, um in wenigen Sekunden zu sehen, welche IPs überhaupt erreichbar sind.
     * Liefert: { "reachable": ["192.168.1.5", ...], "subnetPrefix": "192.168.1", "port": 23 }
     */
    private SimpleHttpServer.HttpResponse handlePingSweep() {
        try {
            String localIp = getLocalIpForScan();
            if (localIp == null || localIp.isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Keine WLAN-IP. Gerät muss mit WLAN verbunden sein.\"}");
            }
            int lastDot = localIp.lastIndexOf('.');
            if (lastDot <= 0) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Ungültige IP-Struktur\"}");
            }
            String subnetPrefix = localIp.substring(0, lastDot);
            final int port = 23;
            final int connectTimeoutMs = 400;
            final int maxConcurrent = 25;

            List<String> ips = new ArrayList<>();
            for (int i = 2; i <= 254; i++) {
                String ip = subnetPrefix + "." + i;
                if (ip.equals(localIp)) continue;
                ips.add(ip);
            }
            List<String> reachable = Collections.synchronizedList(new ArrayList<>());
            ExecutorService executor = Executors.newFixedThreadPool(maxConcurrent);
            for (final String ip : ips) {
                executor.submit(() -> {
                    Socket s = null;
                    try {
                        s = new Socket();
                        s.connect(new InetSocketAddress(ip, port), connectTimeoutMs);
                        reachable.add(ip);
                    } catch (Exception ignored) {
                    } finally {
                        if (s != null) {
                            try { s.close(); } catch (IOException ignored) { }
                        }
                    }
                });
            }
            executor.shutdown();
            executor.awaitTermination(90, TimeUnit.SECONDS);

            Map<String, Object> result = new HashMap<>();
            result.put("subnetPrefix", subnetPrefix);
            result.put("port", port);
            result.put("reachable", reachable);
            result.put("count", reachable.size());
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(result));
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Ping-Sweep", e);
            String err = e.getMessage() != null ? e.getMessage().replace("\"", "'") : "Fehler";
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + err + "\"}");
        }
    }

