    /**
     * Liest alle Nebenuhr-Konfigurationen aus der Datenbank.
     */
    private SimpleHttpServer.HttpResponse handleGetNebenuhren() {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            int mondImpulseProPhase = dbHelper.getMondImpulseProPhase();
            List<PlatinenDatabaseHelper.NebenuhrConfig> nebenuhren = dbHelper.getAllNebenuhren();
            Log.d(TAG, "handleGetNebenuhren: " + nebenuhren.size() + " Nebenuhren gefunden");
            
            java.util.List<java.util.Map<String, Object>> nebenuhrenList = new java.util.ArrayList<>();
            
            for (PlatinenDatabaseHelper.NebenuhrConfig nebenuhr : nebenuhren) {
                Log.d(TAG, "Nebenuhr geladen: " + nebenuhr.uhrName + " (Zeile " + nebenuhr.zeile + "), Modus=" + nebenuhr.modus);
                java.util.Map<String, Object> nebenuhrMap = new java.util.HashMap<>();
                nebenuhrMap.put("uhrName", nebenuhr.uhrNameDisplay != null ? nebenuhr.uhrNameDisplay : nebenuhr.uhrName);
                nebenuhrMap.put("zeile", nebenuhr.zeile);
                nebenuhrMap.put("relaisA", nebenuhr.relaisA);
                nebenuhrMap.put("relaisB", nebenuhr.relaisB);
                nebenuhrMap.put("impulsDauer1", nebenuhr.impulsDauer1);
                nebenuhrMap.put("impulsDauer2", nebenuhr.impulsDauer2);
                nebenuhrMap.put("modus", nebenuhr.modus != null ? nebenuhr.modus : "12");
                nebenuhrMap.put("aktiv", nebenuhr.aktiv);
                int liveAnzeige = nebenuhr.angezeigteZeit;
                int liveMond = nebenuhr.mondphaseIst;
                if (nebenuhr.zeile == 3) liveAnzeige = StaticVariable.uhrA_angezeigteZeit;
                else if (nebenuhr.zeile == 4) liveAnzeige = StaticVariable.uhrB_angezeigteZeit;
                else if (nebenuhr.zeile == 5) liveAnzeige = StaticVariable.uhrC_angezeigteZeit;
                else if (nebenuhr.zeile == 6) liveMond = StaticVariable.uhrD_mondphaseIst;
                nebenuhrMap.put("angezeigteZeit", liveAnzeige);
                nebenuhrMap.put("mondphaseIst", liveMond);
                if (nebenuhr.zeile == 6) {
                    nebenuhrMap.put("mondImpulseProPhase", mondImpulseProPhase);
                }
                nebenuhrenList.add(nebenuhrMap);
            }
            
            java.util.Map<String, Object> response = new java.util.HashMap<>();
            response.put("nebenuhren", nebenuhrenList);
            
            String json = gson.toJson(response);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
            
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Lesen der Nebenuhr-Konfiguration", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
