    private SimpleHttpServer.HttpResponse handleGetRelaisZuordnung(String uri) {
        try {
            Integer kategorieId = null;
            if (uri != null && uri.contains("kategorie_id=")) {
                int idx = uri.indexOf("kategorie_id=");
                String rest = uri.substring(idx + 13);
                int end = rest.indexOf('&');
                String val = end >= 0 ? rest.substring(0, end) : rest;
                try { kategorieId = Integer.parseInt(val.trim()); } catch (NumberFormatException ignored) {}
            }
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.RelaisZuordnung> list = dbHelper.getAllRelaisZuordnung(kategorieId);
            List<PlatinenDatabaseHelper.RelaisKategorie> kategorien = dbHelper.getAllRelaisKategorien();
            Map<Integer, String> kategorieNames = new HashMap<>();
            for (PlatinenDatabaseHelper.RelaisKategorie k : kategorien) kategorieNames.put(k.id, k.name != null ? k.name : "");
            List<Map<String, Object>> out = new ArrayList<>();
            for (PlatinenDatabaseHelper.RelaisZuordnung z : list) {
                Map<String, Object> m = new HashMap<>();
                m.put("id", z.id);
                m.put("software_relais_id", z.softwareRelaisId);
                m.put("name", z.name != null ? z.name : "");
                m.put("kategorie_id", z.kategorieId);
                m.put("kategorie_name", z.kategorieId != null ? kategorieNames.get(z.kategorieId) : null);
                m.put("platine_nummer", z.platineNummer);
                m.put("relais_nummer", z.relaisNummer);
                out.add(m);
            }
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(out));
        } catch (Exception e) {
            Log.e(TAG, "Fehler GET relais-zuordnung", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }
    
    private SimpleHttpServer.HttpResponse handlePostRelaisZuordnung(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body != null ? request.body.trim() : "";
            if (body.isEmpty()) return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Body erforderlich\"}");
            Map<String, Object> data = gson.fromJson(body, Map.class);
            int softwareRelaisId = data.get("software_relais_id") != null ? ((Number) data.get("software_relais_id")).intValue() : 0;
            String name = data.get("name") != null ? String.valueOf(data.get("name")).trim() : "";
            Object ko = data.get("kategorie_id");
            Integer kategorieId = (ko == null) ? null : ((Number) ko).intValue();
            int platineNummer = data.get("platine_nummer") != null ? ((Number) data.get("platine_nummer")).intValue() : 1;
            int relaisNummer = data.get("relais_nummer") != null ? ((Number) data.get("relais_nummer")).intValue() : 1;
            if (platineNummer < 1 || platineNummer > 4) return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"platine_nummer 1-4\"}");
            if (relaisNummer < 1 || relaisNummer > 32) return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"relais_nummer 1-32\"}");
            PlatinenDatabaseHelper.RelaisZuordnung z = new PlatinenDatabaseHelper.RelaisZuordnung();
            z.softwareRelaisId = softwareRelaisId;
            z.name = name;
            z.kategorieId = kategorieId;
            z.platineNummer = platineNummer;
            z.relaisNummer = relaisNummer;
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            long id = dbHelper.insertRelaisZuordnung(z);
            Map<String, Object> out = new HashMap<>();
            out.put("id", (int) id);
            out.put("software_relais_id", softwareRelaisId);
            out.put("name", name);
            out.put("kategorie_id", kategorieId);
            out.put("platine_nummer", platineNummer);
            out.put("relais_nummer", relaisNummer);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(out));
        } catch (Exception e) {
            Log.e(TAG, "Fehler POST relais-zuordnung", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }
    
    private SimpleHttpServer.HttpResponse handlePutRelaisZuordnung(SimpleHttpServer.HttpRequest request, int id) {
        try {
            String body = request.body != null ? request.body.trim() : "";
            if (body.isEmpty()) return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Body erforderlich\"}");
            Map<String, Object> data = gson.fromJson(body, Map.class);
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            PlatinenDatabaseHelper.RelaisZuordnung z = dbHelper.getRelaisZuordnungById(id);
            if (z == null) return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Zuordnung nicht gefunden\"}");
            if (data.get("software_relais_id") != null) z.softwareRelaisId = ((Number) data.get("software_relais_id")).intValue();
            if (data.get("name") != null) z.name = String.valueOf(data.get("name")).trim();
            Object ko = data.get("kategorie_id");
            z.kategorieId = (ko == null) ? z.kategorieId : ((Number) ko).intValue();
            if (data.get("platine_nummer") != null) z.platineNummer = ((Number) data.get("platine_nummer")).intValue();
            if (data.get("relais_nummer") != null) z.relaisNummer = ((Number) data.get("relais_nummer")).intValue();
            if (z.platineNummer < 1 || z.platineNummer > 4) return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"platine_nummer 1-4\"}");
            if (z.relaisNummer < 1 || z.relaisNummer > 32) return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"relais_nummer 1-32\"}");
            dbHelper.updateRelaisZuordnung(z);
            Map<String, Object> out = new HashMap<>();
            out.put("id", z.id);
            out.put("software_relais_id", z.softwareRelaisId);
            out.put("name", z.name);
            out.put("kategorie_id", z.kategorieId);
            out.put("platine_nummer", z.platineNummer);
            out.put("relais_nummer", z.relaisNummer);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(out));
        } catch (Exception e) {
            Log.e(TAG, "Fehler PUT relais-zuordnung", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }
    
    private SimpleHttpServer.HttpResponse handleDeleteRelaisZuordnung(int id) {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.deleteRelaisZuordnung(id);
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true}");
        } catch (Exception e) {
            Log.e(TAG, "Fehler DELETE relais-zuordnung", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }
    
    private SimpleHttpServer.HttpResponse handleGetRelaisZuordnungAufloesen(String uri) {
        try {
            int softwareId = 0;
            if (uri != null && uri.contains("software_id=")) {
                int idx = uri.indexOf("software_id=");
                String rest = uri.substring(idx + 12);
                int end = rest.indexOf('&');
                String val = end >= 0 ? rest.substring(0, end) : rest;
                try { softwareId = Integer.parseInt(val.trim()); } catch (NumberFormatException ignored) {}
            }
            if (softwareId == 0) return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"software_id erforderlich\"}");
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            int[] hw = dbHelper.resolveSoftwareRelaisToHardware(softwareId);
            if (hw == null) return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Software-Relais nicht gefunden\"}");
            Map<String, Object> out = new HashMap<>();
            out.put("platine_nummer", hw[0]);
            out.put("relais_nummer", hw[1]);
            return new SimpleHttpServer.HttpResponse(200, "application/json", gson.toJson(out));
        } catch (Exception e) {
            Log.e(TAG, "Fehler GET relais-zuordnung/aufloesen", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + escapeJsonString(e.getMessage()) + "\"}");
        }
    }
    
    /**
     * Speichert Nebenuhr-Konfigurationen in der Datenbank (NICHT in Excel!).
     */
    private SimpleHttpServer.HttpResponse handlePutNebenuhren(SimpleHttpServer.HttpRequest request) {
        Log.d(TAG, "handlePutNebenuhren aufgerufen");
        try {
            String body = request.body;
            Log.d(TAG, "Request-Body: " + (body != null ? body.substring(0, Math.min(500, body.length())) : "null"));
            if (body == null || body.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Request-Body erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // JSON parsen
            java.util.Map<String, Object> data = gson.fromJson(body, java.util.Map.class);
            java.util.List<java.util.Map<String, Object>> nebenuhren = 
                (java.util.List<java.util.Map<String, Object>>) data.get("nebenuhren");
            
            if (nebenuhren == null || nebenuhren.isEmpty()) {
                String errorJson = "{\"error\":\"Keine Nebenuhren-Daten gefunden\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            
            for (java.util.Map<String, Object> nebenuhrMap : nebenuhren) {
                Object zeileObj = nebenuhrMap.get("zeile");
                if (zeileObj == null) {
                    Log.e(TAG, "FEHLER: zeile fehlt in nebenuhrMap: " + nebenuhrMap);
                    continue;
                }
                
                int zeile;
                if (zeileObj instanceof Double) {
                    zeile = ((Double) zeileObj).intValue();
                } else if (zeileObj instanceof Integer) {
                    zeile = (Integer) zeileObj;
                } else {
                    Log.e(TAG, "FEHLER: zeile hat ungültigen Typ: " + zeileObj.getClass().getName());
                    continue;
                }
                
                if (zeile < 3 || zeile > 6) {
                    Log.e(TAG, "FEHLER: zeile außerhalb des gültigen Bereichs: " + zeile);
                    continue;
                }
                
                Log.d(TAG, "Verarbeite Nebenuhr mit zeile=" + zeile + ", Map=" + nebenuhrMap);
                
                // Bestimme Uhr-Name basierend auf Zeile
                String uhrName = (zeile == 3 ? "A" : (zeile == 4 ? "B" : (zeile == 5 ? "C" : "D")));
                Log.d(TAG, "Lade Nebenuhr " + uhrName + " (Zeile " + zeile + ") aus Datenbank");
                
                // WICHTIG: Lade bestehende Konfiguration aus Datenbank, damit alle Felder erhalten bleiben
                PlatinenDatabaseHelper.NebenuhrConfig nebenuhr = dbHelper.getNebenuhrByZeile(zeile);
                
                // Falls nicht vorhanden, erstelle neue Konfiguration
                if (nebenuhr == null) {
                    Log.w(TAG, "Nebenuhr " + uhrName + " (Zeile " + zeile + ") nicht in DB gefunden, erstelle neue Konfiguration");
                    nebenuhr = new PlatinenDatabaseHelper.NebenuhrConfig();
                    nebenuhr.uhrName = uhrName;
                    nebenuhr.zeile = zeile;
                    nebenuhr.relaisA = (zeile < 6) ? (10 + (zeile - 3) * 2) : 16; // Monduhr D: Relais 16
                    nebenuhr.relaisB = (zeile < 6) ? (11 + (zeile - 3) * 2) : 17; // Monduhr D: Relais 17
                    nebenuhr.impulsDauer1 = 1;
                    nebenuhr.impulsDauer2 = 1;
                    nebenuhr.modus = (zeile == 6) ? "MOND" : "12";
                    nebenuhr.angezeigteZeit = 0;
                    nebenuhr.mondphaseIst = 0;
                    nebenuhr.lastRelaisA = false;
                    nebenuhr.aktiv = true;
                    nebenuhr.uhrNameDisplay = (zeile == 6) ? "Monduhr D" : uhrName;
                } else {
                    Log.d(TAG, "Nebenuhr " + uhrName + " (Zeile " + zeile + ") aus DB geladen: RelaisA=" + nebenuhr.relaisA + ", RelaisB=" + nebenuhr.relaisB + ", Modus=" + nebenuhr.modus);
                }
                
                // Aktualisiere nur die Felder, die im Request gesendet wurden
                
                // Relais A
                Object relaisAObj = nebenuhrMap.get("relaisA");
                if (relaisAObj != null) {
                    int oldRelaisA = nebenuhr.relaisA;
                    try {
                        if (relaisAObj instanceof Double) {
                            nebenuhr.relaisA = ((Double) relaisAObj).intValue();
                        } else if (relaisAObj instanceof Integer) {
                            nebenuhr.relaisA = (Integer) relaisAObj;
                        } else if (relaisAObj instanceof String) {
                            nebenuhr.relaisA = Integer.parseInt((String) relaisAObj);
                        } else {
                            nebenuhr.relaisA = Integer.parseInt(relaisAObj.toString());
                        }
                        Log.d(TAG, "Relais A für " + uhrName + " (Zeile " + zeile + ") geändert: " + oldRelaisA + " -> " + nebenuhr.relaisA);
                    } catch (Exception e) {
                        Log.e(TAG, "Fehler beim Konvertieren von relaisA: " + relaisAObj + " (" + relaisAObj.getClass().getName() + ")", e);
                    }
                } else {
                    Log.w(TAG, "WARNUNG: relaisA nicht im Request für " + uhrName + " (Zeile " + zeile + ")");
                }
                
                // Relais B
                Object relaisBObj = nebenuhrMap.get("relaisB");
                if (relaisBObj != null) {
                    int oldRelaisB = nebenuhr.relaisB;
                    try {
                        if (relaisBObj instanceof Double) {
                            nebenuhr.relaisB = ((Double) relaisBObj).intValue();
                        } else if (relaisBObj instanceof Integer) {
                            nebenuhr.relaisB = (Integer) relaisBObj;
                        } else if (relaisBObj instanceof String) {
                            nebenuhr.relaisB = Integer.parseInt((String) relaisBObj);
                        } else {
                            nebenuhr.relaisB = Integer.parseInt(relaisBObj.toString());
                        }
                        Log.d(TAG, "Relais B für " + uhrName + " (Zeile " + zeile + ") geändert: " + oldRelaisB + " -> " + nebenuhr.relaisB);
                    } catch (Exception e) {
                        Log.e(TAG, "Fehler beim Konvertieren von relaisB: " + relaisBObj + " (" + relaisBObj.getClass().getName() + ")", e);
                    }
                } else {
                    Log.w(TAG, "WARNUNG: relaisB nicht im Request für " + uhrName + " (Zeile " + zeile + ")");
                }
                
                // Impuls-Dauer 1
                Object impulsDauer1Obj = nebenuhrMap.get("impulsDauer1");
                if (impulsDauer1Obj != null) {
                    nebenuhr.impulsDauer1 = (impulsDauer1Obj instanceof Double) 
                        ? ((Double) impulsDauer1Obj).intValue() 
                        : ((Integer) impulsDauer1Obj);
                }
                
                // Impuls-Dauer 2
                Object impulsDauer2Obj = nebenuhrMap.get("impulsDauer2");
                if (impulsDauer2Obj != null) {
                    nebenuhr.impulsDauer2 = (impulsDauer2Obj instanceof Double) 
                        ? ((Double) impulsDauer2Obj).intValue() 
                        : ((Integer) impulsDauer2Obj);
                }

                if (zeile == 6) {
                    Object mondImpulseObj = nebenuhrMap.get("mondImpulseProPhase");
                    if (mondImpulseObj != null) {
                        try {
                            int mondImpulse = (mondImpulseObj instanceof Number)
                                ? ((Number) mondImpulseObj).intValue()
                                : Integer.parseInt(mondImpulseObj.toString());
                            dbHelper.setMondImpulseProPhase(mondImpulse);
                            Log.d(TAG, "Monduhr Impulse pro Phase gesetzt: " + mondImpulse);
                        } catch (Exception e) {
                            Log.e(TAG, "Fehler beim Konvertieren von mondImpulseProPhase: " + mondImpulseObj, e);
                        }
                    }
                }
                
                // Modus
                Object modusObj = nebenuhrMap.get("modus");
                if (modusObj != null) {
                    String modusStr = modusObj.toString();
                    nebenuhr.modus = modusStr;
                    Log.d(TAG, "Modus für " + uhrName + " (Zeile " + zeile + ") gesetzt: " + modusStr);
                    // Für Monduhr D: Stelle sicher, dass Modus "MOND" ist
                    if (zeile == 6 && !"MOND".equals(modusStr)) {
                        Log.w(TAG, "WARNUNG: Monduhr D (Zeile 6) hat Modus " + modusStr + ", setze auf MOND");
                        nebenuhr.modus = "MOND";
                    }
                } else if (zeile == 6) {
                    // Für Monduhr D: Falls Modus nicht gesendet wurde, setze auf "MOND"
                    Log.d(TAG, "Modus für Monduhr D (Zeile 6) nicht gesendet, setze auf MOND");
                    nebenuhr.modus = "MOND";
                }
                
                // Aktiv
                Object aktivObj = nebenuhrMap.get("aktiv");
                if (aktivObj != null) {
                    nebenuhr.aktiv = (aktivObj instanceof Boolean) ? (Boolean) aktivObj : 
                                     (aktivObj.toString().equals("true") || aktivObj.toString().equals("1"));
                }
                
                // Angezeigte Zeit (Minuten seit Mitternacht, 0–1439) – für Layout/Anzeige
                Object angezeigteZeitObj = nebenuhrMap.get("angezeigteZeit");
                if (angezeigteZeitObj != null) {
                    try {
                        int val = (angezeigteZeitObj instanceof Number) ? ((Number) angezeigteZeitObj).intValue() : Integer.parseInt(angezeigteZeitObj.toString());
                        if (val >= 0 && val <= 719) nebenuhr.angezeigteZeit = val;
                    } catch (Exception ignored) { }
                }
                
                // Mondphase Ist (nur für Monduhr D, nur wenn gesendet)
                Object mondphaseIstObj = nebenuhrMap.get("mondphaseIst");
                if (mondphaseIstObj != null && ("MOND".equals(nebenuhr.modus) || zeile == 6)) {
                    int mondImpulseProPhase = dbHelper.getMondImpulseProPhase();
                    int mondphaseIst = (mondphaseIstObj instanceof Double)
                        ? ((Double) mondphaseIstObj).intValue()
                        : ((Integer) mondphaseIstObj);
                    nebenuhr.mondphaseIst = PlatinenDatabaseHelper.normalizeMondphase(mondphaseIst, mondImpulseProPhase);
                }
                
                // Uhr-Name (Display)
                Object uhrNameObj = nebenuhrMap.get("uhrName");
                if (uhrNameObj != null) {
                    nebenuhr.uhrNameDisplay = uhrNameObj.toString().trim();
                }
                
                // In Datenbank speichern
                try {
                    Log.d(TAG, "Speichere Nebenuhr " + nebenuhr.uhrName + " (Zeile " + zeile + ") mit Werten: RelaisA=" + nebenuhr.relaisA + ", RelaisB=" + nebenuhr.relaisB + ", Impuls1=" + nebenuhr.impulsDauer1 + ", Impuls2=" + nebenuhr.impulsDauer2 + ", Modus=" + nebenuhr.modus + ", Aktiv=" + nebenuhr.aktiv);
                    dbHelper.saveNebenuhr(nebenuhr);
                    Log.d(TAG, "Nebenuhr " + nebenuhr.uhrName + " (Zeile " + zeile + ") erfolgreich gespeichert");
                    
                    // Flag setzen, damit Thread die Konfiguration neu lädt
                    if (zeile == 3) {
                        StaticVariable.nebenuhrA_configNeuLaden = true;
                        Log.d(TAG, "Flag gesetzt: Nebenuhr A soll Konfiguration neu laden");
                    } else if (zeile == 4) {
                        StaticVariable.nebenuhrB_configNeuLaden = true;
                        Log.d(TAG, "Flag gesetzt: Nebenuhr B soll Konfiguration neu laden");
                    } else if (zeile == 5) {
                        StaticVariable.nebenuhrC_configNeuLaden = true;
                        Log.d(TAG, "Flag gesetzt: Nebenuhr C soll Konfiguration neu laden");
                    } else if (zeile == 6) {
                        StaticVariable.nebenuhrD_configNeuLaden = true;
                        Log.d(TAG, "Flag gesetzt: Nebenuhr D (Monduhr) soll Konfiguration neu laden");
                    }
                } catch (Exception saveEx) {
                    Log.e(TAG, "FEHLER beim Speichern der Nebenuhr " + nebenuhr.uhrName + " (Zeile " + zeile + "):", saveEx);
                    saveEx.printStackTrace();
                    throw saveEx; // Weiterwerfen, damit es im catch-Block behandelt wird
                }
            }
            
            String json = "{\"success\":true,\"message\":\"Nebenuhr-Konfiguration in Datenbank gespeichert\"}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
            
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Speichern der Nebenuhr-Konfiguration", e);
            e.printStackTrace();
            String errorMsg = e.getMessage() != null ? e.getMessage() : e.toString();
            String errorJson = "{\"error\":\"" + errorMsg.replace("\"", "\\\"") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Liefert Schlagwerk-Konfiguration (Typ 1 und 2) aus der DB.
     */
    private SimpleHttpServer.HttpResponse handleGetSchlagwerk() {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.SchlagwerkConfig> configs = dbHelper.getAllSchlagwerkConfigs();
            java.util.List<java.util.Map<String, Object>> list = new java.util.ArrayList<>();
            for (PlatinenDatabaseHelper.SchlagwerkConfig c : configs) {
                java.util.Map<String, Object> m = new java.util.HashMap<>();
                m.put("id", c.id);
                m.put("typ", c.typ);
                m.put("startZeit", c.startZeit != null ? c.startZeit : "");
                m.put("endeZeit", c.endeZeit != null ? c.endeZeit : "");
                m.put("hammerStundenRelais", c.hammerStundenRelais);
                m.put("hammerViertelRelais", c.hammerViertelRelais);
                m.put("pauseViertelMs", c.pauseViertelMs);
                m.put("pauseViertelZuStundeMs", c.pauseViertelZuStundeMs);
                m.put("halbstundeSchlaganzahl", c.halbstundeSchlaganzahl);
                m.put("volleStundeAnzahl", c.volleStundeAnzahl);
                m.put("schlagenWennMelodieLaeuft", c.schlagenWennMelodieLaeuft);
                m.put("keinSchlagwerkOstern", c.keinSchlagwerkOstern);
                m.put("keinSchlagwerkKarfreitag", c.keinSchlagwerkKarfreitag);
                m.put("keinSchlagwerkKarsamstag", c.keinSchlagwerkKarsamstag);
                m.put("aktiv", c.aktiv);
                m.put("sortierung", c.sortierung);
                list.add(m);
            }
            java.util.Map<String, Object> response = new java.util.HashMap<>();
            response.put("configs", list);
            String json = gson.toJson(response);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Lesen der Schlagwerk-Konfiguration", e);
            String errorJson = "{\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "\\\"") : "") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Speichert Schlagwerk-Konfiguration (Typ 1 und 2) in der DB.
     */
    private SimpleHttpServer.HttpResponse handlePutSchlagwerk(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Request-Body erforderlich\"}");
            }
            java.util.Map<String, Object> data = gson.fromJson(body, java.util.Map.class);
            @SuppressWarnings("unchecked")
            java.util.List<java.util.Map<String, Object>> configs = (java.util.List<java.util.Map<String, Object>>) data.get("configs");
            if (configs == null || configs.isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"error\":\"Keine Schlagwerk-Daten\"}");
            }
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            for (java.util.Map<String, Object> map : configs) {
                Object typObj = map.get("typ");
                if (typObj == null) continue;
                int typ = typObj instanceof Double ? ((Double) typObj).intValue() : ((Number) typObj).intValue();
                PlatinenDatabaseHelper.SchlagwerkConfig existing = dbHelper.getSchlagwerkConfigByTyp(typ);
                if (existing == null) continue;
                if (map.get("startZeit") != null) existing.startZeit = map.get("startZeit").toString().trim();
                if (map.get("endeZeit") != null) existing.endeZeit = map.get("endeZeit").toString().trim();
                if (map.containsKey("hammerStundenRelais")) existing.hammerStundenRelais = getIntFromMap(map, "hammerStundenRelais", 0);
                if (map.containsKey("hammerViertelRelais")) existing.hammerViertelRelais = getIntFromMap(map, "hammerViertelRelais", 0);
                if (map.containsKey("pauseViertelMs")) existing.pauseViertelMs = getIntFromMap(map, "pauseViertelMs", 0);
                if (map.containsKey("pauseViertelZuStundeMs")) existing.pauseViertelZuStundeMs = getIntFromMap(map, "pauseViertelZuStundeMs", 0);
                if (map.containsKey("halbstundeSchlaganzahl")) existing.halbstundeSchlaganzahl = Math.min(2, Math.max(1, getIntFromMap(map, "halbstundeSchlaganzahl", 1)));
                if (map.containsKey("volleStundeAnzahl")) existing.volleStundeAnzahl = Math.min(12, Math.max(1, getIntFromMap(map, "volleStundeAnzahl", 12)));
                if (map.get("schlagenWennMelodieLaeuft") != null) existing.schlagenWennMelodieLaeuft = Boolean.TRUE.equals(map.get("schlagenWennMelodieLaeuft")) || "true".equals(map.get("schlagenWennMelodieLaeuft").toString());
                if (map.get("aktiv") != null) existing.aktiv = Boolean.TRUE.equals(map.get("aktiv")) || "true".equals(map.get("aktiv").toString());
                if (map.get("keinSchlagwerkOstern") != null) existing.keinSchlagwerkOstern = Boolean.TRUE.equals(map.get("keinSchlagwerkOstern")) || "true".equals(map.get("keinSchlagwerkOstern").toString());
                if (map.get("keinSchlagwerkKarfreitag") != null) existing.keinSchlagwerkKarfreitag = Boolean.TRUE.equals(map.get("keinSchlagwerkKarfreitag")) || "true".equals(map.get("keinSchlagwerkKarfreitag").toString());
                if (map.get("keinSchlagwerkKarsamstag") != null) existing.keinSchlagwerkKarsamstag = Boolean.TRUE.equals(map.get("keinSchlagwerkKarsamstag")) || "true".equals(map.get("keinSchlagwerkKarsamstag").toString());
                if (existing.startZeit == null || existing.startZeit.isEmpty()) existing.startZeit = "08:00";
                if (existing.endeZeit == null || existing.endeZeit.isEmpty()) existing.endeZeit = "18:00";
                dbHelper.saveSchlagwerkConfig(existing);
            }
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"message\":\"Schlagwerk gespeichert\"}");
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Speichern der Schlagwerk-Konfiguration", e);
            String msg = e.getMessage() != null ? e.getMessage().replace("\"", "\\\"") : "";
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + msg + "\"}");
        }
    }
    
    /** POST /api/schlagwerk/test – Test-Schlag ausführen. Nutzt Relais aus Schlagwerk-Config, Relais-An-Zeit (Pulsdauer) aus Hammer (Beschriftung Tasten c4). */
    private static final int SCHLAGWERK_TEST_PULSE_MS_DEFAULT = 50;

    /** Liefert die Hammer-Relais-An-Zeit in ms für das gegebene berechnete Relais. Sucht in Beschriftung Tasten nach Hammer-Zelle mit diesem Relais, liest c4 (Hammerzeit); Formel wie in TurmtechnikActivity: c4 * 10 = ms. */
    private static int getHammerPulseMsFromBeschriftung(android.content.Context ctx, int relaisBerechnet) {
        if (ctx == null || relaisBerechnet <= 0) return SCHLAGWERK_TEST_PULSE_MS_DEFAULT;
        try {
            java.util.List<PlatinenDatabaseHelper.BeschriftungTastenRow> rows = PlatinenDatabaseHelper.getInstance(ctx).getBeschriftungTasten();
            if (rows == null) return SCHLAGWERK_TEST_PULSE_MS_DEFAULT;
            for (PlatinenDatabaseHelper.BeschriftungTastenRow r : rows) {
                String c1 = r.c1 != null ? r.c1.trim() : "";
                if (!"Hammer".equalsIgnoreCase(c1)) continue;
                int rel = 0, plat = 1;
                try {
                    if (r.c3 != null && !r.c3.trim().isEmpty()) rel = Integer.parseInt(r.c3.trim());
                    if (r.c5 != null && !r.c5.trim().isEmpty()) plat = Integer.parseInt(r.c5.trim());
                } catch (NumberFormatException e) { continue; }
                int berechnet = rel + (plat - 1) * 32;
                if (berechnet != relaisBerechnet) continue;
                String c4 = r.c4 != null ? r.c4.trim() : "";
                if (c4.isEmpty() || "null".equalsIgnoreCase(c4) || "leer".equalsIgnoreCase(c4)) return SCHLAGWERK_TEST_PULSE_MS_DEFAULT;
                int ms = (int) (Double.parseDouble(c4) * 10);
                return ms > 0 ? ms : SCHLAGWERK_TEST_PULSE_MS_DEFAULT;
            }
            if (StaticVariable.schlagWerkVariable1 > 0) return StaticVariable.schlagWerkVariable1;
        } catch (Exception e) {
            if (StaticVariable.schlagWerkVariable1 > 0) return StaticVariable.schlagWerkVariable1;
        }
        return SCHLAGWERK_TEST_PULSE_MS_DEFAULT;
    }

    private SimpleHttpServer.HttpResponse handlePostSchlagwerkTest(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body != null ? request.body.trim() : "";
            if (body.isEmpty()) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Body erforderlich\"}");
            }
            com.google.gson.JsonObject obj = gson.fromJson(body, com.google.gson.JsonObject.class);
            if (obj == null || !obj.has("typ") || !obj.has("test")) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"typ und test erforderlich\"}");
            }
            int typ = obj.get("typ").getAsInt();
            if (typ != 1 && typ != 2) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"typ muss 1 oder 2 sein\"}");
            }
            String test = obj.get("test").getAsString();
            if (test == null) test = "";
            String[] allowed = { "viertel1", "viertel2", "viertel3", "viertel4", "stunde", "stundeAktuell" };
            boolean ok = false;
            for (String a : allowed) {
                if (a.equals(test)) { ok = true; break; }
            }
            if (!ok) {
                return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"test ungültig\"}");
            }
            android.content.Context ctx = context != null ? context : TurmtechnikActivity.turmtechnikContext;
            if (ctx == null) {
                return new SimpleHttpServer.HttpResponse(503, "application/json", "{\"success\":false,\"error\":\"Kontext nicht verfügbar\"}");
            }
            PlatinenDatabaseHelper.SchlagwerkConfig config = PlatinenDatabaseHelper.getInstance(ctx).getSchlagwerkConfigByTyp(typ);
            if (config == null) {
                return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"success\":false,\"error\":\"Schlagwerk Typ " + typ + " nicht konfiguriert\"}");
            }
            boolean isStundeAktuell = "stundeAktuell".equals(test);
            boolean useStunde = "stunde".equals(test) || isStundeAktuell;
            int relaisViertel = config.hammerViertelRelais;
            int relaisStunde = config.hammerStundenRelais;
            if (isStundeAktuell) {
                if (relaisViertel <= 0 || relaisStunde <= 0) {
                    return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Stundenschlag (aktuell) benötigt Hammer Viertel und Hammer Stunden in der Schlagwerk-Config.\"}");
                }
            } else if (useStunde) {
                if (relaisStunde <= 0) {
                    return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Bitte Hammer Stunden in der Schlagwerk-Config eintragen.\"}");
                }
            } else {
                if (relaisViertel <= 0) {
                    return new SimpleHttpServer.HttpResponse(400, "application/json", "{\"success\":false,\"error\":\"Bitte Hammer Viertel in der Schlagwerk-Config eintragen.\"}");
                }
            }
            final int relayV = relaisViertel;
            final int relayS = relaisStunde;
            final int pauseViertelMs = Math.max(100, config.pauseViertelMs);
            final int pauseViertelZuStundeMs = Math.max(200, config.pauseViertelZuStundeMs);
            final int pulseViertelMs = getHammerPulseMsFromBeschriftung(ctx, relaisViertel);
            final int pulseStundeMs = getHammerPulseMsFromBeschriftung(ctx, relaisStunde);
            final int anzahlViertel;
            final int anzahlStunde;
            if ("viertel1".equals(test)) { anzahlViertel = 1; anzahlStunde = 0; }
            else if ("viertel2".equals(test)) { anzahlViertel = 2; anzahlStunde = 0; }
            else if ("viertel3".equals(test)) { anzahlViertel = 3; anzahlStunde = 0; }
            else if ("viertel4".equals(test)) { anzahlViertel = 4; anzahlStunde = 0; }
            else if ("stunde".equals(test)) { anzahlViertel = 0; anzahlStunde = 1; }
            else {
                int h = java.util.Calendar.getInstance().get(java.util.Calendar.HOUR);
                anzahlViertel = 4;
                anzahlStunde = (h == 0) ? 12 : h;
            }
            final int nV = anzahlViertel;
            final int nS = anzahlStunde;
            new Thread(new Runnable() {
                @Override
                public void run() {
                    try {
                        int pulseV = pulseViertelMs > 0 ? pulseViertelMs : SCHLAGWERK_TEST_PULSE_MS_DEFAULT;
                        int pulseS = pulseStundeMs > 0 ? pulseStundeMs : SCHLAGWERK_TEST_PULSE_MS_DEFAULT;
                        if (nV > 0) {
                            for (int i = 0; i < nV; i++) {
                                Serial_IoThread.changeRelais(relayV, true);
                                Thread.sleep(pulseV);
                                Serial_IoThread.changeRelais(relayV, false);
                                if (i < nV - 1) Thread.sleep(pauseViertelMs);
                            }
                            if (nS > 0) Thread.sleep(pauseViertelZuStundeMs);
                        }
                        if (nS > 0) {
                            for (int i = 0; i < nS; i++) {
                                Serial_IoThread.changeRelais(relayS, true);
                                Thread.sleep(pulseS);
                                Serial_IoThread.changeRelais(relayS, false);
                                if (i < nS - 1) Thread.sleep(pauseViertelZuStundeMs);
                            }
                        }
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        Serial_IoThread.changeRelais(relayV, false);
                        Serial_IoThread.changeRelais(relayS, false);
                    } catch (Exception e) {
                        Log.e(TAG, "Schlagwerk-Test Fehler", e);
                        Serial_IoThread.changeRelais(relayV, false);
                        Serial_IoThread.changeRelais(relayS, false);
                    }
                }
            }).start();
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"message\":\"Test gestartet\"}");
        } catch (Exception e) {
            Log.e(TAG, "Fehler bei POST /api/schlagwerk/test", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"success\":false,\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "\\\\\"") : "") + "\"}");
        }
    }
    
    private static PlatinenDatabaseHelper.SchlagwerkConfig mapToSchlagwerkConfig(java.util.Map<String, Object> map) {
        Object typObj = map.get("typ");
        if (typObj == null) return null;
        int typ = typObj instanceof Double ? ((Double) typObj).intValue() : ((Number) typObj).intValue();
        PlatinenDatabaseHelper.SchlagwerkConfig c = new PlatinenDatabaseHelper.SchlagwerkConfig();
        c.id = map.get("id") != null ? (map.get("id") instanceof Double ? ((Double) map.get("id")).intValue() : ((Number) map.get("id")).intValue()) : 0;
        c.typ = typ;
        c.startZeit = map.get("startZeit") != null ? map.get("startZeit").toString().trim() : "";
        c.endeZeit = map.get("endeZeit") != null ? map.get("endeZeit").toString().trim() : "";
        c.hammerStundenRelais = getIntFromMap(map, "hammerStundenRelais", 0);
        c.hammerViertelRelais = getIntFromMap(map, "hammerViertelRelais", 0);
        c.pauseViertelMs = getIntFromMap(map, "pauseViertelMs", 0);
        c.pauseViertelZuStundeMs = getIntFromMap(map, "pauseViertelZuStundeMs", 0);
        c.halbstundeSchlaganzahl = getIntFromMap(map, "halbstundeSchlaganzahl", 1);
        c.volleStundeAnzahl = getIntFromMap(map, "volleStundeAnzahl", 12);
        c.schlagenWennMelodieLaeuft = map.get("schlagenWennMelodieLaeuft") != null && (Boolean.TRUE.equals(map.get("schlagenWennMelodieLaeuft")) || "true".equals(map.get("schlagenWennMelodieLaeuft").toString()));
        c.keinSchlagwerkOstern = map.get("keinSchlagwerkOstern") != null && (Boolean.TRUE.equals(map.get("keinSchlagwerkOstern")) || "true".equals(map.get("keinSchlagwerkOstern").toString()));
        c.keinSchlagwerkKarfreitag = map.get("keinSchlagwerkKarfreitag") != null && (Boolean.TRUE.equals(map.get("keinSchlagwerkKarfreitag")) || "true".equals(map.get("keinSchlagwerkKarfreitag").toString()));
        c.keinSchlagwerkKarsamstag = map.get("keinSchlagwerkKarsamstag") != null && (Boolean.TRUE.equals(map.get("keinSchlagwerkKarsamstag")) || "true".equals(map.get("keinSchlagwerkKarsamstag").toString()));
        c.aktiv = map.get("aktiv") != null && (Boolean.TRUE.equals(map.get("aktiv")) || "true".equals(map.get("aktiv").toString()));
        c.sortierung = getIntFromMap(map, "sortierung", typ);
        return c;
    }
    
    private static int getIntFromMap(java.util.Map<String, Object> map, String key, int defaultValue) {
        Object o = map.get(key);
        if (o == null) return defaultValue;
        if (o instanceof Number) return ((Number) o).intValue();
        try { return Integer.parseInt(o.toString()); } catch (NumberFormatException e) { return defaultValue; }
    }
    
    /**
     * Gibt alle Vorschwingen-Konfigurationen zurück.
     */
    private SimpleHttpServer.HttpResponse handleGetVorschwingen() {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.VorschwingenConfig> vorschwingen = dbHelper.getAllVorschwingen();
            Log.d(TAG, "handleGetVorschwingen: " + vorschwingen.size() + " Vorschwingen-Einträge gefunden");
            
            java.util.List<java.util.Map<String, Object>> vorschwingenList = new java.util.ArrayList<>();
            
            for (PlatinenDatabaseHelper.VorschwingenConfig config : vorschwingen) {
                java.util.Map<String, Object> configMap = new java.util.HashMap<>();
                configMap.put("id", config.id);
                configMap.put("vorschwingenRelais", config.vorschwingenRelais);
                configMap.put("laeutenRelais", config.laeutenRelais);
                configMap.put("zeitSekunden", config.zeitSekunden);
                configMap.put("vorschwingenPlatine", config.vorschwingenPlatine);
                configMap.put("laeutenPlatine", config.laeutenPlatine);
                configMap.put("vorschwingenRelaisBerechnet", config.vorschwingenRelaisBerechnet);
                configMap.put("laeutenRelaisBerechnet", config.laeutenRelaisBerechnet);
                configMap.put("aktiv", config.aktiv);
                configMap.put("sortierung", config.sortierung);
                vorschwingenList.add(configMap);
            }
            
            java.util.Map<String, Object> response = new java.util.HashMap<>();
            response.put("vorschwingen", vorschwingenList);
            
            String json = gson.toJson(response);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
            
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Lesen der Vorschwingen-Konfiguration", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Erstellt einen neuen Vorschwingen-Eintrag.
     */
    private SimpleHttpServer.HttpResponse handlePostVorschwingen(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Request-Body erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            java.util.Map<String, Object> data = gson.fromJson(body, java.util.Map.class);
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            
            PlatinenDatabaseHelper.VorschwingenConfig config = new PlatinenDatabaseHelper.VorschwingenConfig();
            config.id = 0; // Neuer Eintrag
            config.vorschwingenRelais = getIntValue(data, "vorschwingenRelais", 0);
            config.laeutenRelais = getIntValue(data, "laeutenRelais", 0);
            config.zeitSekunden = getIntValue(data, "zeitSekunden", 5);
            config.vorschwingenPlatine = getIntValue(data, "vorschwingenPlatine", 1);
            config.laeutenPlatine = getIntValue(data, "laeutenPlatine", 1);
            config.aktiv = getBooleanValue(data, "aktiv", true);
            config.sortierung = getIntValue(data, "sortierung", 0);
            
            dbHelper.saveVorschwingen(config);
            TurmtechnikActivity.reloadVorschwingenFromDatabase(context);
            
            String json = "{\"success\":true,\"message\":\"Vorschwingen-Eintrag erstellt\",\"id\":" + config.id + "}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
            
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Erstellen des Vorschwingen-Eintrags", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Aktualisiert Vorschwingen-Einträge (Array).
     */
    private SimpleHttpServer.HttpResponse handlePutVorschwingen(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Request-Body erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            java.util.Map<String, Object> data = gson.fromJson(body, java.util.Map.class);
            java.util.List<java.util.Map<String, Object>> vorschwingenList = 
                (java.util.List<java.util.Map<String, Object>>) data.get("vorschwingen");
            
            if (vorschwingenList == null || vorschwingenList.isEmpty()) {
                String errorJson = "{\"error\":\"Keine Vorschwingen-Daten gefunden\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            
            for (java.util.Map<String, Object> configMap : vorschwingenList) {
                PlatinenDatabaseHelper.VorschwingenConfig config = new PlatinenDatabaseHelper.VorschwingenConfig();
                config.id = getIntValue(configMap, "id", 0);
                config.vorschwingenRelais = getIntValue(configMap, "vorschwingenRelais", 0);
                config.laeutenRelais = getIntValue(configMap, "laeutenRelais", 0);
                config.zeitSekunden = getIntValue(configMap, "zeitSekunden", 5);
                config.vorschwingenPlatine = getIntValue(configMap, "vorschwingenPlatine", 1);
                config.laeutenPlatine = getIntValue(configMap, "laeutenPlatine", 1);
                config.aktiv = getBooleanValue(configMap, "aktiv", true);
                config.sortierung = getIntValue(configMap, "sortierung", 0);
                
                dbHelper.saveVorschwingen(config);
            }
            TurmtechnikActivity.reloadVorschwingenFromDatabase(context);
            
            String json = "{\"success\":true,\"message\":\"Vorschwingen-Konfiguration in Datenbank gespeichert\"}";
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
            
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Speichern der Vorschwingen-Konfiguration", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
