    /**
     * Hilfsmethode zum Extrahieren von Integer-Werten aus Map.
     */
    private int getIntValue(java.util.Map<String, Object> map, String key, int defaultValue) {
        Object value = map.get(key);
        if (value == null) return defaultValue;
        if (value instanceof Integer) return (Integer) value;
        if (value instanceof Double) return ((Double) value).intValue();
        try {
            return Integer.parseInt(value.toString());
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }
    
    /**
     * Hilfsmethode zum Extrahieren von Boolean-Werten aus Map.
     */
    private boolean getBooleanValue(java.util.Map<String, Object> map, String key, boolean defaultValue) {
        Object value = map.get(key);
        if (value == null) return defaultValue;
        if (value instanceof Boolean) return (Boolean) value;
        return value.toString().equals("true") || value.toString().equals("1");
    }
    
