    private String getBenutzerprogrammeHTML() {
        return "<!DOCTYPE html>\n" +
                "<html lang=\"de\">\n" +
                "<head>\n" +
                "    <meta charset=\"UTF-8\">\n" +
                "    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n" +
                "    <title>Benutzerprogramme - Turmtechnik</title>\n" +
                "    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n" +
                "    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n" +
                "    <style>\n" +
                "        :root { --tt-bg: #0a0a0a; --tt-surface: #141414; --tt-card: #1a1a1a; --tt-border: #2a2a2a; --tt-text: #e8e8e8; --tt-muted: #888; --tt-accent: #c9a227; --tt-accent-hover: #dbb83a; }\n" +
                "        body.benutzer-page { font-family: 'Inter', -apple-system, sans-serif; background: var(--tt-bg); color: var(--tt-text); min-height: 100vh; margin: 0; padding-bottom: 80px; }\n" +
                "        body.benutzer-page .text-muted { color: var(--tt-muted) !important; }\n" +
                "        body.benutzer-page h1 { color: var(--tt-text); font-weight: 600; }\n" +
                "        .benutzer-fixed-bottom { position: fixed; bottom: 0; left: 0; right: 0; z-index: 1000; background: var(--tt-surface); border-top: 1px solid var(--tt-border); padding: 12px 16px; box-shadow: 0 -2px 12px rgba(0,0,0,.3); }\n" +
                "        .benutzer-fixed-bottom .btn-secondary { background: transparent; border-color: var(--tt-border); color: var(--tt-text); }\n" +
                "        .benutzer-fixed-bottom .btn-secondary:hover { background: var(--tt-card); border-color: var(--tt-accent); color: var(--tt-accent); }\n" +
                "        .benutzer-fixed-bottom .btn-success { background: var(--tt-accent); border-color: var(--tt-accent); color: #0a0a0a; }\n" +
                "        .benutzer-fixed-bottom .btn-success:hover { background: var(--tt-accent-hover); border-color: var(--tt-accent-hover); color: #0a0a0a; }\n" +
                "        .benutzer-table-scroll { max-height: calc(100vh - 220px); overflow-y: auto; overflow-x: auto; }\n" +
                "        .benutzer-table { --bs-table-bg: var(--tt-card); --bs-table-border-color: var(--tt-border); --bs-table-color: var(--tt-text); --bs-table-striped-bg: #1f1f1f; --bs-table-hover-bg: #252525; }\n" +
                "        .benutzer-table thead th { position: sticky; top: 0; z-index: 5; background: var(--tt-surface) !important; color: var(--tt-text) !important; border-bottom-color: var(--tt-border); box-shadow: 0 1px 0 var(--tt-border); }\n" +
                "        .benutzer-table tbody tr { background: var(--tt-card); color: var(--tt-text); }\n" +
                "        .benutzer-table td { border-color: var(--tt-border); color: var(--tt-text); vertical-align: middle; }\n" +
                "        .benutzer-table .form-control, .benutzer-table .form-select { background: #111; border-color: var(--tt-border); color: var(--tt-text); }\n" +
                "        .benutzer-table .form-control:focus, .benutzer-table .form-select:focus { background: #151515; border-color: var(--tt-accent); color: var(--tt-text); }\n" +
                "        .benutzer-table .btn-outline-danger { border-color: #8b3a3a; color: #e0a0a0; }\n" +
                "        .benutzer-table .btn-outline-danger:hover { background: #8b3a3a; color: #fff; }\n" +
                "        .benutzer-table .btn-outline-primary { border-color: var(--tt-accent); color: var(--tt-accent); }\n" +
                "        .benutzer-table .btn-outline-primary:hover { background: var(--tt-accent); border-color: var(--tt-accent); color: #0a0a0a; }\n" +
                "        #statusMessage.alert { background: var(--tt-card); border: 1px solid var(--tt-border); }\n" +
                "        #statusMessage.alert-success { background: #1e3a1e; border-color: #2d5a2d; color: #b8e0b8; }\n" +
                "        #statusMessage.alert-danger { background: #3a1e1e; border-color: #5a2d2d; color: #e0b8b8; }\n" +
                "        #modalNeuesProgramm .modal-content { background: var(--tt-card); border: 1px solid var(--tt-border); color: var(--tt-text); }\n" +
                "        #modalNeuesProgramm .modal-header { border-color: var(--tt-border); }\n" +
                "        #modalNeuesProgramm .modal-title { color: var(--tt-text); font-weight: 600; }\n" +
                "        #modalNeuesProgramm .modal-footer { border-color: var(--tt-border); display: flex; gap: 0.5rem; }\n" +
                "        #modalNeuesProgramm .modal-footer .btn { flex: 1; min-width: 0; }\n" +
                "        #modalNeuesProgramm .modal-body .form-label { color: var(--tt-text); }\n" +
                "        #modalNeuesProgramm .form-control, #modalNeuesProgramm .form-select { background: #111; border-color: var(--tt-border); color: var(--tt-text); }\n" +
                "        #modalNeuesProgramm .form-control:focus, #modalNeuesProgramm .form-select:focus { background: #151515; border-color: var(--tt-accent); color: var(--tt-text); }\n" +
                "        #modalNeuesProgramm .form-check-label { color: var(--tt-text); }\n" +
                "        #modalNeuesProgramm .form-check-input { background-color: #111; border-color: var(--tt-border); }\n" +
                "        #modalNeuesProgramm .form-check-input:checked { background-color: var(--tt-accent); border-color: var(--tt-accent); }\n" +
                "        #modalNeuesProgramm .btn-secondary { background: transparent; border-color: var(--tt-border); color: var(--tt-text); }\n" +
                "        #modalNeuesProgramm .btn-primary { background: var(--tt-accent); border-color: var(--tt-accent); color: #0a0a0a; }\n" +
                "        #modalNeuesProgramm .btn-close { filter: invert(1); }\n" +
                "        #modalNeuesProgramm .alert-danger { background: #3a1e1e; border-color: #5a2d2d; color: #e0b8b8; }\n" +
                "        #modalNeuesProgramm #newDatum, #modalNeuesProgramm #newZeit { min-width: 10rem; padding: 0.6rem 0.8rem; font-size: 1.1rem; border: 2px solid var(--tt-border); border-radius: 6px; cursor: pointer; }\n" +
                "        #modalNeuesProgramm #newDatum:hover, #modalNeuesProgramm #newDatum:focus, #modalNeuesProgramm #newZeit:hover, #modalNeuesProgramm #newZeit:focus { border-color: var(--tt-accent); outline: none; }\n" +
                "        #modalNeuesProgramm #newDatum::-webkit-calendar-picker-indicator, #modalNeuesProgramm #newZeit::-webkit-calendar-picker-indicator { filter: invert(1); opacity: 0.9; cursor: pointer; }\n" +
                "        #modalNeuesProgramm #newZeitWrap .form-label { display: block; margin-bottom: 0.5rem; }\n" +
                "        .benutzer-table thead th:nth-child(1) { min-width: 3rem; width: 3rem; }\n" +
                "        .benutzer-table tbody td:nth-child(1) { background: var(--tt-card) !important; color: var(--tt-text) !important; font-weight: 600; min-width: 3rem; width: 3rem; text-align: center; }\n" +
                "        .benutzer-table thead th:nth-child(2) { min-width: 10rem; }\n" +
                "        .benutzer-table thead th:nth-child(3) { min-width: 12rem; }\n" +
                "        .benutzer-table td:nth-child(2) { min-width: 10rem; }\n" +
                "        .benutzer-table td:nth-child(3) { min-width: 12rem; }\n" +
                "        .benutzer-table .benutzer-datum-input { min-width: 10rem; width: 100%; padding: 0.5rem 0.6rem; font-size: 1rem; cursor: pointer; background: var(--tt-surface) !important; border: 2px solid var(--tt-border); border-radius: 6px; color: var(--tt-text); }\n" +
                "        .benutzer-table .benutzer-datum-input:hover, .benutzer-table .benutzer-datum-input:focus { border-color: var(--tt-accent); outline: none; }\n" +
                "        .benutzer-table .benutzer-zeit-wrap { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; min-height: 2.5rem; }\n" +
                "        .benutzer-table .benutzer-zeit-input { min-width: 6rem; padding: 0.5rem 0.6rem; font-size: 1rem; cursor: pointer; background: var(--tt-surface) !important; border: 2px solid var(--tt-border); border-radius: 6px; color: var(--tt-text); }\n" +
                "        .benutzer-table .benutzer-zeit-input:hover, .benutzer-table .benutzer-zeit-input:focus { border-color: var(--tt-accent); outline: none; }\n" +
                "        .benutzer-table .benutzer-zeit-input::-webkit-calendar-picker-indicator { filter: invert(1); opacity: 0.8; cursor: pointer; }\n" +
                "        .benutzer-table input[type=date]::-webkit-calendar-picker-indicator { filter: invert(1); opacity: 0.8; cursor: pointer; }\n" +
                "        .benutzer-table .benutzer-cell-readonly { color: var(--tt-text); padding: 0.5rem 0.75rem; user-select: none; }\n" +
                "    </style>\n" +
                "</head>\n" +
                "<body class=\"benutzer-page\">\n" +
                "    <nav class=\"navbar navbar-expand-lg navbar-dark bg-dark\" style=\"display:none;\">\n" +
                "        <div class=\"container-fluid\">\n" +
                "            <a class=\"navbar-brand\" href=\"/\">Turmtechnik</a>\n" +
                "            <div class=\"navbar-nav\">\n" +
                "                <a class=\"nav-link\" href=\"/\">Config System</a>\n" +
                "                <a class=\"nav-link\" href=\"/programm-editor.html\">Programm-Editor</a>\n" +
                "                <a class=\"nav-link active\" href=\"/benutzerprogramme.html\">Benutzerprogramme</a>\n" +
                "            </div>\n" +
                "        </div>\n" +
                "    </nav>\n" +
                "    <div class=\"container mt-4\">\n" +
                "        <h1>Benutzerprogramme</h1>\n" +
                "        <p class=\"text-muted\">Datum (Kalender), Uhrzeit, Melodie und optional Programmtag (für dieses Datum gültig). Leer = Kalender verwenden.</p>\n" +
                "        <div id=\"statusMessage\" class=\"alert\" style=\"display:none;\"></div>\n" +
                "        <div class=\"table-responsive benutzer-table-scroll\">\n" +
                "            <table class=\"table benutzer-table\">\n" +
                "                <thead><tr><th>Nr.</th><th>Datum</th><th>Uhrzeit</th><th>Melodie</th><th>Programmtag</th><th>Aktion</th></tr></thead>\n" +
                "                <tbody id=\"benutzerBody\"></tbody>\n" +
                "            </table>\n" +
                "        </div>\n" +
                "    </div>\n" +
                "    <div class=\"benutzer-fixed-bottom\">\n" +
                "        <div class=\"container\">\n" +
                "            <a href=\"/app-seite1.html\" class=\"btn btn-secondary me-2\" style=\"padding:12px 24px;font-size:1.1em;\">← Zurück zur App Seite 1</a><button type=\"button\" class=\"btn btn-success\" onclick=\"addNeuesProgramm()\" style=\"min-width:280px;padding:12px 24px;font-size:1.1em;\">Programm hinzufügen</button>\n" +
                "        </div>\n" +
                "    </div>\n" +
                "    <div class=\"modal fade\" id=\"modalNeuesProgramm\" tabindex=\"-1\">\n" +
                "        <div class=\"modal-dialog\">\n" +
                "            <div class=\"modal-content\">\n" +
                "                <div class=\"modal-header\"><h5 class=\"modal-title\" id=\"modalNeuesProgrammTitle\">Neues Benutzerprogramm</h5><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button></div>\n" +
                "                <div class=\"modal-body\">\n" +
                "                    <div class=\"mb-3\"><label class=\"form-label\">Datum</label><input type=\"date\" class=\"form-control\" id=\"newDatum\"></div>\n" +
                "                    <div class=\"mb-3\" id=\"newZeitWrap\"><label class=\"form-label\">Uhrzeit</label><label class=\"me-2\"><input type=\"checkbox\" id=\"newGanzerTag\"> Ganzer Tag</label><input type=\"time\" class=\"form-control d-inline-block\" id=\"newZeit\" style=\"min-width:100px\"></div>\n" +
                "                    <div class=\"mb-3\"><label class=\"form-label\">Melodie</label><select class=\"form-select\" id=\"newMelodie\"></select></div>\n" +
                "                    <div class=\"mb-3\"><label class=\"form-label\">Programmtag</label><select class=\"form-select\" id=\"newTagtyp\"></select></div>\n" +
                "                    <div id=\"newModalError\" class=\"alert alert-danger\" style=\"display:none;\"></div>\n" +
                "                </div>\n" +
                "                <div class=\"modal-footer\"><button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Abbrechen</button><button type=\"button\" class=\"btn btn-primary\" id=\"newModalSave\">Speichern</button></div>\n" +
                "            </div>\n" +
                "        </div>\n" +
                "    </div>\n" +
                "    <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/js/bootstrap.bundle.min.js\"></script>\n" +
                "    <script>\n" +
                "        let melodien = [];\n" +
                "        let tagtypen = [];\n" +
                "        let benutzer = [];\n" +
                "        let copyBuffer = null;\n" +
                "        let newSlotIndex = -1;\n" +
                "        const dirtySlots = new Set();\n" +
                "        let pendingNavigateHref = null;\n" +
                "        function markDirty(index) { dirtySlots.add(index); const btn = document.getElementById('save-btn-' + index); if (btn) { btn.classList.remove('btn-success'); btn.classList.add('btn-danger'); } }\n" +
                "        function hasUnsavedChanges() { return dirtySlots.size > 0; }\n" +
                "        async function saveAllDirty() { const list = Array.from(dirtySlots); for (let i = 0; i < list.length; i++) await saveBenutzer(list[i]); }\n" +
                "        window.addEventListener('beforeunload', function(e) { if (dirtySlots.size > 0) { e.preventDefault(); e.returnValue = 'Ungespeicherte Änderungen'; return e.returnValue; } });\n" +
                "        document.addEventListener('click', function(e) {\n" +
                "            var a = e.target.closest('a[href^=\"/\"]'); if (!a || a.getAttribute('href') === '#' || pendingNavigateHref) return;\n" +
                "            if (dirtySlots.size === 0) return;\n" +
                "            e.preventDefault();\n" +
                "            var href = a.getAttribute('href');\n" +
                "            if (confirm('Sie haben ungespeicherte Änderungen in den Benutzerprogrammen. Möchten Sie vor dem Verlassen speichern?')) {\n" +
                "                pendingNavigateHref = href;\n" +
                "                saveAllDirty().then(function() { window.location.href = pendingNavigateHref; pendingNavigateHref = null; }).catch(function(err) { showStatus('Fehler beim Speichern: ' + err.message, 'danger'); pendingNavigateHref = null; });\n" +
                "            } else if (confirm('Ohne zu speichern verlassen?')) { window.location.href = href; }\n" +
                "        });\n" +
                "        async function loadMelodien() { try { const r = await fetch('/api/melodien'); const d = await r.json(); var raw = (r.ok && d && Array.isArray(d.melodien)) ? d.melodien : []; melodien = raw.filter(function(m){ return m && (m.inDropdown !== false && m.inDropdown !== 'false'); }); } catch (e) { melodien = []; } }\n" +
                "        async function loadTagtypen() { try { const r = await fetch('/api/tagtypen'); const d = await r.json(); var raw = (Array.isArray(d) ? d : (d && d.tagtypen) ? d.tagtypen : []); tagtypen = raw.filter(function(t){ return (t && t.name != null) && (t.inDropdown !== false && t.inDropdown !== 'false'); }).map(function(t){ return String(t.name).trim(); }).filter(function(n){ return n !== ''; }); if (tagtypen.indexOf('Normalprogramm') < 0) tagtypen.unshift('Normalprogramm'); } catch (e) { tagtypen = ['Normalprogramm']; } }\n" +
                "        async function loadBenutzer() { const r = await fetch('/api/benutzerprogramme'); benutzer = await r.json(); }\n" +
                "        function escapeHtml(str) { if (str == null) return ''; return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;'); }\n" +
                "        function showStatus(msg, type) { const el = document.getElementById('statusMessage'); el.textContent = msg; el.className = 'alert alert-' + type; el.style.display = 'block'; setTimeout(() => { el.style.display = 'none'; }, 4000); }\n" +
                "        function datumToYyyyMmDd(tag, monat, jahr) {\n" +
                "            const d = parseInt(tag) || 1, m = parseInt(monat) || 1, y = parseInt(jahr) || new Date().getFullYear();\n" +
                "            const mm = Math.max(1, Math.min(12, m)).toString().padStart(2, '0');\n" +
                "            const dd = d.toString().padStart(2, '0');\n" +
                "            return y + '-' + mm + '-' + dd;\n" +
                "        }\n" +
                "        function stundeMinuteToTimeValue(stunde, minute) {\n" +
                "            const h = Math.max(0, Math.min(23, parseInt(stunde) || 12));\n" +
                "            const m = Math.max(0, Math.min(59, parseInt(minute) || 0));\n" +
                "            return ('' + h).padStart(2, '0') + ':' + ('' + m).padStart(2, '0');\n" +
                "        }\n" +
                "        function isSlotBelegt(b) {\n" +
                "            if (!b) return false;\n" +
                "            const tagtyp = (b.tagtypName != null) ? String(b.tagtypName).trim() : '';\n" +
                "            if (tagtyp !== '') return true;\n" +
                "            const name = (b.melodieName != null) ? String(b.melodieName).trim() : '';\n" +
                "            if (name !== '') return true;\n" +
                "            const t = parseInt(b.tag) || 1, m = parseInt(b.monat) || 1;\n" +
                "            if (t !== 1 || m !== 1) return true;\n" +
                "            const h = parseInt(b.stunde, 10), min = parseInt(b.minute, 10);\n" +
                "            if (!isNaN(h) && !isNaN(min) && (h < 0 || min < 0)) return true;\n" +
                "            if (h !== 12 || min !== 0) return true;\n" +
                "            return b.on === true;\n" +
                "        }\n" +
                "        async function saveBenutzer(index, data) {\n" +
                "            const payload = data || {\n" +
                "                on: true,\n" +
                "                tag: 1, monat: 1, jahr: new Date().getFullYear(),\n" +
                "                stunde: 12, minute: 0, melodieName: '', tagtypName: ''\n" +
                "            };\n" +
                "            if (!data) {\n" +
                "                const datumEl = document.getElementById('datum-' + index);\n" +
                "                if (datumEl && datumEl.value) {\n" +
                "                    const parts = datumEl.value.split('-');\n" +
                "                    if (parts.length === 3) { payload.jahr = parseInt(parts[0]) || payload.jahr; payload.monat = parseInt(parts[1]) || 1; payload.tag = parseInt(parts[2]) || 1; }\n" +
                "                }\n" +
                "                const ganzerTagEl = document.getElementById('ganzerTag-' + index);\n" +
                "                if (ganzerTagEl && ganzerTagEl.checked) {\n" +
                "                    payload.stunde = -1; payload.minute = -1;\n" +
                "                } else {\n" +
                "                    const zeitEl = document.getElementById('zeit-' + index);\n" +
                "                    if (zeitEl && zeitEl.value) {\n" +
                "                        const t = zeitEl.value.split(':');\n" +
                "                        payload.stunde = parseInt(t[0]) || 12;\n" +
                "                        payload.minute = parseInt(t[1]) || 0;\n" +
                "                    } else { payload.stunde = 12; payload.minute = 0; }\n" +
                "                }\n" +
                "                const melodieSel = document.getElementById('melodie-' + index);\n" +
                "                payload.melodieName = melodieSel ? melodieSel.value : '';\n" +
                "                const tagtypSel = document.getElementById('tagtyp-' + index);\n" +
                "                payload.tagtypName = tagtypSel ? tagtypSel.value : '';\n" +
                "                payload.on = true;\n" +
                "            }\n" +
                "            const r = await fetch('/api/benutzerprogramme/' + index, {\n" +
                "                method: 'PUT', headers: { 'Content-Type': 'application/json' },\n" +
                "                body: JSON.stringify({ on: payload.on, tag: payload.tag, monat: payload.monat, jahr: payload.jahr, stunde: payload.stunde, minute: payload.minute, melodieName: payload.melodieName, tagtypName: payload.tagtypName })\n" +
                "            });\n" +
                "            if (!r.ok) {\n" +
                "                const e = await r.json().catch(function(){ return {}; });\n" +
                "                const msg = e.error || 'Fehler beim Speichern';\n" +
                "                showStatus(msg, 'danger');\n" +
                "                const row = document.getElementById('benutzer-row-' + index);\n" +
                "                if (row) row.scrollIntoView({ behavior: 'smooth', block: 'center' });\n" +
                "                return;\n" +
                "            }\n" +
                "            if (!data) { dirtySlots.delete(index); showStatus('Benutzerprogramm ' + (index + 1) + ' gespeichert.', 'success'); await loadBenutzer(); render(); }\n" +
                "            return payload;\n" +
                "        }\n" +
                "        async function deleteBenutzer(index) {\n" +
                "            const r = await fetch('/api/benutzerprogramme/' + index, {\n" +
                "                method: 'PUT', headers: { 'Content-Type': 'application/json' },\n" +
                "                body: JSON.stringify({ on: false, tag: 1, monat: 1, jahr: new Date().getFullYear(), stunde: 12, minute: 0, melodieName: '', tagtypName: '' })\n" +
                "            });\n" +
                "            if (!r.ok) { const e = await r.json(); throw new Error(e.error || 'Fehler'); }\n" +
                "            showStatus('Benutzerprogramm ' + (index + 1) + ' gelöscht.', 'success');\n" +
                "            await loadBenutzer(); render();\n" +
                "        }\n" +
                "        function fillModalNeuesProgramm() {\n" +
                "            var tit = document.getElementById('modalNeuesProgrammTitle'); if (tit) tit.textContent = 'Neues Benutzerprogramm';\n" +
                "            const now = new Date();\n" +
                "            const y = now.getFullYear(), m = (now.getMonth() + 1).toString().padStart(2, '0'), d = now.getDate().toString().padStart(2, '0');\n" +
                "            document.getElementById('newDatum').value = y + '-' + m + '-' + d;\n" +
                "            document.getElementById('newGanzerTag').checked = false;\n" +
                "            document.getElementById('newZeit').value = '12:00';\n" +
                "            document.getElementById('newModalError').style.display = 'none';\n" +
                "            let melOpts = '<option value=\"\">-- Keine --</option>';\n" +
                "            melodien.forEach(function(m) { const n = (m.name != null) ? String(m.name).trim() : ''; melOpts += '<option value=\"' + escapeHtml(n) + '\">' + escapeHtml(n || '(ohne Name)') + '</option>'; });\n" +
                "            document.getElementById('newMelodie').innerHTML = melOpts;\n" +
                "            document.getElementById('newMelodie').value = '';\n" +
                "            let tagOpts = '<option value=\"\">Keine Änderung</option>';\n" +
                "            tagtypen.forEach(function(t) { tagOpts += '<option value=\"' + escapeHtml(t) + '\">' + escapeHtml(t) + '</option>'; });\n" +
                "            document.getElementById('newTagtyp').innerHTML = tagOpts;\n" +
                "            document.getElementById('newTagtyp').value = '';\n" +
                "        }\n" +
                "        function fillModalEditBenutzer(index) {\n" +
                "            var tit = document.getElementById('modalNeuesProgrammTitle'); if (tit) tit.textContent = 'Benutzerprogramm bearbeiten';\n" +
                "            var b = benutzer[index]; if (!b) return;\n" +
                "            document.getElementById('newDatum').value = datumToYyyyMmDd(b.tag, b.monat, b.jahr);\n" +
                "            var ganzerTag = (parseInt(b.stunde, 10) === -1 || parseInt(b.minute, 10) === -1);\n" +
                "            document.getElementById('newGanzerTag').checked = ganzerTag;\n" +
                "            document.getElementById('newZeit').value = ganzerTag ? '12:00' : stundeMinuteToTimeValue(b.stunde, b.minute);\n" +
                "            document.getElementById('newZeit').style.display = ganzerTag ? 'none' : '';\n" +
                "            document.getElementById('newModalError').style.display = 'none';\n" +
                "            var melOpts = '<option value=\"\">-- Keine --</option>';\n" +
                "            melodien.forEach(function(m) { var n = (m.name != null) ? String(m.name).trim() : ''; var sel = (n === (b.melodieName || '').trim()) ? ' selected' : ''; melOpts += '<option value=\"' + escapeHtml(n) + '\"' + sel + '>' + escapeHtml(n || '(ohne Name)') + '</option>'; });\n" +
                "            if (melodien.length === 0 && (b.melodieName || '')) melOpts += '<option value=\"' + escapeHtml(b.melodieName) + '\" selected>' + escapeHtml(b.melodieName) + '</option>';\n" +
                "            document.getElementById('newMelodie').innerHTML = melOpts;\n" +
                "            var tagOpts = '<option value=\"\">Keine Änderung</option>';\n" +
                "            tagtypen.forEach(function(t) { var sel = ((b.tagtypName || '') === t) ? ' selected' : ''; tagOpts += '<option value=\"' + escapeHtml(t) + '\"' + sel + '>' + escapeHtml(t) + '</option>'; });\n" +
                "            document.getElementById('newTagtyp').innerHTML = tagOpts;\n" +
                "        }\n" +
                "        function openEditBenutzer(index) {\n" +
                "            newSlotIndex = index;\n" +
                "            fillModalEditBenutzer(index);\n" +
                "            var modal = new bootstrap.Modal(document.getElementById('modalNeuesProgramm'));\n" +
                "            modal.show();\n" +
                "        }\n" +
                "        async function addNeuesProgramm() {\n" +
                "            await loadBenutzer();\n" +
                "            newSlotIndex = -1;\n" +
                "            for (let i = 0; i < 20; i++) {\n" +
                "                if (!benutzer[i] || !isSlotBelegt(benutzer[i])) { newSlotIndex = i; break; }\n" +
                "            }\n" +
                "            if (newSlotIndex < 0) { showStatus('Maximal 20 Benutzerprogramme möglich.', 'warning'); return; }\n" +
                "            fillModalNeuesProgramm();\n" +
                "            var modal = new bootstrap.Modal(document.getElementById('modalNeuesProgramm'));\n" +
                "            modal.show();\n" +
                "        }\n" +
                "        async function saveFromModalNeuesProgramm() {\n" +
                "            var datumEl = document.getElementById('newDatum');\n" +
                "            var parts = (datumEl.value || '').split('-');\n" +
                "            var jahr = parts.length === 3 ? parseInt(parts[0], 10) : new Date().getFullYear();\n" +
                "            var monat = parts.length === 3 ? parseInt(parts[1], 10) : 1;\n" +
                "            var tag = parts.length === 3 ? parseInt(parts[2], 10) : 1;\n" +
                "            var ganzerTag = document.getElementById('newGanzerTag').checked;\n" +
                "            var zeitEl = document.getElementById('newZeit');\n" +
                "            var stunde = ganzerTag ? -1 : (parseInt((zeitEl.value || '12').split(':')[0], 10) || 12);\n" +
                "            var minute = ganzerTag ? -1 : (parseInt((zeitEl.value || '12:00').split(':')[1], 10) || 0);\n" +
                "            var melodieName = (document.getElementById('newMelodie').value || '').trim();\n" +
                "            var tagtypName = (document.getElementById('newTagtyp').value || '').trim();\n" +
                "            if (!melodieName && !tagtypName) {\n" +
                "                var errEl = document.getElementById('newModalError');\n" +
                "                errEl.textContent = 'Bitte Melodie oder Programmtag auswählen.';\n" +
                "                errEl.style.display = 'block';\n" +
                "                return;\n" +
                "            }\n" +
                "            var payload = { on: true, tag: tag, monat: monat, jahr: jahr, stunde: stunde, minute: minute, melodieName: melodieName, tagtypName: tagtypName };\n" +
                "            var r = await fetch('/api/benutzerprogramme/' + newSlotIndex, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });\n" +
                "            if (!r.ok) { var e = await r.json().catch(function(){ return {}; }); var errEl = document.getElementById('newModalError'); errEl.textContent = e.error || 'Fehler beim Speichern'; errEl.style.display = 'block'; return; }\n" +
                "            if (document.activeElement && document.activeElement.blur) document.activeElement.blur();\n" +
                "            bootstrap.Modal.getInstance(document.getElementById('modalNeuesProgramm')).hide();\n" +
                "            await loadBenutzer(); render();\n" +
                "            showStatus('Programm gespeichert. Liste nach Datum sortiert.', 'success');\n" +
                "        }\n" +
                "        function sortByDatumZeit(list) {\n" +
                "            return list.slice().sort(function(a, b) {\n" +
                "                var j = (parseInt(a.jahr,10)||0) - (parseInt(b.jahr,10)||0); if (j !== 0) return j;\n" +
                "                var m = (parseInt(a.monat,10)||0) - (parseInt(b.monat,10)||0); if (m !== 0) return m;\n" +
                "                var t = (parseInt(a.tag,10)||0) - (parseInt(b.tag,10)||0); if (t !== 0) return t;\n" +
                "                var ah = parseInt(a.stunde,10), am = parseInt(a.minute,10); if (ah < 0) ah = 24; if (am < 0) am = 60;\n" +
                "                var bh = parseInt(b.stunde,10), bm = parseInt(b.minute,10); if (bh < 0) bh = 24; if (bm < 0) bm = 60;\n" +
                "                var h = ah - bh; if (h !== 0) return h; return am - bm;\n" +
                "            });\n" +
                "        }\n" +
                "        function render() {\n" +
                "            const tbody = document.getElementById('benutzerBody');\n" +
                "            const belegt = sortByDatumZeit(benutzer.filter(b => isSlotBelegt(b)));\n" +
                "            if (belegt.length === 0) {\n" +
                "                tbody.innerHTML = '<tr><td colspan=\"6\" class=\"text-center text-muted py-5\">Noch keine Benutzerprogramme. Klicken Sie unten auf <strong>Programm hinzufügen</strong> – im Dialog können Sie <strong>Datum (Kalender)</strong> und <strong>Uhrzeit (Timepicker)</strong> einstellen.</td></tr>';\n" +
                "                return;\n" +
                "            }\n" +
                "            tbody.innerHTML = belegt.map(function(b, pos) { return (function(b, listPos) {\n" +
                "                const datumVal = datumToYyyyMmDd(b.tag, b.monat, b.jahr);\n" +
                "                const datumDisplay = datumVal ? (datumVal.split('-')[2] + '.' + datumVal.split('-')[1] + '.' + datumVal.split('-')[0]) : '–';\n" +
                "                const ganzerTag = (parseInt(b.stunde, 10) === -1 || parseInt(b.minute, 10) === -1);\n" +
                "                const zeitDisplay = ganzerTag ? 'Ganzer Tag' : (stundeMinuteToTimeValue(b.stunde, b.minute) || '–');\n" +
                "                const melodieDisplay = (b.melodieName != null && String(b.melodieName).trim() !== '') ? escapeHtml(String(b.melodieName).trim()) : '– Keine –';\n" +
                "                const tagtypDisplay = (b.tagtypName != null && String(b.tagtypName).trim() !== '') ? escapeHtml(String(b.tagtypName).trim()) : 'Keine Änderung';\n" +
                "                const btns = '<button class=\"btn btn-danger btn-sm me-1\" onclick=\"deleteBenutzer(' + b.index + ')\" title=\"Slot leeren\">Löschen</button>' +\n" +
                "                    '<button class=\"btn btn-primary btn-sm me-1\" onclick=\"openEditBenutzer(' + b.index + ')\" title=\"Bearbeiten\">Bearbeiten</button>';\n" +
                "                return '<tr id=\"benutzer-row-' + b.index + '\" style=\"background-color:#E8F5E9\"><td>' + (listPos + 1) + '</td><td class=\"benutzer-cell-readonly\">' + datumDisplay + '</td><td class=\"benutzer-cell-readonly\">' + zeitDisplay + '</td><td class=\"benutzer-cell-readonly\">' + melodieDisplay + '</td><td class=\"benutzer-cell-readonly\">' + tagtypDisplay + '</td><td><div class=\"btn-group btn-group-sm\">' + btns + '</div></td></tr>';\n" +
                "            })(b, pos); }).join('');\n" +
                "        }\n" +
                "        document.getElementById('newModalSave').onclick = saveFromModalNeuesProgramm;\n" +
                "        document.getElementById('newGanzerTag').addEventListener('change', function() { var z = document.getElementById('newZeit'); if (z) z.style.display = this.checked ? 'none' : ''; });\n" +
                "        (async function init() { try { await Promise.all([loadMelodien(), loadTagtypen()]); await loadBenutzer(); dirtySlots.clear(); render(); if (melodien.length === 0) showStatus('Hinweis: Keine Melodien in der Datenbank. Bitte zuerst Melodien importieren (Melodien-Editor).', 'info'); } catch (e) { showStatus('Fehler: ' + e.message, 'danger'); } })();\n" +
                "    </script>\n" +
                "</body>\n" +
                "</html>";
    }
    
    /**
     * Berechnet das Osterdatum für ein gegebenes Jahr (Gauß'sche Osterformel).
     * @param jahr Das Jahr (z.B. 2024)
     * @return Calendar-Objekt mit dem Osterdatum
     */
    private java.util.Calendar berechneOsterdatum(int jahr) {
        // Gauß'sche Osterformel
        int a = jahr % 19;
        int b = jahr % 4;
        int c = jahr % 7;
        int k = jahr / 100;
        int p = (8 * k + 13) / 25;
        int q = k / 4;
        int m = (15 + k - p - q) % 30;
        int n = (4 + k - q) % 7;
        int d = (19 * a + m) % 30;
        int e = (2 * b + 4 * c + 6 * d + n) % 7;
        
        int tag = 22 + d + e;
        int monat = 3; // März
        
        // Sonderfälle
        if (tag > 31) {
            tag = tag - 31;
            monat = 4; // April
        }
        
        // Ausnahmeregel: Wenn d=29 und e=6, dann ist Ostern am 19. April
        if (d == 29 && e == 6) {
            tag = 19;
            monat = 4;
        }
        
        // Ausnahmeregel: Wenn d=28 und e=6 und (11*m+11) mod 30 < 19, dann ist Ostern am 18. April
        if (d == 28 && e == 6 && ((11 * m + 11) % 30) < 19) {
            tag = 18;
            monat = 4;
        }
        
        java.util.Calendar osterdatum = java.util.Calendar.getInstance();
        osterdatum.set(jahr, monat - 1, tag); // Monat ist 0-basiert in Calendar
        return osterdatum;
    }
    
    /**
     * Generiert HTML für die Osterfeiertage-Seite mit Osterdatum-Anzeige.
     */
    private String getOsterfeiertageHTML() {
        // Berechne Osterdatum für aktuelles Jahr
        java.util.Calendar calendar = java.util.Calendar.getInstance();
        int aktuellesJahr = calendar.get(java.util.Calendar.YEAR);
        java.util.Calendar osterdatum = berechneOsterdatum(aktuellesJahr);
        
        // Formatiere Datum
        java.text.SimpleDateFormat dateFormat = new java.text.SimpleDateFormat("dd.MM.yyyy", java.util.Locale.GERMAN);
        String osterdatumString = dateFormat.format(osterdatum.getTime());
        String wochentag = new java.text.SimpleDateFormat("EEEE", java.util.Locale.GERMAN).format(osterdatum.getTime());
        
        return "<!DOCTYPE html>\n" +
                "<html lang=\"de\">\n" +
                "<head>\n" +
                "    <meta charset=\"UTF-8\">\n" +
                "    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n" +
                "    <title>Osterfeiertage - Turmtechnik</title>\n" +
                "    <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n" +
                "    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n" +
                "    <style>\n" +
                "        :root { --tt-bg: #0a0a0a; --tt-surface: #141414; --tt-card: #1a1a1a; --tt-border: #2a2a2a; --tt-text: #e8e8e8; --tt-muted: #888; --tt-accent: #c495b0; }\n" +
                "        * { box-sizing: border-box; }\n" +
                "        body { font-family: 'Inter', -apple-system, sans-serif; background: var(--tt-bg); color: var(--tt-text); min-height: 100vh; margin: 0; }\n" +
                "        .tt-header { background: var(--tt-surface); border-bottom: 1px solid var(--tt-border); padding: 1rem 0; }\n" +
                "        .tt-header h1 { font-size: 1.25rem; font-weight: 700; margin: 0; }\n" +
                "        .tt-nav a { color: var(--tt-muted); text-decoration: none; margin-right: 1rem; }\n" +
                "        .tt-nav a:hover { color: var(--tt-accent); }\n" +
                "        .tt-nav a.active { color: var(--tt-text); }\n" +
                "        .tt-card { background: var(--tt-card); border: 1px solid var(--tt-border); border-radius: 10px; padding: 1.25rem; margin-bottom: 1.25rem; }\n" +
                "        .tt-card .text-muted { color: var(--tt-muted) !important; }\n" +
                "        .form-control, .form-select { background: #111; border-color: var(--tt-border); color: var(--tt-text); }\n" +
                "        .form-control:focus, .form-select:focus { background: #151515; border-color: var(--tt-accent); color: var(--tt-text); }\n" +
                "        .table { color: var(--tt-text); font-size: 0.875rem; }\n" +
                "        .table thead th { background: var(--tt-surface) !important; border-color: var(--tt-border); color: var(--tt-accent); font-size: 0.8rem; }\n" +
                "        .table td, .table th { border-color: var(--tt-border); }\n" +
                "        .table tbody td { font-size: 0.85rem; }\n" +
                "        .table-striped tbody tr:nth-of-type(odd) { background: rgba(255,255,255,0.03); }\n" +
                "        .table-hover tbody tr:hover { background: rgba(196,149,176,0.15); }\n" +
                "        .alert { background: var(--tt-surface); border-color: var(--tt-border); color: var(--tt-text); }\n" +
                "        .alert-success { color: #86efac; }\n" +
                "        .alert-danger { color: #fca5a5; }\n" +
                "        .btn-primary { background: var(--tt-accent); border-color: var(--tt-accent); color: #0a0a0a; }\n" +
                "        .btn-primary:hover { background: #d4a5be; border-color: #d4a5be; color: #0a0a0a; }\n" +
                "        .btn-success { background: #22c55e; border-color: #22c55e; color: #fff; }\n" +
                "        .btn-outline-primary { border-color: var(--tt-accent); color: var(--tt-accent); }\n" +
                "        .btn-outline-primary:hover { background: var(--tt-accent); border-color: var(--tt-accent); color: #0a0a0a; }\n" +
                "        .btn-secondary { background: var(--tt-surface); border-color: var(--tt-border); color: var(--tt-text); }\n" +
                "        .tagtyp-badge { display: inline-block; width: 1.1em; height: 1.1em; border-radius: 4px; vertical-align: middle; margin-right: 6px; border: 1px solid var(--tt-border); }\n" +
                "        .tt-name-feiertag { color: var(--tt-accent) !important; font-weight: 500; font-size: 0.85rem; }\n" +
                "        .tt-name-vorfeiertag { color: #a8d0e6 !important; font-size: 0.85rem; }\n" +
                "        .tt-table-osterfeiertage tbody td { color: var(--tt-text) !important; }\n" +
                "        .tt-table-osterfeiertage tbody tr:nth-of-type(odd) { background: rgba(255,255,255,0.06); }\n" +
                "        .tt-table-osterfeiertage tbody tr:nth-of-type(even) { background: var(--tt-card); }\n" +
                "        .tt-table-osterfeiertage th:nth-child(1), .tt-table-osterfeiertage td:nth-child(1) { width: 18%; max-width: 160px; }\n" +
                "        .tt-table-osterfeiertage th:nth-child(2), .tt-table-osterfeiertage td:nth-child(2) { width: 10%; max-width: 80px; }\n" +
                "        .tt-table-osterfeiertage th:nth-child(3), .tt-table-osterfeiertage td:nth-child(3) { width: 12%; max-width: 100px; }\n" +
                "        .tt-table-osterfeiertage th:nth-child(4), .tt-table-osterfeiertage td:nth-child(4) { width: 32%; min-width: 220px; }\n" +
                "        .tt-table-osterfeiertage th:nth-child(5), .tt-table-osterfeiertage td:nth-child(5) { width: 18%; max-width: 120px; }\n" +
                "        .tt-table-osterfeiertage td:nth-child(4) select { max-width: 100%; min-width: 200px; }\n" +
                "    </style>\n" +
                "</head>\n" +
                "<body>\n" +
                "    <header class=\"tt-header\">\n" +
                "        <div class=\"container\">\n" +
                "            <h1>Turmtechnik</h1>\n" +
                "            <div class=\"tt-nav mt-1\"><a href=\"/\">Config System</a> <a href=\"/fixe-feiertage.html\">Fixe Feiertage</a></div>\n" +
                "        </div>\n" +
                "    </header>\n" +
                "    <div class=\"container py-4\">\n" +
                "        <h2 class=\"mb-2\" style=\"font-size:1.4rem;\">Osterfeiertage</h2>\n" +
                "        <p class=\"text-muted mb-4\">Variable Feiertage (Osterfeiertage) bearbeiten</p>\n" +
                "        <div class=\"tt-card\">\n" +
                "            <h5 class=\"mb-0\" style=\"color:var(--tt-accent);\">Osterdatum " + aktuellesJahr + ": " + osterdatumString + " (" + wochentag + ")</h5>\n" +
                "        </div>\n" +
                "        <div class=\"tt-card\">\n" +
                "            <p class=\"text-muted small mb-0\"><strong class=\"text-secondary\">Hinweis:</strong> Die Osterfeiertage werden basierend auf dem Osterdatum berechnet. Das Osterdatum wird nach der Gauß'schen Osterformel offline berechnet.</p>\n" +
                "        </div>\n" +
                "        <div class=\"tt-card\">\n" +
                "            <div class=\"d-flex justify-content-between align-items-center mb-3\" style=\"border-bottom:1px solid var(--tt-border);padding-bottom:0.75rem;\">\n" +
                "                <h5 class=\"mb-0\" style=\"color:var(--tt-accent);\">Osterfeiertage-Verwaltung</h5>\n" +
                "                <button class=\"btn btn-sm btn-primary\" onclick=\"migrateFromExcel()\">Aus Excel importieren</button>\n" +
                "            </div>\n" +
                "            <div id=\"migrationMessage\" class=\"alert mb-3\" style=\"display: none;\"></div>\n" +
                "            <div class=\"table-responsive\">\n" +
                "                <table class=\"table table-striped table-hover tt-table-osterfeiertage\">\n" +
                "                    <thead>\n" +
                "                        <tr>\n" +
                "                            <th>Feiertag</th>\n" +
                "                            <th>Tage +/-</th>\n" +
                "                            <th>Datum " + aktuellesJahr + "</th>\n" +
                "                            <th>Tagtyp</th>\n" +
                "                            <th>Aktionen</th>\n" +
                "                        </tr>\n" +
                "                    </thead>\n" +
                "                    <tbody id=\"feiertageBody\">\n" +
                "                        <tr><td colspan=\"5\" class=\"text-center text-muted\">Lade Osterfeiertage...</td></tr>\n" +
                "                    </tbody>\n" +
                "                </table>\n" +
                "            </div>\n" +
                "        </div>\n" +
                "    </div>\n" +
                "    \n" +
                "    <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/js/bootstrap.bundle.min.js\"></script>\n" +
                "    <script>\n" +
                "        let feiertage = [];\n" +
                "        let tagtypen = [];\n" +
                "        const TAGTYP_PALETTE = ['#e6194b','#3cb44b','#ffe119','#4363d8','#f58231','#911eb4','#42d4f4','#f032e6','#bfef45','#469990','#dcbeff','#9a6324','#800000','#aaffc3','#ffd8b1','#808000'];\n" +
                "        function tagtypColor(name) {\n" +
                "            if (!name || !name.trim()) return '#cccccc';\n" +
                "            let h = 0; for (let i = 0; i < name.length; i++) h = ((h << 5) - h) + name.charCodeAt(i);\n" +
                "            return TAGTYP_PALETTE[Math.abs(h) % TAGTYP_PALETTE.length];\n" +
                "        }\n" +
                "        \n" +
                "        async function loadTagtypen() {\n" +
                "            try {\n" +
                "                const response = await fetch('/api/tagtypen');\n" +
                "                if (!response.ok) throw new Error('Fehler beim Laden der Tagtypen');\n" +
                "                tagtypen = await response.json();\n" +
                "            } catch (error) {\n" +
                "                console.error('Fehler:', error);\n" +
                "            }\n" +
                "        }\n" +
                "        \n" +
                "        async function loadFeiertage() {\n" +
                "            try {\n" +
                "                const response = await fetch('/api/osterfeiertage');\n" +
                "                if (!response.ok) throw new Error('Fehler beim Laden der Osterfeiertage');\n" +
                "                const data = await response.json();\n" +
                "                feiertage = Array.isArray(data) ? data : [];\n" +
                "                renderFeiertage();\n" +
                "            } catch (error) {\n" +
                "                console.error('Fehler:', error);\n" +
                "                document.getElementById('feiertageBody').innerHTML = '<tr><td colspan=\"5\" class=\"text-center text-danger\">Fehler beim Laden der Daten</td></tr>';\n" +
                "            }\n" +
                "        }\n" +
                "        \n" +
                "        function renderFeiertage() {\n" +
                "            const tbody = document.getElementById('feiertageBody');\n" +
                "            if (!tbody) return;\n" +
                "            if (!Array.isArray(feiertage) || feiertage.length === 0) {\n" +
                "                tbody.innerHTML = '<tr><td colspan=\"5\" class=\"text-center\">Keine Osterfeiertage gefunden</td></tr>';\n" +
                "                return;\n" +
                "            }\n" +
                "            \n" +
                "            // Sortiere Feiertage nach Datum (aufsteigend)\n" +
                "            const sortedFeiertage = feiertage.slice().sort((a, b) => {\n" +
                "                // Für Osterfeiertage: Datum ist im Format dd.MM.yyyy\n" +
                "                // Konvertiere zu yyyy-MM-dd für Vergleich\n" +
                "                if (!a.datum || !b.datum) return 0;\n" +
                "                const partsA = a.datum.split('.');\n" +
                "                const partsB = b.datum.split('.');\n" +
                "                if (partsA.length === 3 && partsB.length === 3) {\n" +
                "                    // Format: dd.MM.yyyy -> yyyy-MM-dd\n" +
                "                    const dateA = partsA[2] + '-' + partsA[1].padStart(2, '0') + '-' + partsA[0].padStart(2, '0');\n" +
                "                    const dateB = partsB[2] + '-' + partsB[1].padStart(2, '0') + '-' + partsB[0].padStart(2, '0');\n" +
                "                    return dateA.localeCompare(dateB);\n" +
                "                }\n" +
                "                return a.datum.localeCompare(b.datum);\n" +
                "            });\n" +
                "            \n" +
                "            tbody.innerHTML = sortedFeiertage.map(f => {\n" +
                "                const tagtypOptions = tagtypen.map(t => \n" +
                "                    `<option value=\"${t.name}\" ${t.name === f.tagtypName ? 'selected' : ''}>${t.name}</option>`\n" +
                "                ).join('');\n" +
                "                const isVorfeiertag = (f.name && (f.name.indexOf('Tag vor') >= 0 || f.name.indexOf('vor ') === 0));\n" +
                "                const nameClass = isVorfeiertag ? 'tt-name-vorfeiertag' : 'tt-name-feiertag';\n" +
                "                const isWeihnacht = (f.name && (f.name.indexOf('Christkönig') >= 0 || f.name.indexOf('Advent') >= 0));\n" +
                "                const ttColor = tagtypColor(f.tagtypName);\n" +
                "                return `<tr>\n" +
                "                    <td class=\"${nameClass}\">${f.name}</td>\n" +
                "                    <td>${isWeihnacht ? 'Weihnacht' : (f.osterOffset > 0 ? '+' : '') + f.osterOffset}</td>\n" +
                "                    <td>${f.datum}</td>\n" +
                "                    <td>\n" +
                "                        <span class=\"tagtyp-badge\" style=\"background:${ttColor}\" title=\"${(f.tagtypName || '').replace(/\"/g, '&quot;')}\"></span>\n" +
                "                        <select class=\"form-select form-select-sm d-inline-block w-100\" id=\"tagtyp_${f.id}\" onchange=\"saveFeiertag(${f.id})\">\n" +
                "                            <option value=\"\">-- Kein Tagtyp --</option>\n" +
                "                            ${tagtypOptions}\n" +
                "                        </select>\n" +
                "                    </td>\n" +
                "                    <td>\n" +
                "                        <button class=\"btn btn-sm btn-primary\" onclick=\"saveFeiertag(${f.id})\">Speichern</button>\n" +
                "                    </td>\n" +
                "                </tr>`;\n" +
                "            }).join('');\n" +
                "        }\n" +
                "        \n" +
                "        async function saveFeiertag(id) {\n" +
                "            const feiertag = feiertage.find(f => f.id === id);\n" +
                "            if (!feiertag) return;\n" +
                "            \n" +
                "            const tagtypSelect = document.getElementById(`tagtyp_${id}`);\n" +
                "            feiertag.tagtypName = tagtypSelect.value || null;\n" +
                "            \n" +
                "            try {\n" +
                "                const response = await fetch('/api/osterfeiertage', {\n" +
                "                    method: 'PUT',\n" +
                "                    headers: { 'Content-Type': 'application/json' },\n" +
                "                    body: JSON.stringify(feiertag)\n" +
                "                });\n" +
                "                \n" +
                "                if (!response.ok) throw new Error('Fehler beim Speichern');\n" +
                "                \n" +
                "                alert('Osterfeiertag gespeichert');\n" +
                "                loadFeiertage();\n" +
                "            } catch (error) {\n" +
                "                console.error('Fehler:', error);\n" +
                "                alert('Fehler beim Speichern: ' + error.message);\n" +
                "            }\n" +
                "        }\n" +
                "        \n" +
                "        async function migrateFromExcel() {\n" +
                "            if (!confirm('Tagtypen aus System.xls Sheet 12 importieren?\\\\n\\\\nDies überschreibt vorhandene Tagtyp-Zuordnungen!')) {\n" +
                "                return;\n" +
                "            }\n" +
                "            \n" +
                "            try {\n" +
                "                const response = await fetch('/api/osterfeiertage/migrate', {\n" +
                "                    method: 'POST'\n" +
                "                });\n" +
                "                \n" +
                "                if (!response.ok) throw new Error('Fehler bei Migration');\n" +
                "                \n" +
                "                const result = await response.json();\n" +
                "                showMigrationMessage('Migration erfolgreich abgeschlossen', 'success');\n" +
                "                await loadFeiertage(); // Lade Daten neu\n" +
                "            } catch (error) {\n" +
                "                console.error('Fehler:', error);\n" +
                "                showMigrationMessage('Fehler bei Migration: ' + error.message, 'danger');\n" +
                "            }\n" +
                "        }\n" +
                "        \n" +
                "        function showMigrationMessage(message, type) {\n" +
                "            const msgDiv = document.getElementById('migrationMessage');\n" +
                "            msgDiv.className = 'alert alert-' + type;\n" +
                "            msgDiv.textContent = message;\n" +
                "            msgDiv.style.display = 'block';\n" +
                "            setTimeout(() => {\n" +
                "                msgDiv.style.display = 'none';\n" +
                "            }, 5000);\n" +
                "        }\n" +
                "        \n" +
                "        // Beim Laden der Seite\n" +
                "        document.addEventListener('DOMContentLoaded', async () => {\n" +
                "            await loadTagtypen();\n" +
                "            await loadFeiertage();\n" +
                "        });\n" +
                "    </script>\n" +
                "</body>\n" +
                "</html>";
    }
    
    /**
     * Berechnet ein Datum relativ zum Osterdatum oder Weihnachten.
     * @param osterdatum Das Osterdatum
     * @param feiertagName Name des Feiertags (für Sonderfälle wie Christkönig, Advent)
     * @param tageOffset Anzahl der Tage relativ zu Ostern (negativ = vor Ostern, positiv = nach Ostern)
     * @param jahr Das Jahr
     * @return Formatierter Datumsstring (dd.MM.yyyy)
     */
    private String berechneFeiertagDatum(java.util.Calendar osterdatum, String feiertagName, int tageOffset, int jahr) {
        java.util.Calendar feiertag;
        
        // Sonderfälle: Christkönig und Advent sind Weihnachts-bezogen, nicht Oster-bezogen
        if (feiertagName != null && (feiertagName.contains("Christkönig") || feiertagName.contains("Advent"))) {
            feiertag = berechneWeihnachtsbezogenerFeiertag(feiertagName, jahr);
        } else {
            // Normale Oster-bezogene Feiertage
            feiertag = (java.util.Calendar) osterdatum.clone();
            feiertag.add(java.util.Calendar.DAY_OF_MONTH, tageOffset);
        }
        
        java.text.SimpleDateFormat dateFormat = new java.text.SimpleDateFormat("dd.MM.yyyy", java.util.Locale.GERMAN);
        return dateFormat.format(feiertag.getTime());
    }
    
    /**
     * Berechnet weihnachts-bezogene Feiertage (Christkönig, Advent).
     * Excel-Formel für Christkönig Sonntag: =DATUM($B$3;12;25)-WOCHENTAG(DATUM($B$3;12;25);2)-28
     * WOCHENTAG(;2): Montag=1, Dienstag=2, ..., Sonntag=7
     * Das bedeutet: 25. Dezember - (Wochentag als Zahl 1-7) - 28 Tage
     */
    private java.util.Calendar berechneWeihnachtsbezogenerFeiertag(String feiertagName, int jahr) {
        java.util.Calendar weihnachten = java.util.Calendar.getInstance();
        weihnachten.set(jahr, java.util.Calendar.DECEMBER, 25); // 25. Dezember
        
        if (feiertagName.contains("Christkönig")) {
            // Christkönig Sonntag = Letzter Sonntag vor dem 1. Advent
            // Berechne zuerst den 1. Advent, dann gehe 7 Tage zurück zum letzten Sonntag davor
            
            // 1. Advent berechnen: 4. Sonntag vor Weihnachten = letzter Sonntag vor/nach dem 25.12 minus 3 Wochen
            int wochentagWeihnachten = weihnachten.get(java.util.Calendar.DAY_OF_WEEK);
            // Calendar: Sonntag=1, Montag=2, ..., Samstag=7 → Tage zurück zum vorherigen Sonntag
            int tageZurueckZumSonntag = (wochentagWeihnachten == 1) ? 7 : (wochentagWeihnachten - 1);
            
            java.util.Calendar ersterAdvent = (java.util.Calendar) weihnachten.clone();
            ersterAdvent.add(java.util.Calendar.DAY_OF_MONTH, -tageZurueckZumSonntag); // Zum Sonntag vor Weihnachten
            ersterAdvent.add(java.util.Calendar.DAY_OF_MONTH, -3 * 7); // 3 weitere Wochen = 1. Advent
            
            // Christkönig = Letzter Sonntag vor dem 1. Advent = 7 Tage vor dem 1. Advent
            java.util.Calendar christkoenig = (java.util.Calendar) ersterAdvent.clone();
            christkoenig.add(java.util.Calendar.DAY_OF_MONTH, -7);
            
            if (feiertagName.contains("Samstag")) {
                // Christkönig Samstag = Tag vor Christkönig Sonntag
                christkoenig.add(java.util.Calendar.DAY_OF_MONTH, -1);
            }
            
            return christkoenig;
            
        } else if (feiertagName.contains("Advent")) {
            // Advent = 4 Sonntage vor Weihnachten
            // 1. Advent = 4. Sonntag vor Weihnachten (ca. 4 Wochen vor Weihnachten)
            // 2. Advent = 3. Sonntag vor Weihnachten
            // 3. Advent = 2. Sonntag vor Weihnachten
            // 4. Advent = 1. Sonntag vor Weihnachten
            
            int adventNummer = 1;
            if (feiertagName.contains("1.")) adventNummer = 1;
            else if (feiertagName.contains("2.")) adventNummer = 2;
            else if (feiertagName.contains("3.")) adventNummer = 3;
            else if (feiertagName.contains("4.")) adventNummer = 4;
            
            // Finde den Sonntag vor Weihnachten (bzw. Weihnachten wenn es ein Sonntag ist)
            int wochentagWeihnachten = weihnachten.get(java.util.Calendar.DAY_OF_WEEK);
            // Calendar: Sonntag=1, Montag=2, ..., Samstag=7 → Tage zurück zum vorherigen Sonntag
            int tageZurueckZumSonntag = (wochentagWeihnachten == 1) ? 7 : (wochentagWeihnachten - 1);
            
            java.util.Calendar advent = (java.util.Calendar) weihnachten.clone();
            advent.add(java.util.Calendar.DAY_OF_MONTH, -tageZurueckZumSonntag); // Zum Sonntag vor Weihnachten
            advent.add(java.util.Calendar.DAY_OF_MONTH, -(4 - adventNummer) * 7); // Zurück zum entsprechenden Advent (4-adventNummer Wochen)
            
            return advent;
        }
        
        // Fallback
        return weihnachten;
    }
    
    /**
     * Gibt alle Osterfeiertage zurück.
     */
    private SimpleHttpServer.HttpResponse handleGetOsterfeiertage() {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.Osterfeiertag> feiertage = dbHelper.getAllOsterfeiertage();
            
            // Berechne Osterdatum für aktuelles Jahr
            java.util.Calendar calendar = java.util.Calendar.getInstance();
            int aktuellesJahr = calendar.get(java.util.Calendar.YEAR);
            java.util.Calendar osterdatum = berechneOsterdatum(aktuellesJahr);
            
            // Erstelle Liste mit berechneten Daten
            java.util.List<java.util.Map<String, Object>> feiertageMitDatum = new java.util.ArrayList<>();
            for (PlatinenDatabaseHelper.Osterfeiertag feiertag : feiertage) {
                java.util.Map<String, Object> feiertagMap = new java.util.HashMap<>();
                feiertagMap.put("id", feiertag.id);
                feiertagMap.put("name", feiertag.name);
                feiertagMap.put("osterOffset", feiertag.osterOffset);
                feiertagMap.put("tagtypName", feiertag.tagtypName);
                feiertagMap.put("datum", berechneFeiertagDatum(osterdatum, feiertag.name, feiertag.osterOffset, aktuellesJahr));
                feiertageMitDatum.add(feiertagMap);
            }
            
            String json = gson.toJson(feiertageMitDatum);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen der Osterfeiertage", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
