    /**
     * Lädt Sonderfeiertage (verschobene Feiertage) aus der Datenbank.
     * Ohne ?alle=1 nur aktuelles Jahr; mit ?alle=1 alle Jahre (für Fixe-Feiertage-Seite).
     */
    private SimpleHttpServer.HttpResponse handleGetSonderfeiertage(String uri) {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.Sonderfeiertag> alleSonderfeiertage = dbHelper.getAllSonderfeiertage();
            boolean alleJahre = uri != null && uri.contains("alle=1");
            List<PlatinenDatabaseHelper.Sonderfeiertag> result;
            if (alleJahre) {
                result = alleSonderfeiertage;
            } else {
                java.util.Calendar cal = java.util.Calendar.getInstance();
                int aktuellesJahr = cal.get(java.util.Calendar.YEAR);
                result = new java.util.ArrayList<>();
                for (PlatinenDatabaseHelper.Sonderfeiertag s : alleSonderfeiertage) {
                    if (s.jahr == aktuellesJahr) result.add(s);
                }
            }
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen der Sonderfeiertage", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Berechnet und speichert Sonderfeiertage für einen neuen Feiertag (mit Name und Original-Datum).
     */
    private SimpleHttpServer.HttpResponse handleBerechneSonderfeiertage(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Request-Body erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            java.util.Map<String, Object> data = gson.fromJson(body, java.util.Map.class);
            String name = (String) data.get("name");
            String originalDatum = (String) data.get("originalDatum");
            String tagtypName = data.containsKey("tagtypName") && data.get("tagtypName") != null ? (String) data.get("tagtypName") : null;
            // Verschiebung wird automatisch aus sonntagImMonat berechnet
            int sonntagImMonat = data.containsKey("sonntagImMonat") && data.get("sonntagImMonat") != null ? 
                ((Double) data.get("sonntagImMonat")).intValue() : 0;
            // Verschiebung ist aktiviert wenn sonntagImMonat != 0 (0 = keine, -1 = näher zum Sonntag, 1-4 = n-ter Sonntag)
            boolean verschiebenAufSonntag = sonntagImMonat != 0;
            
            // Jahr: Wenn nicht angegeben, verwende aktuelles Jahr (nur zum Testen)
            java.util.Calendar cal = java.util.Calendar.getInstance();
            int aktuellesJahr = cal.get(java.util.Calendar.YEAR);
            int jahr = data.containsKey("jahr") && data.get("jahr") != null ? 
                ((Double) data.get("jahr")).intValue() : aktuellesJahr;
            int startJahr = jahr;
            int endJahr = jahr; // Nur ein Jahr zum Testen
            
            if (name == null || name.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Name erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            if (originalDatum == null || originalDatum.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Original-Datum erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            
            // Erstelle zuerst einen festen Feiertag (wenn noch nicht vorhanden)
            List<PlatinenDatabaseHelper.FesterFeiertag> alleFeiertage = dbHelper.getAllFesteFeiertage();
            PlatinenDatabaseHelper.FesterFeiertag feiertag = null;
            
            // Prüfe ob bereits vorhanden
            for (PlatinenDatabaseHelper.FesterFeiertag f : alleFeiertage) {
                if (f.datum.equals(originalDatum) && f.name.equals(name)) {
                    feiertag = f;
                    break;
                }
            }
            
            // Erstelle neuen Feiertag falls nicht vorhanden
            if (feiertag == null) {
                feiertag = new PlatinenDatabaseHelper.FesterFeiertag();
                feiertag.id = 0;
                feiertag.name = name;
                feiertag.datum = originalDatum;
                feiertag.tagtypName = tagtypName;
                feiertag.sonntagImMonat = sonntagImMonat;
                feiertag.verschiebenAufSonntag = verschiebenAufSonntag;
                feiertag = dbHelper.saveFesterFeiertag(feiertag);
                if (feiertag == null) {
                    String errorJson = "{\"error\":\"Feiertag mit diesem Namen und Datum existiert bereits.\"}";
                    return new SimpleHttpServer.HttpResponse(409, "application/json", errorJson);
                }
            } else {
                // Aktualisiere falls vorhanden
                feiertag.sonntagImMonat = sonntagImMonat;
                feiertag.verschiebenAufSonntag = verschiebenAufSonntag;
                if (tagtypName != null) {
                    feiertag.tagtypName = tagtypName;
                }
                feiertag = dbHelper.saveFesterFeiertag(feiertag);
                if (feiertag == null) {
                    String errorJson = "{\"error\":\"Feiertag konnte nicht aktualisiert werden.\"}";
                    return new SimpleHttpServer.HttpResponse(409, "application/json", errorJson);
                }
            }
            
            // Berechne und speichere Sonderfeiertage nur wenn Verschiebung aktiviert ist
            if (verschiebenAufSonntag) {
                dbHelper.berechneUndSpeichereSonderfeiertage(
                    feiertag.id,
                    originalDatum,
                    tagtypName,
                    startJahr,
                    endJahr,
                    sonntagImMonat
                );
            } else {
                // Wenn keine Verschiebung: Lösche alle vorhandenen Sonderfeiertage für diesen Feiertag
                dbHelper.deleteSonderfeiertageByFeiertagId(feiertag.id);
            }
            
            // Zähle erstellte Einträge (nur für das Test-Jahr)
            List<PlatinenDatabaseHelper.Sonderfeiertag> sonderfeiertage = dbHelper.getAllSonderfeiertage();
            int anzahl = 0;
            for (PlatinenDatabaseHelper.Sonderfeiertag s : sonderfeiertage) {
                if (s.feiertagId == feiertag.id && s.jahr == jahr) {
                    anzahl++;
                }
            }
            
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("anzahl", anzahl);
            result.put("jahr", jahr);
            result.put("feiertagId", feiertag.id);
            result.put("message", "Sonderfeiertag für Jahr " + jahr + " erstellt (nur zum Testen - App berechnet automatisch bei Bedarf)");
            
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Berechnen der Sonderfeiertage", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
