    /**
     * Aktualisiert eine MIDI-Datei-Konfiguration.
     */
    private SimpleHttpServer.HttpResponse handlePutMidiConfig(SimpleHttpServer.HttpRequest request) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Request-Body erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper.MidiConfig config = gson.fromJson(body, PlatinenDatabaseHelper.MidiConfig.class);
            
            // Validierung
            if (config.dateiname == null || config.dateiname.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Dateiname erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            if (config.abspielgeschwindigkeit <= 0 || config.abspielgeschwindigkeit > 10.0) {
                String errorJson = "{\"error\":\"Abspielgeschwindigkeit muss zwischen 0.1 und 10.0 sein\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            dbHelper.saveMidiConfig(config);
            
            String json = gson.toJson(config);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Speichern der MIDI-Konfiguration", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Empfängt eine MIDI-Datei-Upload und speichert sie.
     */
    private SimpleHttpServer.HttpResponse handlePostMidiConfigUpload(SimpleHttpServer.HttpRequest request) {
        try {
            // Prüfe Content-Type
            String contentType = request.headers.get("Content-Type");
            if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                String errorJson = "{\"error\":\"Content-Type muss multipart/form-data sein\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Parse multipart/form-data
            // Einfache Implementierung: Suche nach Datei-Daten im Body
            String body = request.body;
            if (body == null || body.isEmpty()) {
                String errorJson = "{\"error\":\"Keine Datei-Daten gefunden\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Einfache Multipart-Parsing (für einfache Fälle)
            // In einer produktiven Umgebung sollte man eine Bibliothek verwenden
            String boundary = null;
            if (contentType.contains("boundary=")) {
                boundary = "--" + contentType.substring(contentType.indexOf("boundary=") + 9);
            } else {
                String errorJson = "{\"error\":\"Boundary nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Extrahiere Dateiname und Dateiinhalt
            String fileName = null;
            byte[] fileData = null;
            
            String[] parts = body.split(boundary);
            for (String part : parts) {
                if (part.contains("Content-Disposition")) {
                    // Extrahiere Dateiname
                    if (part.contains("filename=\"")) {
                        int start = part.indexOf("filename=\"") + 10;
                        int end = part.indexOf("\"", start);
                        if (end > start) {
                            fileName = part.substring(start, end);
                        }
                    }
                    
                    // Finde Dateiinhalt (nach doppeltem CRLF)
                    int dataStart = part.indexOf("\r\n\r\n");
                    if (dataStart < 0) {
                        dataStart = part.indexOf("\n\n");
                    }
                    if (dataStart >= 0) {
                        String dataPart = part.substring(dataStart).trim();
                        // Entferne trailing boundary
                        if (dataPart.endsWith("--")) {
                            dataPart = dataPart.substring(0, dataPart.length() - 2).trim();
                        }
                        // Konvertiere zu Bytes (einfache Implementierung)
                        try {
                            fileData = dataPart.getBytes("ISO-8859-1");
                        } catch (java.io.UnsupportedEncodingException e) {
                            fileData = dataPart.getBytes();
                        }
                    }
                }
            }
            
            if (fileName == null || fileData == null) {
                String errorJson = "{\"error\":\"Dateiname oder Dateiinhalt nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Validiere Dateiendung
            String lowerFileName = fileName.toLowerCase();
            if (!lowerFileName.endsWith(".mid") && !lowerFileName.endsWith(".midi")) {
                String errorJson = "{\"error\":\"Nur .mid und .midi Dateien sind erlaubt\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Speichere Datei
            String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
            java.io.File midiDir = new java.io.File(sdCardPath + "/Turmtechnik/MIDI");
            if (!midiDir.exists()) {
                midiDir.mkdirs();
            }
            
            java.io.File midiFile = new java.io.File(midiDir, fileName);
            java.io.FileOutputStream fos = new java.io.FileOutputStream(midiFile);
            fos.write(fileData);
            fos.close();
            
            // Erstelle oder aktualisiere Konfiguration in DB
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            PlatinenDatabaseHelper.MidiConfig config = dbHelper.getMidiConfig(fileName);
            if (config == null) {
                config = new PlatinenDatabaseHelper.MidiConfig();
                config.dateiname = fileName;
                config.abspielgeschwindigkeit = 1.0;
                config.aktiv = true;
            }
            dbHelper.saveMidiConfig(config);
            
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("dateiname", fileName);
            result.put("id", config.id);
            
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Hochladen der MIDI-Datei", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Löscht eine MIDI-Datei-Konfiguration und die zugehörige Datei.
     */
    private SimpleHttpServer.HttpResponse handleDeleteMidiConfig(int id) {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.MidiConfig> configs = dbHelper.getAllMidiConfigs();
            PlatinenDatabaseHelper.MidiConfig config = null;
            
            for (PlatinenDatabaseHelper.MidiConfig c : configs) {
                if (c.id == id) {
                    config = c;
                    break;
                }
            }
            
            if (config == null) {
                String errorJson = "{\"error\":\"MIDI-Konfiguration mit ID " + id + " nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", errorJson);
            }
            
            // Lösche Datei
            String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
            java.io.File midiFile = new java.io.File(sdCardPath + "/Turmtechnik/MIDI", config.dateiname);
            if (midiFile.exists()) {
                midiFile.delete();
            }
            
            // Lösche aus DB
            dbHelper.deleteMidiConfig(id);
            
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("id", id);
            
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Löschen der MIDI-Konfiguration", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
