    /**
     * Lädt alle Melodien aus der Datenbank.
     */
    private SimpleHttpServer.HttpResponse handleGetMelodien() {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            List<PlatinenDatabaseHelper.Melodie> melodien = dbHelper.getAllMelodien();
            
            // Zähle Zeilen für jede Melodie
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            java.util.List<java.util.Map<String, Object>> melodienList = new java.util.ArrayList<>();
            
            for (PlatinenDatabaseHelper.Melodie melodie : melodien) {
                java.util.Map<String, Object> melodieMap = new java.util.HashMap<>();
                melodieMap.put("id", melodie.id);
                melodieMap.put("name", melodie.name);
                melodieMap.put("vorlaufMinuten", melodie.vorlaufMinuten);
                melodieMap.put("createdAt", melodie.createdAt);
                melodieMap.put("updatedAt", melodie.updatedAt);
                String dropdownVal = dbHelper.getConfigValue("melodie_dropdown_" + melodie.id);
                melodieMap.put("inDropdown", !"0".equals(dropdownVal));
                // Zähle Zeilen
                List<PlatinenDatabaseHelper.MelodieZeile> zeilen = dbHelper.getMelodieZeilen(melodie.id);
                melodieMap.put("anzahlZeilen", zeilen.size());
                melodienList.add(melodieMap);
            }
            
            result.put("melodien", melodienList);
            
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Abrufen der Melodien", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /** Setzt das Flag „In Benutzerprogramm-Dropdown anzeigen“ für eine Melodie (io_config). */
    private SimpleHttpServer.HttpResponse handlePutMelodieDropdown(int id, SimpleHttpServer.HttpRequest request) {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            if (dbHelper.getMelodie(id) == null) {
                return new SimpleHttpServer.HttpResponse(404, "application/json", "{\"error\":\"Melodie nicht gefunden\"}");
            }
            Map<?, ?> body = gson.fromJson(request.body, Map.class);
            if (body == null) body = new java.util.HashMap<>();
            Object inObj = body.get("inDropdown");
            boolean inDropdown = Boolean.TRUE.equals(inObj) || "true".equalsIgnoreCase(String.valueOf(inObj)) || "1".equals(String.valueOf(inObj));
            dbHelper.setConfigValue("melodie_dropdown_" + id, inDropdown ? "1" : "0");
            return new SimpleHttpServer.HttpResponse(200, "application/json", "{\"success\":true,\"inDropdown\":" + inDropdown + "}");
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Setzen Melodie-Dropdown", e);
            return new SimpleHttpServer.HttpResponse(500, "application/json", "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}");
        }
    }
    
