    /**
     * Exportiert eine Melodie als JSON-Datei (Download). Gleiches Format wie GET /api/melodien/:id,
     * kann mit „Melodie importieren (JSON)“ wieder eingelesen werden.
     */
    private SimpleHttpServer.HttpResponse handleGetMelodieExport(int id) {
        try {
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            PlatinenDatabaseHelper.Melodie melodie = dbHelper.getMelodie(id);
            if (melodie == null) {
                String errorJson = "{\"error\":\"Melodie mit ID " + id + " nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", errorJson);
            }
            List<PlatinenDatabaseHelper.MelodieZeile> zeilen = dbHelper.getMelodieZeilen(melodie.id);
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("name", melodie.name);
            result.put("vorlaufMinuten", melodie.vorlaufMinuten);
            result.put("zeilen", zeilen);
            String json = gson.toJson(result);
            String safeName = melodie.name.replaceAll("[^a-zA-Z0-9äöüÄÖÜß _-]", "_").trim();
            if (safeName.isEmpty()) safeName = "melodie";
            SimpleHttpServer.HttpResponse resp = new SimpleHttpServer.HttpResponse(200, "application/json; charset=UTF-8", json);
            resp.headers.put("Content-Disposition", "attachment; filename=\"" + safeName + ".json\"");
            return resp;
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Export der Melodie", e);
            String errorJson = "{\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "'") : "Export fehlgeschlagen") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }

    /**
     * Importiert eine Melodie aus einer JSON-Datei (gleiches Format wie Export).
     * Erstellt eine neue Melodie; wenn der Name bereits existiert, wird ein Fehler zurückgegeben.
     */
    private SimpleHttpServer.HttpResponse handlePostMelodieImportJson(SimpleHttpServer.HttpRequest request) {
        try {
            byte[] bodyBytes = request.bodyBytes;
            String jsonBody = request.body;
            if (bodyBytes != null && bodyBytes.length > 0) {
                jsonBody = new String(bodyBytes, "UTF-8");
            }
            if (jsonBody == null || jsonBody.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Keine JSON-Daten (Datei oder Body erforderlich)\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            @SuppressWarnings("unchecked")
            java.util.Map<String, Object> data = gson.fromJson(jsonBody, java.util.Map.class);
            if (data == null) {
                String errorJson = "{\"error\":\"Ungültiges JSON\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            String name = data.get("name") != null ? String.valueOf(data.get("name")).trim() : "";
            if (name.isEmpty()) {
                String errorJson = "{\"error\":\"Feld 'name' in der JSON-Datei fehlt oder ist leer\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            if (dbHelper.getMelodie(name) != null) {
                String errorJson = "{\"error\":\"Eine Melodie mit dem Namen \\\"" + name.replace("\"", "\\\"") + "\\\" existiert bereits. Bitte anderen Namen wählen oder bestehende Melodie löschen.\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            Object vorlaufObj = data.get("vorlaufMinuten");
            int vorlaufMinuten = vorlaufObj != null ? ((Number) vorlaufObj).intValue() : 0;
            PlatinenDatabaseHelper.Melodie melodie = new PlatinenDatabaseHelper.Melodie();
            melodie.name = name;
            melodie.vorlaufMinuten = vorlaufMinuten;
            melodie = dbHelper.saveMelodie(melodie);
            @SuppressWarnings("unchecked")
            List<Object> zeilenList = (List<Object>) data.get("zeilen");
            if (zeilenList != null) {
                for (int i = 0; i < zeilenList.size(); i++) {
                    Object zObj = zeilenList.get(i);
                    if (!(zObj instanceof java.util.Map)) continue;
                    @SuppressWarnings("unchecked")
                    java.util.Map<String, Object> zMap = (java.util.Map<String, Object>) zObj;
                    PlatinenDatabaseHelper.MelodieZeile zeile = new PlatinenDatabaseHelper.MelodieZeile();
                    zeile.id = 0;
                    zeile.melodieId = melodie.id;
                    zeile.zeileIndex = zMap.get("zeileIndex") != null ? ((Number) zMap.get("zeileIndex")).intValue() : i;
                    zeile.beginnZeit = getStringFromMap(zMap, "beginnZeit");
                    Object dauer = zMap.get("dauerSekunden");
                    zeile.dauerSekunden = (dauer != null && dauer instanceof Number) ? ((Number) dauer).doubleValue() : null;
                    zeile.zeiteinheit = getStringFromMap(zMap, "zeiteinheit");
                    zeile.kloeppelA = getStringFromMap(zMap, "kloeppelA");
                    zeile.kloeppelB = getStringFromMap(zMap, "kloeppelB");
                    zeile.kloeppelC = getStringFromMap(zMap, "kloeppelC");
                    zeile.kloeppelD = getStringFromMap(zMap, "kloeppelD");
                    zeile.kloeppelE = getStringFromMap(zMap, "kloeppelE");
                    zeile.kloeppelF = getStringFromMap(zMap, "kloeppelF");
                    zeile.kloeppelG = getStringFromMap(zMap, "kloeppelG");
                    zeile.kloeppelH = getStringFromMap(zMap, "kloeppelH");
                    zeile.kloeppelI = getStringFromMap(zMap, "kloeppelI");
                    zeile.kloeppelJ = getStringFromMap(zMap, "kloeppelJ");
                    zeile.kloeppelK = getStringFromMap(zMap, "kloeppelK");
                    zeile.kloeppelL = getStringFromMap(zMap, "kloeppelL");
                    zeile.kloeppelM = getStringFromMap(zMap, "kloeppelM");
                    zeile.kloeppelN = getStringFromMap(zMap, "kloeppelN");
                    zeile.kloeppelO = getStringFromMap(zMap, "kloeppelO");
                    zeile.kloeppelP = getStringFromMap(zMap, "kloeppelP");
                    zeile.soundMp3 = getStringFromMap(zMap, "soundMp3");
                    zeile.melodieXls = getStringFromMap(zMap, "melodieXls");
                    dbHelper.saveMelodieZeile(zeile);
                }
            }
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("message", "Melodie \"" + name + "\" importiert.");
            result.put("id", melodie.id);
            result.put("name", melodie.name);
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim JSON-Import der Melodie", e);
            String errorJson = "{\"error\":\"" + (e.getMessage() != null ? e.getMessage().replace("\"", "'") : "Import fehlgeschlagen") + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
