    /**
     * Importiert eine Melodie aus einer Excel-Datei.
     */
    private SimpleHttpServer.HttpResponse handlePostMelodieImport(SimpleHttpServer.HttpRequest request) {
        try {
            // Prüfe Content-Type
            String contentType = null;
            for (java.util.Map.Entry<String, String> entry : request.headers.entrySet()) {
                if (entry.getKey().equalsIgnoreCase("content-type")) {
                    contentType = entry.getValue();
                    break;
                }
            }
            
            if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                String errorJson = "{\"error\":\"Content-Type muss multipart/form-data sein\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Verwende bodyBytes für binäre Daten (wichtig für Excel-Dateien!)
            byte[] bodyBytes = request.bodyBytes;
            if (bodyBytes == null || bodyBytes.length == 0) {
                Log.e(TAG, "Melodie-Import: BodyBytes ist leer");
                String errorJson = "{\"error\":\"Keine Datei-Daten gefunden\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Extrahiere Boundary
            String boundary = null;
            if (contentType.contains("boundary=")) {
                int boundaryStart = contentType.indexOf("boundary=") + 9;
                String boundaryValue = contentType.substring(boundaryStart).trim();
                if (boundaryValue.startsWith("\"") && boundaryValue.endsWith("\"")) {
                    boundaryValue = boundaryValue.substring(1, boundaryValue.length() - 1);
                }
                boundary = "--" + boundaryValue;
            }
            
            if (boundary == null) {
                String errorJson = "{\"error\":\"Boundary nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            byte[] boundaryBytes = boundary.getBytes("ISO-8859-1");
            
            // Parse multipart/form-data aus Bytes
            String fileName = null;
            byte[] fileData = null;
            
            // Suche nach Boundary im Byte-Array (erste Part = zwischen erstem und zweitem Boundary)
            int boundaryIndex = 0;
            while (boundaryIndex < bodyBytes.length) {
                int nextBoundary = findBytes(bodyBytes, boundaryBytes, boundaryIndex + boundaryBytes.length);
                if (nextBoundary < 0) nextBoundary = bodyBytes.length;
                int partStart = boundaryIndex + boundaryBytes.length;
                int partEnd = nextBoundary;
                if (partStart < partEnd) {
                    byte[] partBytes = new byte[partEnd - partStart];
                    System.arraycopy(bodyBytes, partStart, partBytes, 0, partBytes.length);
                    String partString = new String(partBytes, "ISO-8859-1");
                    if (partString.contains("Content-Disposition") || partString.contains("content-disposition")) {
                        int filenameStart = partString.indexOf("filename=\"");
                        if (filenameStart >= 0) {
                            filenameStart += 10;
                            int filenameEnd = partString.indexOf("\"", filenameStart);
                            if (filenameEnd > filenameStart) {
                                fileName = partString.substring(filenameStart, filenameEnd);
                            }
                        }
                        int dataStartInString = partString.indexOf("\r\n\r\n");
                        if (dataStartInString < 0) dataStartInString = partString.indexOf("\n\n");
                        if (dataStartInString >= 0) {
                            int headerBytes = partString.substring(0, dataStartInString).getBytes("ISO-8859-1").length;
                            int skipBytes = (dataStartInString == partString.indexOf("\r\n\r\n")) ? 4 : 2;
                            int dataStartIndex = partStart + headerBytes + skipBytes;
                            int dataEndIndex = partEnd;
                            while (dataEndIndex > dataStartIndex && 
                                   (bodyBytes[dataEndIndex - 1] == '\r' || bodyBytes[dataEndIndex - 1] == '\n' || bodyBytes[dataEndIndex - 1] == ' ' || bodyBytes[dataEndIndex - 1] == '\t')) {
                                dataEndIndex--;
                            }
                            if (dataEndIndex > dataStartIndex) {
                                fileData = new byte[dataEndIndex - dataStartIndex];
                                System.arraycopy(bodyBytes, dataStartIndex, fileData, 0, fileData.length);
                            }
                        }
                    }
                }
                if (fileData != null && fileData.length > 0) break;
                boundaryIndex = nextBoundary;
            }
            if (fileName == null || fileData == null || fileData.length == 0) {
                Log.e(TAG, "Datei-Parsing fehlgeschlagen. fileName: " + fileName + ", fileData-Länge: " + (fileData != null ? fileData.length : 0));
                String errorJson = "{\"error\":\"Dateiname oder Dateiinhalt nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Validiere Dateiendung
            String lowerFileName = fileName.toLowerCase();
            if (!lowerFileName.endsWith(".xls")) {
                String errorJson = "{\"error\":\"Nur .xls Dateien sind erlaubt\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            // Speichere Datei temporär
            String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
            java.io.File tempDir = new java.io.File(sdCardPath + "/Turmtechnik/temp");
            if (!tempDir.exists()) {
                tempDir.mkdirs();
            }
            
            java.io.File tempFile = new java.io.File(tempDir, fileName);
            java.io.FileOutputStream fos = new java.io.FileOutputStream(tempFile);
            fos.write(fileData);
            fos.close();
            
            // Importiere Melodie
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            PlatinenDatabaseHelper.Melodie melodie = dbHelper.importMelodieFromExcel(tempFile.getAbsolutePath());
            
            // Lösche temporäre Datei
            tempFile.delete();
            
            if (melodie == null) {
                String errorJson = "{\"error\":\"Fehler beim Importieren der Melodie\"}";
                return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
            }
            
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("melodie", melodie);
            
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Importieren der Melodie", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Importiert alle Melodien aus dem Melodien-Ordner.
     */
    private SimpleHttpServer.HttpResponse handlePostMelodieImportAll() {
        try {
            String sdCardPath = android.os.Environment.getExternalStorageDirectory().getPath();
            java.io.File melodienDir = new java.io.File(sdCardPath + "/Turmtechnik/Melodien");
            
            if (!melodienDir.exists() || !melodienDir.isDirectory()) {
                String errorJson = "{\"error\":\"Melodien-Ordner nicht gefunden: " + melodienDir.getAbsolutePath() + "\"}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", errorJson);
            }
            
            java.io.File[] files = melodienDir.listFiles();
            if (files == null || files.length == 0) {
                String errorJson = "{\"error\":\"Keine Dateien im Melodien-Ordner gefunden\"}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            java.util.List<java.util.Map<String, Object>> importierteMelodien = new java.util.ArrayList<>();
            int erfolgreich = 0;
            int fehler = 0;
            
            for (java.io.File file : files) {
                if (file.isFile() && file.getName().toLowerCase().endsWith(".xls")) {
                    try {
                        PlatinenDatabaseHelper.Melodie melodie = dbHelper.importMelodieFromExcel(file.getAbsolutePath());
                        if (melodie != null) {
                            java.util.Map<String, Object> melodieInfo = new java.util.HashMap<>();
                            melodieInfo.put("name", melodie.name);
                            melodieInfo.put("id", melodie.id);
                            importierteMelodien.add(melodieInfo);
                            erfolgreich++;
                        } else {
                            fehler++;
                        }
                    } catch (Exception e) {
                        Log.e(TAG, "Fehler beim Importieren von " + file.getName(), e);
                        fehler++;
                    }
                }
            }
            
            java.util.Map<String, Object> result = new java.util.HashMap<>();
            result.put("success", true);
            result.put("erfolgreich", erfolgreich);
            result.put("fehler", fehler);
            result.put("importierteMelodien", importierteMelodien);
            
            String json = gson.toJson(result);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Importieren aller Melodien", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
