    /**
     * Erstellt eine neue Melodie-Zeile.
     */
    private SimpleHttpServer.HttpResponse handlePostMelodieZeile(SimpleHttpServer.HttpRequest request, int melodieId) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Request-Body erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            PlatinenDatabaseHelper.Melodie melodie = dbHelper.getMelodie(melodieId);
            
            if (melodie == null) {
                String errorJson = "{\"error\":\"Melodie mit ID " + melodieId + " nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper.MelodieZeile zeile = gson.fromJson(body, PlatinenDatabaseHelper.MelodieZeile.class);
            zeile.melodieId = melodieId;
            
            // Verwende zeileIndex und beginnZeit aus dem Request, falls vorhanden
            // Nur wenn nicht vorhanden, berechne sie automatisch
            if (zeile.zeileIndex < 0) {
                // Finde nächsten zeile_index
                List<PlatinenDatabaseHelper.MelodieZeile> vorhandeneZeilen = dbHelper.getMelodieZeilen(melodieId);
                int maxIndex = -1;
                for (PlatinenDatabaseHelper.MelodieZeile z : vorhandeneZeilen) {
                    if (z.zeileIndex > maxIndex) {
                        maxIndex = z.zeileIndex;
                    }
                }
                zeile.zeileIndex = maxIndex + 1;
            }
            
            // Verwende beginnZeit aus Request, falls vorhanden
            if (zeile.beginnZeit == null || zeile.beginnZeit.trim().isEmpty()) {
                // Berechne Beginn-Zeit basierend auf vorheriger Zeile
                // WICHTIG: Erste Zeile beginnt immer bei 00:00.00 (0 Minuten, 0 Sekunden)
                List<PlatinenDatabaseHelper.MelodieZeile> vorhandeneZeilen = dbHelper.getMelodieZeilen(melodieId);
                if (vorhandeneZeilen.isEmpty()) {
                    zeile.beginnZeit = "00:00.00";
                } else {
                    PlatinenDatabaseHelper.MelodieZeile letzteZeile = vorhandeneZeilen.get(vorhandeneZeilen.size() - 1);
                    double neueBeginnSekunden = parseZeit(letzteZeile.beginnZeit) + (letzteZeile.dauerSekunden != null ? letzteZeile.dauerSekunden : 0.0);
                    zeile.beginnZeit = formatZeit(neueBeginnSekunden);
                }
            }
            
            // Konvertiere Dauer basierend auf Zeiteinheit
            if (zeile.dauerSekunden != null && zeile.zeiteinheit != null) {
                if ("Min".equals(zeile.zeiteinheit)) {
                    // Dauer ist in Minuten, konvertiere zu Sekunden
                    zeile.dauerSekunden = zeile.dauerSekunden * 60.0;
                }
                // Bei "Sec" bleibt es wie es ist
            }
            
            zeile = dbHelper.saveMelodieZeile(zeile);
            
            String json = gson.toJson(zeile);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Erstellen der Melodie-Zeile", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
    /**
     * Aktualisiert eine Melodie-Zeile.
     */
    private SimpleHttpServer.HttpResponse handlePutMelodieZeile(SimpleHttpServer.HttpRequest request, int zeileId) {
        try {
            String body = request.body;
            if (body == null || body.trim().isEmpty()) {
                String errorJson = "{\"error\":\"Request-Body erforderlich\"}";
                return new SimpleHttpServer.HttpResponse(400, "application/json", errorJson);
            }
            
            PlatinenDatabaseHelper dbHelper = PlatinenDatabaseHelper.getInstance(context);
            
            // Lade vorhandene Zeile
            List<PlatinenDatabaseHelper.Melodie> melodien = dbHelper.getAllMelodien();
            PlatinenDatabaseHelper.MelodieZeile vorhandeneZeile = null;
            for (PlatinenDatabaseHelper.Melodie melodie : melodien) {
                List<PlatinenDatabaseHelper.MelodieZeile> zeilen = dbHelper.getMelodieZeilen(melodie.id);
                for (PlatinenDatabaseHelper.MelodieZeile z : zeilen) {
                    if (z.id == zeileId) {
                        vorhandeneZeile = z;
                        break;
                    }
                }
                if (vorhandeneZeile != null) break;
            }
            
            if (vorhandeneZeile == null) {
                String errorJson = "{\"error\":\"Melodie-Zeile mit ID " + zeileId + " nicht gefunden\"}";
                return new SimpleHttpServer.HttpResponse(404, "application/json", errorJson);
            }
            
            // Parse JSON
            java.util.Map<String, Object> data = gson.fromJson(body, java.util.Map.class);
            
            // Aktualisiere Felder
            if (data.containsKey("dauerSekunden")) {
                Object dauerObj = data.get("dauerSekunden");
                if (dauerObj != null) {
                    vorhandeneZeile.dauerSekunden = ((Number) dauerObj).doubleValue();
                }
            }
            
            if (data.containsKey("zeiteinheit")) {
                vorhandeneZeile.zeiteinheit = (String) data.get("zeiteinheit");
            }
            
            // Konvertiere Dauer basierend auf Zeiteinheit
            if (vorhandeneZeile.dauerSekunden != null && vorhandeneZeile.zeiteinheit != null) {
                // Wenn Zeiteinheit "Min" ist, muss der Wert in Minuten sein, konvertiere zu Sekunden
                if ("Min".equals(vorhandeneZeile.zeiteinheit)) {
                    // Der eingegebene Wert ist in Minuten, konvertiere zu Sekunden
                    // Aber warte: wenn wir den Wert aus der DB laden, ist er bereits in Sekunden
                    // Also müssen wir prüfen, ob der Wert bereits konvertiert wurde
                    // Für jetzt: Wenn Zeiteinheit "Min" ist und der Wert < 1000, dann ist er wahrscheinlich in Minuten
                    if (vorhandeneZeile.dauerSekunden < 1000) {
                        vorhandeneZeile.dauerSekunden = vorhandeneZeile.dauerSekunden * 60.0;
                    }
                }
            }
            
            // Aktualisiere Kloeppel-Felder
            String[] kloeppelFields = {"kloeppelA", "kloeppelB", "kloeppelC", "kloeppelD", "kloeppelE", 
                                       "kloeppelF", "kloeppelG", "kloeppelH", "kloeppelI", "kloeppelJ",
                                       "kloeppelK", "kloeppelL", "kloeppelM", "kloeppelN", "kloeppelO", "kloeppelP"};
            for (String field : kloeppelFields) {
                if (data.containsKey(field)) {
                    Object value = data.get(field);
                    try {
                        java.lang.reflect.Field f = vorhandeneZeile.getClass().getField(field);
                        f.set(vorhandeneZeile, value != null ? value.toString() : null);
                    } catch (Exception e) {
                        Log.w(TAG, "Fehler beim Setzen von " + field, e);
                    }
                }
            }
            
            if (data.containsKey("soundMp3")) {
                vorhandeneZeile.soundMp3 = (String) data.get("soundMp3");
            }
            
            if (data.containsKey("melodieXls")) {
                vorhandeneZeile.melodieXls = (String) data.get("melodieXls");
            }
            
            vorhandeneZeile = dbHelper.saveMelodieZeile(vorhandeneZeile);
            
            String json = gson.toJson(vorhandeneZeile);
            return new SimpleHttpServer.HttpResponse(200, "application/json", json);
        } catch (Exception e) {
            Log.e(TAG, "Fehler beim Aktualisieren der Melodie-Zeile", e);
            String errorJson = "{\"error\":\"" + e.getMessage() + "\"}";
            return new SimpleHttpServer.HttpResponse(500, "application/json", errorJson);
        }
    }
    
